INSERT INTO yijing_hexagram_dictum (name, dictum_text, label) VALUES
('Dictum_Hex_01', '元亨利贞。', '乾为天卦辞'),
('Dictum_Hex_02', '元亨，利牝马之贞。君子有攸往，先迷后得主利。西南得朋，东北丧朋。安贞吉。', '坤为地卦辞'),
('Dictum_Hex_03', '元亨利贞。勿用有攸往，利建侯。', '水雷屯卦辞'),
('Dictum_Hex_04', '亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎则不告。利贞。', '山水蒙卦辞'),
('Dictum_Hex_05', '有孚，光亨，贞吉。利涉大川。', '水天需卦辞'),
('Dictum_Hex_06', '有孚窒惕，中吉，终凶。利见大人，不利涉大川。', '天水讼卦辞'),
('Dictum_Hex_07', '贞，丈人吉，无咎。', '地水师卦辞'),
('Dictum_Hex_08', '吉。原筮元永贞，无咎。不宁方来，后夫凶。', '水地比卦辞'),
('Dictum_Hex_09', '亨。密云不雨，自我西郊。', '风天小畜卦辞'),
('Dictum_Hex_10', '履虎尾，不咥人，亨。', '天泽履卦辞'),
('Dictum_Hex_11', '小往大来，吉亨。', '地天泰卦辞'),
('Dictum_Hex_12', '否之匪人，不利君子贞，大往小来。', '天地否卦辞'),
('Dictum_Hex_13', '同人于野，亨。利涉大川，利君子贞。', '天火同人卦辞'),
('Dictum_Hex_14', '元亨。', '火天大有卦辞'),
('Dictum_Hex_15', '亨，君子有终。', '地山谦卦辞'),
('Dictum_Hex_16', '利建侯行师。', '雷地豫卦辞'),
('Dictum_Hex_17', '元亨利贞，无咎。', '泽雷随卦辞'),
('Dictum_Hex_18', '元亨，利涉大川。先甲三日，后甲三日。', '山风蛊卦辞'),
('Dictum_Hex_19', '元亨利贞。至于八月有凶。', '地泽临卦辞'),
('Dictum_Hex_20', '盥而不荐，有孚颙若。', '风地观卦辞'),
('Dictum_Hex_21', '亨。利用狱。', '火雷噬嗑卦辞'),
('Dictum_Hex_22', '亨。小利有攸往。', '山火贲卦辞'),
('Dictum_Hex_23', '不利有攸往。', '山地剥卦辞'),
('Dictum_Hex_24', '亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。', '地雷复卦辞'),
('Dictum_Hex_25', '元亨利贞。其匪正有眚，不利有攸往。', '天雷无妄卦辞'),
('Dictum_Hex_26', '利贞，不家食吉，利涉大川。', '山天大畜卦辞'),
('Dictum_Hex_27', '贞吉。观颐，自求口实。', '山雷颐卦辞'),
('Dictum_Hex_28', '栋桡，利有攸往，亨。', '泽风大过卦辞'),
('Dictum_Hex_29', '习坎，有孚，维心亨，行有尚。', '坎为水卦辞'),
('Dictum_Hex_30', '利贞，亨。畜牝牛，吉。', '离为火卦辞'),
('Dictum_Hex_31', '亨，利贞，取女吉。', '泽山咸卦辞'),
('Dictum_Hex_32', '亨，无咎，利贞，利有攸往。', '雷风恒卦辞'),
('Dictum_Hex_33', '亨，小利贞。', '天山遁卦辞'),
('Dictum_Hex_34', '利贞。', '雷天大壮卦辞'),
('Dictum_Hex_35', '康侯用锡马蕃庶，昼日三接。', '火地晋卦辞'),
('Dictum_Hex_36', '利艰贞。', '地火明夷卦辞'),
('Dictum_Hex_37', '利女贞。', '风火家人卦辞'),
('Dictum_Hex_38', '小事吉。', '火泽睽卦辞'),
('Dictum_Hex_39', '利西南，不利东北；利见大人，贞吉。', '水山蹇卦辞'),
('Dictum_Hex_40', '利西南，无所往，其来复吉。有攸往，夙吉。', '雷水解卦辞'),
('Dictum_Hex_41', '有孚，元吉，无咎，可贞，利有攸往。曷之用，二簋可用享。', '山泽损卦辞'),
('Dictum_Hex_42', '利有攸往，利涉大川。', '风雷益卦辞'),
('Dictum_Hex_43', '扬于王庭，孚号有厉。告自邑，不利即戎，利有攸往。', '泽天夬卦辞'),
('Dictum_Hex_44', '女壮，勿用取女。', '天风姤卦辞'),
('Dictum_Hex_45', '亨。王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往。', '泽地萃卦辞'),
('Dictum_Hex_46', '元亨，用见大人，勿恤，南征吉。', '地风升卦辞'),
('Dictum_Hex_47', '亨，贞，大人吉，无咎，有言不信。', '泽水困卦辞'),
('Dictum_Hex_48', '改邑不改井，无丧无得，往来井井。汔至，亦未繘井，羸其瓶，凶。', '水风井卦辞'),
('Dictum_Hex_49', '己日乃孚，元亨利贞，悔亡。', '泽火革卦辞'),
('Dictum_Hex_50', '元吉，亨。', '火风鼎卦辞'),
('Dictum_Hex_51', '亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。', '震为雷卦辞'),
('Dictum_Hex_52', '艮其背，不获其身，行其庭，不见其人，无咎。', '艮为山卦辞'),
('Dictum_Hex_53', '女归吉，利贞。', '风山渐卦辞'),
('Dictum_Hex_54', '征凶，无攸利。', '雷泽归妹卦辞'),
('Dictum_Hex_55', '亨，王假之，勿忧，宜日中。', '雷火丰卦辞'),
('Dictum_Hex_56', '小亨，旅贞吉。', '火山旅卦辞'),
('Dictum_Hex_57', '小亨，利有攸往，利见大人。', '巽为风卦辞'),
('Dictum_Hex_58', '亨，利贞。', '兑为泽卦辞'),
('Dictum_Hex_59', '亨。王假有庙，利涉大川，利贞。', '风水涣卦辞'),
('Dictum_Hex_60', '亨。苦节不可贞。', '水泽节卦辞'),
('Dictum_Hex_61', '豚鱼吉，利涉大川，利贞。', '风泽中孚卦辞'),
('Dictum_Hex_62', '亨，利贞，可小事，不可大事。飞鸟遗之音，不宜上宜下，大吉。', '雷山小过卦辞'),
('Dictum_Hex_63', '亨小，利贞，初吉终乱。', '水火既济卦辞'),
('Dictum_Hex_64', '亨，小狐汔济，濡其尾，无攸利。', '火水未济卦辞');
INSERT INTO yijing_line_dictum (name, position, dictum_text, label) VALUES
('LineDictum_01_1', 1, '初九：潜龙勿用。', '乾为天爻辞1'),
('LineDictum_01_2', 2, '九二：见龙在田，利见大人。', '乾为天爻辞2'),
('LineDictum_01_3', 3, '九三：君子终日乾乾，夕惕若厉，无咎。', '乾为天爻辞3'),
('LineDictum_01_4', 4, '九四：或跃在渊，无咎。', '乾为天爻辞4'),
('LineDictum_01_5', 5, '九五：飞龙在天，利见大人。', '乾为天爻辞5'),
('LineDictum_01_6', 6, '上九：亢龙有悔。', '乾为天爻辞6'),
('LineDictum_02_1', 1, '初六：履霜，坚冰至。', '坤为地爻辞1'),
('LineDictum_02_2', 2, '六二：直方大，不习无不利。', '坤为地爻辞2'),
('LineDictum_02_3', 3, '六三：含章可贞。或从王事，无成有终。', '坤为地爻辞3'),
('LineDictum_02_4', 4, '六四：括囊，无咎无誉。', '坤为地爻辞4'),
('LineDictum_02_5', 5, '六五：黄裳元吉。', '坤为地爻辞5'),
('LineDictum_02_6', 6, '上六：龙战于野，其血玄黄。', '坤为地爻辞6'),
('LineDictum_03_1', 1, '初九：磐桓，利居贞，利建侯。', '水雷屯爻辞1'),
('LineDictum_03_2', 2, '六二：屯如邅如，乘马班如。匪寇婚媾，女子贞不字，十年乃字。', '水雷屯爻辞2'),
('LineDictum_03_3', 3, '六三：即鹿无虞，惟入于林中。君子几不如舍，往吝。', '水雷屯爻辞3'),
('LineDictum_03_4', 4, '六四：乘马班如，求婚媾。往吉无不利。', '水雷屯爻辞4'),
('LineDictum_03_5', 5, '九五：屯其膏。小贞吉，大贞凶。', '水雷屯爻辞5'),
('LineDictum_03_6', 6, '上六：乘马班如，泣血涟如。', '水雷屯爻辞6'),
('LineDictum_04_1', 1, '初六：发蒙，利用刑人，用说桎梏，以往吝。', '山水蒙爻辞1'),
('LineDictum_04_2', 2, '九二：包蒙吉，纳妇吉，子克家。', '山水蒙爻辞2'),
('LineDictum_04_3', 3, '六三：勿用取女，见金夫，不有躬，无攸利。', '山水蒙爻辞3'),
('LineDictum_04_4', 4, '六四：困蒙，吝。', '山水蒙爻辞4'),
('LineDictum_04_5', 5, '六五：童蒙，吉。', '山水蒙爻辞5'),
('LineDictum_04_6', 6, '上九：击蒙。不利为寇，利御寇。', '山水蒙爻辞6'),
('LineDictum_05_1', 1, '初九：需于郊，利用恒，无咎。', '水天需爻辞1'),
('LineDictum_05_2', 2, '九二：需于沙，小有言，终吉。', '水天需爻辞2'),
('LineDictum_05_3', 3, '九三：需于泥，致寇至。', '水天需爻辞3'),
('LineDictum_05_4', 4, '六四：需于血，出自穴。', '水天需爻辞4'),
('LineDictum_05_5', 5, '九五：需于酒食，贞吉。', '水天需爻辞5'),
('LineDictum_05_6', 6, '上六：入于穴，有不速之客三人来，敬之终吉。', '水天需爻辞6'),
('LineDictum_06_1', 1, '初六：不永所事，小有言，终吉。', '天水讼爻辞1'),
('LineDictum_06_2', 2, '九二：不克讼，归而逋，其邑人三百户，无眚。', '天水讼爻辞2'),
('LineDictum_06_3', 3, '六三：食旧德，贞厉，终吉。或从王事，无成。', '天水讼爻辞3'),
('LineDictum_06_4', 4, '九四：不克讼，复即命渝，安贞吉。', '天水讼爻辞4'),
('LineDictum_06_5', 5, '九五：讼元吉。', '天水讼爻辞5'),
('LineDictum_06_6', 6, '上九：或锡之鞶带，终朝三褫之。', '天水讼爻辞6'),
('LineDictum_07_1', 1, '初六：师出以律，否臧凶。', '地水师爻辞1'),
('LineDictum_07_2', 2, '九二：在师中吉，无咎，王三锡命。', '地水师爻辞2'),
('LineDictum_07_3', 3, '六三：师或舆尸，凶。', '地水师爻辞3'),
('LineDictum_07_4', 4, '六四：师左次，无咎。', '地水师爻辞4'),
('LineDictum_07_5', 5, '六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。', '地水师爻辞5'),
('LineDictum_07_6', 6, '上六：大君有命，开国承家，小人勿用。', '地水师爻辞6'),
('LineDictum_08_1', 1, '初六：有孚比之，无咎。有孚盈缶，终来有它，吉。', '水地比爻辞1'),
('LineDictum_08_2', 2, '六二：比之自内，贞吉。', '水地比爻辞2'),
('LineDictum_08_3', 3, '六三：比之匪人。', '水地比爻辞3'),
('LineDictum_08_4', 4, '六四：外比之，贞吉。', '水地比爻辞4'),
('LineDictum_08_5', 5, '九五：显比，王用三驱，失前禽，邑人不诫，吉。', '水地比爻辞5'),
('LineDictum_08_6', 6, '上六：比之无首，凶。', '水地比爻辞6'),
('LineDictum_09_1', 1, '初九：复自道，何其咎？吉。', '风天小畜爻辞1'),
('LineDictum_09_2', 2, '九二：牵复，吉。', '风天小畜爻辞2'),
('LineDictum_09_3', 3, '九三：舆说辐，夫妻反目。', '风天小畜爻辞3'),
('LineDictum_09_4', 4, '六四：有孚，血去惕出，无咎。', '风天小畜爻辞4'),
('LineDictum_09_5', 5, '九五：有孚挛如，富以其邻。', '风天小畜爻辞5'),
('LineDictum_09_6', 6, '上九：既雨既处，尚德载，妇贞厉。月几望，君子征凶。', '风天小畜爻辞6'),
('LineDictum_10_1', 1, '初九：素履往，无咎。', '天泽履爻辞1'),
('LineDictum_10_2', 2, '九二：履道坦坦，幽人贞吉。', '天泽履爻辞2'),
('LineDictum_10_3', 3, '六三：眇能视，跛能履，履虎尾，咥人，凶。武人为于大君。', '天泽履爻辞3'),
('LineDictum_10_4', 4, '九四：履虎尾，愬愬终吉。', '天泽履爻辞4'),
('LineDictum_10_5', 5, '九五：夬履，贞厉。', '天泽履爻辞5'),
('LineDictum_10_6', 6, '上九：视履考祥，其旋元吉。', '天泽履爻辞6'),
('LineDictum_11_1', 1, '初九：拔茅茹，以其汇，征吉。', '地天泰爻辞1'),
('LineDictum_11_2', 2, '九二：包荒，用冯河，不遐遗，朋亡，得尚于中行。', '地天泰爻辞2'),
('LineDictum_11_3', 3, '九三：无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。', '地天泰爻辞3'),
('LineDictum_11_4', 4, '六四：翩翩不富，以其邻，不戒以孚。', '地天泰爻辞4'),
('LineDictum_11_5', 5, '六五：帝乙归妹，以祉元吉。', '地天泰爻辞5'),
('LineDictum_11_6', 6, '上六：城复于隍，勿用师。自邑告命，贞吝。', '地天泰爻辞6'),
('LineDictum_12_1', 1, '初六：拔茅茹，以其汇，贞吉亨。', '天地否爻辞1'),
('LineDictum_12_2', 2, '六二：包承，小人吉，大人否亨。', '天地否爻辞2'),
('LineDictum_12_3', 3, '六三：包羞。', '天地否爻辞3'),
('LineDictum_12_4', 4, '九四：有命无咎，畴离祉。', '天地否爻辞4'),
('LineDictum_12_5', 5, '九五：休否，大人吉。其亡其亡，系于苞桑。', '天地否爻辞5'),
('LineDictum_12_6', 6, '上九：倾否，先否后喜。', '天地否爻辞6'),
('LineDictum_13_1', 1, '初九：同人于门，无咎。', '天火同人爻辞1'),
('LineDictum_13_2', 2, '六二：同人于宗，吝。', '天火同人爻辞2'),
('LineDictum_13_3', 3, '九三：伏戎于莽，升其高陵，三岁不兴。', '天火同人爻辞3'),
('LineDictum_13_4', 4, '九四：乘其墉，弗克攻，吉。', '天火同人爻辞4'),
('LineDictum_13_5', 5, '九五：同人先号咷而后笑，大师克相遇。', '天火同人爻辞5'),
('LineDictum_13_6', 6, '上九：同人于郊，无悔。', '天火同人爻辞6'),
('LineDictum_14_1', 1, '初九：无交害，匪咎，艰则无咎。', '火天大有爻辞1'),
('LineDictum_14_2', 2, '九二：大车以载，有攸往，无咎。', '火天大有爻辞2'),
('LineDictum_14_3', 3, '九三：公用亨于天子，小人弗克。', '火天大有爻辞3'),
('LineDictum_14_4', 4, '九四：匪其彭，无咎。', '火天大有爻辞4'),
('LineDictum_14_5', 5, '六五：厥孚交如，威如，吉。', '火天大有爻辞5'),
('LineDictum_14_6', 6, '上九：自天佑之，吉无不利。', '火天大有爻辞6'),
('LineDictum_15_1', 1, '初六：谦谦君子，用涉大川，吉。', '地山谦爻辞1'),
('LineDictum_15_2', 2, '六二：鸣谦，贞吉。', '地山谦爻辞2'),
('LineDictum_15_3', 3, '九三：劳谦君子，有终吉。', '地山谦爻辞3'),
('LineDictum_15_4', 4, '六四：无不利，撝谦。', '地山谦爻辞4'),
('LineDictum_15_5', 5, '六五：不富以其邻，利用侵伐，无不利。', '地山谦爻辞5'),
('LineDictum_15_6', 6, '上六：鸣谦，利用行师，征邑国。', '地山谦爻辞6'),
('LineDictum_16_1', 1, '初六：鸣豫，凶。', '雷地豫爻辞1'),
('LineDictum_16_2', 2, '六二：介于石，不终日，贞吉。', '雷地豫爻辞2'),
('LineDictum_16_3', 3, '六三：盱豫，悔。迟有悔。', '雷地豫爻辞3'),
('LineDictum_16_4', 4, '九四：由豫，大有得。勿疑。朋盍簪。', '雷地豫爻辞4'),
('LineDictum_16_5', 5, '六五：贞疾，恒不死。', '雷地豫爻辞5'),
('LineDictum_16_6', 6, '上六：冥豫成，有渝无咎。', '雷地豫爻辞6'),
('LineDictum_17_1', 1, '初九：官有渝，贞吉。出门交有功。', '泽雷随爻辞1'),
('LineDictum_17_2', 2, '六二：系小子，失丈夫。', '泽雷随爻辞2'),
('LineDictum_17_3', 3, '六三：系丈夫，失小子。随有求得，利居贞。', '泽雷随爻辞3'),
('LineDictum_17_4', 4, '九四：随有获，贞凶。有孚在道，以明，何咎。', '泽雷随爻辞4'),
('LineDictum_17_5', 5, '九五：孚于嘉，吉。', '泽雷随爻辞5'),
('LineDictum_17_6', 6, '上六：拘系之，乃从维之。王用亨于西山。', '泽雷随爻辞6'),
('LineDictum_18_1', 1, '初六：干父之蛊，有子，考无咎，厉终吉。', '山风蛊爻辞1'),
('LineDictum_18_2', 2, '九二：干母之蛊，不可贞。', '山风蛊爻辞2'),
('LineDictum_18_3', 3, '九三：干父之蛊，小有悔，无大咎。', '山风蛊爻辞3'),
('LineDictum_18_4', 4, '六四：裕父之蛊，往见吝。', '山风蛊爻辞4'),
('LineDictum_18_5', 5, '六五：干父之蛊，用誉。', '山风蛊爻辞5'),
('LineDictum_18_6', 6, '上九：不事王侯，高尚其事。', '山风蛊爻辞6'),
('LineDictum_19_1', 1, '初九：咸临，贞吉。', '地泽临爻辞1'),
('LineDictum_19_2', 2, '九二：咸临，吉无不利。', '地泽临爻辞2'),
('LineDictum_19_3', 3, '六三：甘临，无攸利。既忧之，无咎。', '地泽临爻辞3'),
('LineDictum_19_4', 4, '六四：至临，无咎。', '地泽临爻辞4'),
('LineDictum_19_5', 5, '六五：知临，大君之宜，吉。', '地泽临爻辞5'),
('LineDictum_19_6', 6, '上六：敦临，吉无咎。', '地泽临爻辞6'),
('LineDictum_20_1', 1, '初六：童观，小人无咎，君子吝。', '风地观爻辞1'),
('LineDictum_20_2', 2, '六二：窥观，利女贞。', '风地观爻辞2'),
('LineDictum_20_3', 3, '六三：观我生，进退。', '风地观爻辞3'),
('LineDictum_20_4', 4, '六四：观国之光，利用宾于王。', '风地观爻辞4'),
('LineDictum_20_5', 5, '九五：观我生，君子无咎。', '风地观爻辞5'),
('LineDictum_20_6', 6, '上九：观其生，君子无咎。', '风地观爻辞6'),
('LineDictum_21_1', 1, '初九：屦校灭趾，无咎。', '火雷噬嗑爻辞1'),
('LineDictum_21_2', 2, '六二：噬肤灭鼻，无咎。', '火雷噬嗑爻辞2'),
('LineDictum_21_3', 3, '六三：噬腊肉，遇毒；小吝，无咎。', '火雷噬嗑爻辞3'),
('LineDictum_21_4', 4, '九四：噬干胏，得金矢，利艰贞，吉。', '火雷噬嗑爻辞4'),
('LineDictum_21_5', 5, '六五：噬干肉，得黄金，贞厉，无咎。', '火雷噬嗑爻辞5'),
('LineDictum_21_6', 6, '上九：何校灭耳，凶。', '火雷噬嗑爻辞6'),
('LineDictum_22_1', 1, '初九：贲其趾，舍车而徒。', '山火贲爻辞1'),
('LineDictum_22_2', 2, '六二：贲其须。', '山火贲爻辞2'),
('LineDictum_22_3', 3, '九三：贲如濡如，永贞吉。', '山火贲爻辞3'),
('LineDictum_22_4', 4, '六四：贲如皤如，白马翰如，匪寇婚媾。', '山火贲爻辞4'),
('LineDictum_22_5', 5, '六五：贲于丘园，束帛戋戋，吝，终吉。', '山火贲爻辞5'),
('LineDictum_22_6', 6, '上九：白贲，无咎。', '山火贲爻辞6'),
('LineDictum_23_1', 1, '初六：剥床以足，蔑贞凶。', '山地剥爻辞1'),
('LineDictum_23_2', 2, '六二：剥床以辨，蔑贞凶。', '山地剥爻辞2'),
('LineDictum_23_3', 3, '六三：剥之，无咎。', '山地剥爻辞3'),
('LineDictum_23_4', 4, '六四：剥床以肤，凶。', '山地剥爻辞4'),
('LineDictum_23_5', 5, '六五：贯鱼，以宫人宠，无不利。', '山地剥爻辞5'),
('LineDictum_23_6', 6, '上九：硕果不食，君子得舆，小人剥庐。', '山地剥爻辞6'),
('LineDictum_24_1', 1, '初九：不远复，无祗悔，元吉。', '地雷复爻辞1'),
('LineDictum_24_2', 2, '六二：休复，吉。', '地雷复爻辞2'),
('LineDictum_24_3', 3, '六三：频复，厉无咎。', '地雷复爻辞3'),
('LineDictum_24_4', 4, '六四：中行独复。', '地雷复爻辞4'),
('LineDictum_24_5', 5, '六五：敦复，无悔。', '地雷复爻辞5'),
('LineDictum_24_6', 6, '上六：迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征。', '地雷复爻辞6'),
('LineDictum_25_1', 1, '初九：无妄往，吉。', '天雷无妄爻辞1'),
('LineDictum_25_2', 2, '六二：不耕获，不菑畲，则利有攸往。', '天雷无妄爻辞2'),
('LineDictum_25_3', 3, '六三：无妄之灾，或系之牛，行人之得，邑人之灾。', '天雷无妄爻辞3'),
('LineDictum_25_4', 4, '九四：可贞，无咎。', '天雷无妄爻辞4'),
('LineDictum_25_5', 5, '九五：无妄之疾，勿药有喜。', '天雷无妄爻辞5'),
('LineDictum_25_6', 6, '上九：无妄行，有眚，无攸利。', '天雷无妄爻辞6'),
('LineDictum_26_1', 1, '初九：有厉利已。', '山天大畜爻辞1'),
('LineDictum_26_2', 2, '九二：舆说輹。', '山天大畜爻辞2'),
('LineDictum_26_3', 3, '九三：良马逐，利艰贞。曰闲舆卫，利有攸往。', '山天大畜爻辞3'),
('LineDictum_26_4', 4, '六四：童牛之牿，元吉。', '山天大畜爻辞4'),
('LineDictum_26_5', 5, '六五：豮豕之牙，吉。', '山天大畜爻辞5'),
('LineDictum_26_6', 6, '上九：何天之衢，亨。', '山天大畜爻辞6'),
('LineDictum_27_1', 1, '初九：舍尔灵龟，观我朵颐，凶。', '山雷颐爻辞1'),
('LineDictum_27_2', 2, '六二：颠颐，拂经，于丘颐，征凶。', '山雷颐爻辞2'),
('LineDictum_27_3', 3, '六三：拂颐，贞凶，十年勿用，无攸利。', '山雷颐爻辞3'),
('LineDictum_27_4', 4, '六四：颠颐吉，虎视眈眈，其欲逐逐，无咎。', '山雷颐爻辞4'),
('LineDictum_27_5', 5, '六五：拂经，居贞吉，不可涉大川。', '山雷颐爻辞5'),
('LineDictum_27_6', 6, '上九：由颐，厉吉，利涉大川。', '山雷颐爻辞6'),
('LineDictum_28_1', 1, '初六：藉用白茅，无咎。', '泽风大过爻辞1'),
('LineDictum_28_2', 2, '九二：枯杨生稊，老夫得其女妻，无不利。', '泽风大过爻辞2'),
('LineDictum_28_3', 3, '九三：栋桡，凶。', '泽风大过爻辞3'),
('LineDictum_28_4', 4, '九四：栋隆，吉；有它吝。', '泽风大过爻辞4'),
('LineDictum_28_5', 5, '九五：枯杨生华，老妇得其士夫，无咎无誉。', '泽风大过爻辞5'),
('LineDictum_28_6', 6, '上六：过涉灭顶，凶，无咎。', '泽风大过爻辞6'),
('LineDictum_29_1', 1, '初六：习坎，入于坎窞，凶。', '坎为水爻辞1'),
('LineDictum_29_2', 2, '九二：坎有险，求小得。', '坎为水爻辞2'),
('LineDictum_29_3', 3, '六三：来之坎坎，险且枕，入于坎窞，勿用。', '坎为水爻辞3'),
('LineDictum_29_4', 4, '六四：樽酒簋贰，用缶，纳约自牖，终无咎。', '坎为水爻辞4'),
('LineDictum_29_5', 5, '九五：坎不盈，祗既平，无咎。', '坎为水爻辞5'),
('LineDictum_29_6', 6, '上六：系用徽纆，寘于丛棘，三岁不得，凶。', '坎为水爻辞6'),
('LineDictum_30_1', 1, '初九：履错然，敬之无咎。', '离为火爻辞1'),
('LineDictum_30_2', 2, '六二：黄离，元吉。', '离为火爻辞2'),
('LineDictum_30_3', 3, '九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶。', '离为火爻辞3'),
('LineDictum_30_4', 4, '九四：突如其来如，焚如，死如，弃如。', '离为火爻辞4'),
('LineDictum_30_5', 5, '六五：出涕沱若，戚嗟若，吉。', '离为火爻辞5'),
('LineDictum_30_6', 6, '上九：王用出征，有嘉折首，获匪其丑，无咎。', '离为火爻辞6'),
('LineDictum_31_1', 1, '初六：咸其拇。', '泽山咸爻辞1'),
('LineDictum_31_2', 2, '六二：咸其腓，凶，居吉。', '泽山咸爻辞2'),
('LineDictum_31_3', 3, '九三：咸其股，执其随，往吝。', '泽山咸爻辞3'),
('LineDictum_31_4', 4, '九四：贞吉悔亡，憧憧往来，朋从尔思。', '泽山咸爻辞4'),
('LineDictum_31_5', 5, '九五：咸其脢，无悔。', '泽山咸爻辞5'),
('LineDictum_31_6', 6, '上六：咸其辅颊舌。', '泽山咸爻辞6'),
('LineDictum_32_1', 1, '初六：浚恒，贞凶，无攸利。', '雷风恒爻辞1'),
('LineDictum_32_2', 2, '九二：悔亡。', '雷风恒爻辞2'),
('LineDictum_32_3', 3, '九三：不恒其德，或承之羞，贞吝。', '雷风恒爻辞3'),
('LineDictum_32_4', 4, '九四：田无禽。', '雷风恒爻辞4'),
('LineDictum_32_5', 5, '六五：恒其德，贞，妇人吉，夫子凶。', '雷风恒爻辞5'),
('LineDictum_32_6', 6, '上六：振恒，凶。', '雷风恒爻辞6'),
('LineDictum_33_1', 1, '初六：遁尾，厉，勿用有攸往。', '天山遁爻辞1'),
('LineDictum_33_2', 2, '六二：执之用黄牛之革，莫之胜说。', '天山遁爻辞2'),
('LineDictum_33_3', 3, '九三：系遁，有疾厉，畜臣妾吉。', '天山遁爻辞3'),
('LineDictum_33_4', 4, '九四：好遁，君子吉，小人否。', '天山遁爻辞4'),
('LineDictum_33_5', 5, '九五：嘉遁，贞吉。', '天山遁爻辞5'),
('LineDictum_33_6', 6, '上九：肥遁，无不利。', '天山遁爻辞6'),
('LineDictum_34_1', 1, '初九：壮于趾，征凶，有孚。', '雷天大壮爻辞1'),
('LineDictum_34_2', 2, '九二：贞吉。', '雷天大壮爻辞2'),
('LineDictum_34_3', 3, '九三：小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。', '雷天大壮爻辞3'),
('LineDictum_34_4', 4, '九四：贞吉悔亡，藩决不羸，壮于大舆之輹。', '雷天大壮爻辞4'),
('LineDictum_34_5', 5, '六五：丧羊于易，无悔。', '雷天大壮爻辞5'),
('LineDictum_34_6', 6, '上六：羝羊触藩，不能退，不能遂，无攸利，艰则吉。', '雷天大壮爻辞6'),
('LineDictum_35_1', 1, '初六：晋如摧如，贞吉。罔孚，裕无咎。', '火地晋爻辞1'),
('LineDictum_35_2', 2, '六二：晋如愁如，贞吉。受兹介福，于其王母。', '火地晋爻辞2'),
('LineDictum_35_3', 3, '六三：众允，悔亡。', '火地晋爻辞3'),
('LineDictum_35_4', 4, '九四：晋如鼫鼠，贞厉。', '火地晋爻辞4'),
('LineDictum_35_5', 5, '六五：悔亡，失得勿恤，往吉无不利。', '火地晋爻辞5'),
('LineDictum_35_6', 6, '上九：晋其角，维用伐邑，厉吉无咎，贞吝。', '火地晋爻辞6'),
('LineDictum_36_1', 1, '初九：明夷于飞，垂其翼。君子于行，三日不食，有攸往，主人有言。', '地火明夷爻辞1'),
('LineDictum_36_2', 2, '六二：明夷，夷于左股，用拯马壮，吉。', '地火明夷爻辞2'),
('LineDictum_36_3', 3, '九三：明夷于南狩，得其大首，不可疾贞。', '地火明夷爻辞3'),
('LineDictum_36_4', 4, '六四：入于左腹，获明夷之心，于出门庭。', '地火明夷爻辞4'),
('LineDictum_36_5', 5, '六五：箕子之明夷，利贞。', '地火明夷爻辞5'),
('LineDictum_36_6', 6, '上六：不明晦，初登于天，后入于地。', '地火明夷爻辞6'),
('LineDictum_37_1', 1, '初九：闲有家，悔亡。', '风火家人爻辞1'),
('LineDictum_37_2', 2, '六二：无攸遂，在中馈，贞吉。', '风火家人爻辞2'),
('LineDictum_37_3', 3, '九三：家人嗃嗃，悔厉吉；妇子嘻嘻，终吝。', '风火家人爻辞3'),
('LineDictum_37_4', 4, '六四：富家，大吉。', '风火家人爻辞4'),
('LineDictum_37_5', 5, '九五：王假有家，勿恤，吉。', '风火家人爻辞5'),
('LineDictum_37_6', 6, '上九：有孚威如，终吉。', '风火家人爻辞6'),
('LineDictum_38_1', 1, '初九：悔亡。丧马勿逐，自复。见恶人，无咎。', '火泽睽爻辞1'),
('LineDictum_38_2', 2, '九二：遇主于巷，无咎。', '火泽睽爻辞2'),
('LineDictum_38_3', 3, '六三：见舆曳，其牛掣，其人天且劓，无初有终。', '火泽睽爻辞3'),
('LineDictum_38_4', 4, '九四：睽孤，遇元夫，交孚，厉无咎。', '火泽睽爻辞4'),
('LineDictum_38_5', 5, '六五：悔亡，厥宗噬肤，往何咎。', '火泽睽爻辞5'),
('LineDictum_38_6', 6, '上九：睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉。', '火泽睽爻辞6'),
('LineDictum_39_1', 1, '初六：往蹇，来誉。', '水山蹇爻辞1'),
('LineDictum_39_2', 2, '六二：王臣蹇蹇，匪躬之故。', '水山蹇爻辞2'),
('LineDictum_39_3', 3, '九三：往蹇来反。', '水山蹇爻辞3'),
('LineDictum_39_4', 4, '六四：往蹇来连。', '水山蹇爻辞4'),
('LineDictum_39_5', 5, '九五：大蹇朋来。', '水山蹇爻辞5'),
('LineDictum_39_6', 6, '上六：往蹇来硕，吉；利见大人。', '水山蹇爻辞6'),
('LineDictum_40_1', 1, '初六：无咎。', '雷水解爻辞1'),
('LineDictum_40_2', 2, '九二：田获三狐，得黄矢，贞吉。', '雷水解爻辞2'),
('LineDictum_40_3', 3, '六三：负且乘，致寇至，贞吝。', '雷水解爻辞3'),
('LineDictum_40_4', 4, '九四：解而拇，朋至斯孚。', '雷水解爻辞4'),
('LineDictum_40_5', 5, '六五：君子维有解，吉；有孚于小人。', '雷水解爻辞5'),
('LineDictum_40_6', 6, '上六：公用射隼于高墉之上，获之，无不利。', '雷水解爻辞6'),
('LineDictum_41_1', 1, '初九：已事遄往，无咎，酌损之。', '山泽损爻辞1'),
('LineDictum_41_2', 2, '九二：利贞，征凶，弗损益之。', '山泽损爻辞2'),
('LineDictum_41_3', 3, '六三：三人行，则损一人；一人行，则得其友。', '山泽损爻辞3'),
('LineDictum_41_4', 4, '六四：损其疾，使遄有喜，无咎。', '山泽损爻辞4'),
('LineDictum_41_5', 5, '六五：或益之十朋之龟，弗克违，元吉。', '山泽损爻辞5'),
('LineDictum_41_6', 6, '上九：弗损益之，无咎，贞吉，利有攸往，得臣无家。', '山泽损爻辞6'),
('LineDictum_42_1', 1, '初九：利用为大作，元吉，无咎。', '风雷益爻辞1'),
('LineDictum_42_2', 2, '六二：或益之十朋之龟，弗克违，永贞吉。王用享于帝，吉。', '风雷益爻辞2'),
('LineDictum_42_3', 3, '六三：益之用凶事，无咎。有孚中行，告公用圭。', '风雷益爻辞3'),
('LineDictum_42_4', 4, '六四：中行，告公从，利用为依迁国。', '风雷益爻辞4'),
('LineDictum_42_5', 5, '九五：有孚惠心，勿问元吉。有孚惠我德。', '风雷益爻辞5'),
('LineDictum_42_6', 6, '上九：莫益之，或击之，立心勿恒，凶。', '风雷益爻辞6'),
('LineDictum_43_1', 1, '初九：壮于前趾，往不胜为咎。', '泽天夬爻辞1'),
('LineDictum_43_2', 2, '九二：惕号，莫夜有戎，勿恤。', '泽天夬爻辞2'),
('LineDictum_43_3', 3, '九三：壮于頄，有凶。君子夬夬，独行遇雨，若濡有愠，无咎。', '泽天夬爻辞3'),
('LineDictum_43_4', 4, '九四：臀无肤，其行次且。牵羊悔亡，闻言不信。', '泽天夬爻辞4'),
('LineDictum_43_5', 5, '九五：苋陆夬夬，中行无咎。', '泽天夬爻辞5'),
('LineDictum_43_6', 6, '上六：无号，终有凶。', '泽天夬爻辞6'),
('LineDictum_44_1', 1, '初六：系于金柅，贞吉。有攸往，见凶，羸豕孚蹢躅。', '天风姤爻辞1'),
('LineDictum_44_2', 2, '九二：包有鱼，无咎，不利宾。', '天风姤爻辞2'),
('LineDictum_44_3', 3, '九三：臀无肤，其行次且，厉，无大咎。', '天风姤爻辞3'),
('LineDictum_44_4', 4, '九四：包无鱼，起凶。', '天风姤爻辞4'),
('LineDictum_44_5', 5, '九五：以杞包瓜，含章，有陨自天。', '天风姤爻辞5'),
('LineDictum_44_6', 6, '上九：姤其角，吝，无咎。', '天风姤爻辞6'),
('LineDictum_45_1', 1, '初六：有孚不终，乃乱乃萃，若号，一握为笑，勿恤，往无咎。', '泽地萃爻辞1'),
('LineDictum_45_2', 2, '六二：引吉，无咎，孚乃利用禴。', '泽地萃爻辞2'),
('LineDictum_45_3', 3, '六三：萃如嗟如，无攸利，往无咎，小吝。', '泽地萃爻辞3'),
('LineDictum_45_4', 4, '九四：大吉，无咎。', '泽地萃爻辞4'),
('LineDictum_45_5', 5, '九五：萃有位，无咎。匪孚，元永贞，悔亡。', '泽地萃爻辞5'),
('LineDictum_45_6', 6, '上六：赍咨涕洟，无咎。', '泽地萃爻辞6'),
('LineDictum_46_1', 1, '初六：允升，大吉。', '地风升爻辞1'),
('LineDictum_46_2', 2, '九二：孚乃利用禴，无咎。', '地风升爻辞2'),
('LineDictum_46_3', 3, '九三：升虚邑。', '地风升爻辞3'),
('LineDictum_46_4', 4, '六四：王用亨于岐山，吉无咎。', '地风升爻辞4'),
('LineDictum_46_5', 5, '六五：贞吉，升阶。', '地风升爻辞5'),
('LineDictum_46_6', 6, '上六：冥升，利于不息之贞。', '地风升爻辞6'),
('LineDictum_47_1', 1, '初六：臀困于株木，入于幽谷，三岁不觌。', '泽水困爻辞1'),
('LineDictum_47_2', 2, '九二：困于酒食，朱绂方来，利用亨祀，征凶，无咎。', '泽水困爻辞2'),
('LineDictum_47_3', 3, '六三：困于石，据于蒺藜，入于其宫，不见其妻，凶。', '泽水困爻辞3'),
('LineDictum_47_4', 4, '九四：来徐徐，困于金车，吝，有终。', '泽水困爻辞4'),
('LineDictum_47_5', 5, '九五：劓刖，困于赤绂，乃徐有说，利用祭祀。', '泽水困爻辞5'),
('LineDictum_47_6', 6, '上六：困于葛藟，于臲卼，曰动悔。有悔，征吉。', '泽水困爻辞6'),
('LineDictum_48_1', 1, '初六：井泥不食，旧井无禽。', '水风井爻辞1'),
('LineDictum_48_2', 2, '九二：井谷射鲋，瓮敝漏。', '水风井爻辞2'),
('LineDictum_48_3', 3, '九三：井渫不食，为我心恻，可用汲，王明，并受其福。', '水风井爻辞3'),
('LineDictum_48_4', 4, '六四：井甃，无咎。', '水风井爻辞4'),
('LineDictum_48_5', 5, '九五：井洌，寒泉食。', '水风井爻辞5'),
('LineDictum_48_6', 6, '上六：井收勿幕，有孚元吉。', '水风井爻辞6'),
('LineDictum_49_1', 1, '初九：巩用黄牛之革。', '泽火革爻辞1'),
('LineDictum_49_2', 2, '六二：己日乃革之，征吉，无咎。', '泽火革爻辞2'),
('LineDictum_49_3', 3, '九三：征凶，贞厉，革言三就，有孚。', '泽火革爻辞3'),
('LineDictum_49_4', 4, '九四：悔亡，有孚改命，吉。', '泽火革爻辞4'),
('LineDictum_49_5', 5, '九五：大人虎变，未占有孚。', '泽火革爻辞5'),
('LineDictum_49_6', 6, '上六：君子豹变，小人革面，征凶，居贞吉。', '泽火革爻辞6'),
('LineDictum_50_1', 1, '初六：鼎颠趾，利出否，得妾以其子，无咎。', '火风鼎爻辞1'),
('LineDictum_50_2', 2, '九二：鼎有实，我仇有疾，不我能即，吉。', '火风鼎爻辞2'),
('LineDictum_50_3', 3, '九三：鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。', '火风鼎爻辞3'),
('LineDictum_50_4', 4, '九四：鼎折足，覆公餗，其形渥，凶。', '火风鼎爻辞4'),
('LineDictum_50_5', 5, '六五：鼎黄耳金铉，利贞。', '火风鼎爻辞5'),
('LineDictum_50_6', 6, '上九：鼎玉铉，大吉，无不利。', '火风鼎爻辞6'),
('LineDictum_51_1', 1, '初九：震来虩虩，后笑言哑哑，吉。', '震为雷爻辞1'),
('LineDictum_51_2', 2, '六二：震来厉，亿丧贝，跻于九陵，勿逐，七日得。', '震为雷爻辞2'),
('LineDictum_51_3', 3, '六三：震苏苏，震行无眚。', '震为雷爻辞3'),
('LineDictum_51_4', 4, '九四：震遂泥。', '震为雷爻辞4'),
('LineDictum_51_5', 5, '六五：震往来厉，亿无丧，有事。', '震为雷爻辞5'),
('LineDictum_51_6', 6, '上六：震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。', '震为雷爻辞6'),
('LineDictum_52_1', 1, '初六：艮其趾，无咎，利永贞。', '艮为山爻辞1'),
('LineDictum_52_2', 2, '六二：艮其腓，不拯其随，其心不快。', '艮为山爻辞2'),
('LineDictum_52_3', 3, '九三：艮其限，列其夤，厉薰心。', '艮为山爻辞3'),
('LineDictum_52_4', 4, '六四：艮其身，无咎。', '艮为山爻辞4'),
('LineDictum_52_5', 5, '六五：艮其辅，言有序，悔亡。', '艮为山爻辞5'),
('LineDictum_52_6', 6, '上九：敦艮，吉。', '艮为山爻辞6'),
('LineDictum_53_1', 1, '初六：鸿渐于干，小子厉，有言，无咎。', '风山渐爻辞1'),
('LineDictum_53_2', 2, '六二：鸿渐于磐，饮食衎衎，吉。', '风山渐爻辞2'),
('LineDictum_53_3', 3, '九三：鸿渐于陆，夫征不复，妇孕不育，凶；利御寇。', '风山渐爻辞3'),
('LineDictum_53_4', 4, '六四：鸿渐于木，或得其桷，无咎。', '风山渐爻辞4'),
('LineDictum_53_5', 5, '九五：鸿渐于陵，妇三岁不孕，终莫之胜，吉。', '风山渐爻辞5'),
('LineDictum_53_6', 6, '上九：鸿渐于陆，其羽可用为仪，吉。', '风山渐爻辞6'),
('LineDictum_54_1', 1, '初九：归妹以娣，跛能履，征吉。', '雷泽归妹爻辞1'),
('LineDictum_54_2', 2, '九二：眇能视，利幽人之贞。', '雷泽归妹爻辞2'),
('LineDictum_54_3', 3, '六三：归妹以须，反归以娣。', '雷泽归妹爻辞3'),
('LineDictum_54_4', 4, '九四：归妹愆期，迟归有时。', '雷泽归妹爻辞4'),
('LineDictum_54_5', 5, '六五：帝乙归妹，其君之袂，不如其娣之袂良，月几望，吉。', '雷泽归妹爻辞5'),
('LineDictum_54_6', 6, '上六：女承筐无实，士刲羊无血，无攸利。', '雷泽归妹爻辞6'),
('LineDictum_55_1', 1, '初九：遇其配主，虽旬无咎，往有尚。', '雷火丰爻辞1'),
('LineDictum_55_2', 2, '六二：丰其蔀，日中见斗，往得疑疾，有孚发若，吉。', '雷火丰爻辞2'),
('LineDictum_55_3', 3, '九三：丰其沛，日中见沫，折其右肱，无咎。', '雷火丰爻辞3'),
('LineDictum_55_4', 4, '九四：丰其蔀，日中见斗，遇其夷主，吉。', '雷火丰爻辞4'),
('LineDictum_55_5', 5, '六五：来章，有庆誉，吉。', '雷火丰爻辞5'),
('LineDictum_55_6', 6, '上六：丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶。', '雷火丰爻辞6'),
('LineDictum_56_1', 1, '初六：旅琐琐，斯其所取灾。', '火山旅爻辞1'),
('LineDictum_56_2', 2, '六二：旅即次，怀其资，得童仆贞。', '火山旅爻辞2'),
('LineDictum_56_3', 3, '九三：旅焚其次，丧其童仆，贞厉。', '火山旅爻辞3'),
('LineDictum_56_4', 4, '九四：旅于处，得其资斧，我心不快。', '火山旅爻辞4'),
('LineDictum_56_5', 5, '六五：射雉一矢亡，终以誉命。', '火山旅爻辞5'),
('LineDictum_56_6', 6, '上九：鸟焚其巢，旅人先笑后号咷。丧牛于易，凶。', '火山旅爻辞6'),
('LineDictum_57_1', 1, '初六：进退，利武人之贞。', '巽为风爻辞1'),
('LineDictum_57_2', 2, '九二：巽在床下，用史巫纷若，吉无咎。', '巽为风爻辞2'),
('LineDictum_57_3', 3, '九三：频巽，吝。', '巽为风爻辞3'),
('LineDictum_57_4', 4, '六四：悔亡，田获三品。', '巽为风爻辞4'),
('LineDictum_57_5', 5, '九五：贞吉悔亡，无不利。无初有终，先庚三日，后庚三日，吉。', '巽为风爻辞5'),
('LineDictum_57_6', 6, '上九：巽在床下，丧其资斧，贞凶。', '巽为风爻辞6'),
('LineDictum_58_1', 1, '初九：和兑，吉。', '兑为泽爻辞1'),
('LineDictum_58_2', 2, '九二：孚兑，吉，悔亡。', '兑为泽爻辞2'),
('LineDictum_58_3', 3, '六三：来兑，凶。', '兑为泽爻辞3'),
('LineDictum_58_4', 4, '九四：商兑未宁，介疾有喜。', '兑为泽爻辞4'),
('LineDictum_58_5', 5, '九五：孚于剥，有厉。', '兑为泽爻辞5'),
('LineDictum_58_6', 6, '上六：引兑。', '兑为泽爻辞6'),
('LineDictum_59_1', 1, '初六：用拯马壮，吉。', '风水涣爻辞1'),
('LineDictum_59_2', 2, '九二：涣奔其机，悔亡。', '风水涣爻辞2'),
('LineDictum_59_3', 3, '六三：涣其躬，无悔。', '风水涣爻辞3'),
('LineDictum_59_4', 4, '六四：涣其群，元吉。涣有丘，匪夷所思。', '风水涣爻辞4'),
('LineDictum_59_5', 5, '九五：涣汗其大号，涣王居，无咎。', '风水涣爻辞5'),
('LineDictum_59_6', 6, '上九：涣其血，去逖出，无咎。', '风水涣爻辞6'),
('LineDictum_60_1', 1, '初九：不出户庭，无咎。', '水泽节爻辞1'),
('LineDictum_60_2', 2, '九二：不出门庭，凶。', '水泽节爻辞2'),
('LineDictum_60_3', 3, '六三：不节若，则嗟若，无咎。', '水泽节爻辞3'),
('LineDictum_60_4', 4, '六四：安节，亨。', '水泽节爻辞4'),
('LineDictum_60_5', 5, '九五：甘节，吉；往有尚。', '水泽节爻辞5'),
('LineDictum_60_6', 6, '上六：苦节，贞凶，悔亡。', '水泽节爻辞6'),
('LineDictum_61_1', 1, '初九：虞吉，有它不燕。', '风泽中孚爻辞1'),
('LineDictum_61_2', 2, '九二：鸣鹤在阴，其子和之。我有好爵，吾与尔靡之。', '风泽中孚爻辞2'),
('LineDictum_61_3', 3, '六三：得敌，或鼓或罢，或泣或歌。', '风泽中孚爻辞3'),
('LineDictum_61_4', 4, '六四：月几望，马匹亡，无咎。', '风泽中孚爻辞4'),
('LineDictum_61_5', 5, '九五：有孚挛如，无咎。', '风泽中孚爻辞5'),
('LineDictum_61_6', 6, '上九：翰音登于天，贞凶。', '风泽中孚爻辞6'),
('LineDictum_62_1', 1, '初六：飞鸟以凶。', '雷山小过爻辞1'),
('LineDictum_62_2', 2, '六二：过其祖，遇其妣；不及其君，遇其臣；无咎。', '雷山小过爻辞2'),
('LineDictum_62_3', 3, '九三：弗过防之，从或戕之，凶。', '雷山小过爻辞3'),
('LineDictum_62_4', 4, '九四：无咎，弗过遇之。往厉必戒，勿用永贞。', '雷山小过爻辞4'),
('LineDictum_62_5', 5, '六五：密云不雨，自我西郊，公弋取彼在穴。', '雷山小过爻辞5'),
('LineDictum_62_6', 6, '上六：弗遇过之，飞鸟离之，凶，是谓灾眚。', '雷山小过爻辞6'),
('LineDictum_63_1', 1, '初九：曳其轮，濡其尾，无咎。', '水火既济爻辞1'),
('LineDictum_63_2', 2, '六二：妇丧其茀，勿逐，七日得。', '水火既济爻辞2'),
('LineDictum_63_3', 3, '九三：高宗伐鬼方，三年克之，小人勿用。', '水火既济爻辞3'),
('LineDictum_63_4', 4, '六四：繻有衣袽，终日戒。', '水火既济爻辞4'),
('LineDictum_63_5', 5, '九五：东邻杀牛，不如西邻之禴祭，实受其福。', '水火既济爻辞5'),
('LineDictum_63_6', 6, '上六：濡其首，厉。', '水火既济爻辞6'),
('LineDictum_64_1', 1, '初六：濡其尾，吝。', '火水未济爻辞1'),
('LineDictum_64_2', 2, '九二：曳其轮，贞吉。', '火水未济爻辞2'),
('LineDictum_64_3', 3, '六三：未济，征凶，利涉大川。', '火水未济爻辞3'),
('LineDictum_64_4', 4, '九四：贞吉，悔亡，震用伐鬼方，三年有赏于大国。', '火水未济爻辞4'),
('LineDictum_64_5', 5, '六五：贞吉，无悔，君子之光，有孚，吉。', '火水未济爻辞5'),
('LineDictum_64_6', 6, '上九：有孚于饮酒，无咎，濡其首，有孚失是。', '火水未济爻辞6');
INSERT INTO divination_result (pb_name, divination_system, method, subject_category, auspiciousness, is_major_result, uses_zhouyi_dictum, response_period, process_flag, description, created_at) VALUES
('PB_QianBodyUse_Bihe', '先天', 'YearMonthDayHourMethod', 'Cat_TianShi', 'Ji', 0, 1, '近', '体用比和', '乾为天卦体用比和，百事顺遂，所谋可成。', '2026-10-20'),
('PB_DuiYongShengTi', '先天', 'YearMonthDayHourMethod', 'Cat_QiuCai', 'DaJi', 1, 1, '近', '用生体', '兑为泽卦用生体，进益之喜，财帛有得。', '2026-10-20'),
('PB_ZhenTiKeYong', '先天', 'YearMonthDayHourMethod', 'Cat_ChuXing', 'Ji', 0, 1, '中', '体克用', '震为雷卦体克用，诸事小吉，出行顺利。', '2026-10-20'),
('PB_LiTiShengYong', '先天', 'YearMonthDayHourMethod', 'Cat_WuShe', 'Ping', 0, 1, '中', '体生用', '离为火卦体生用，有耗失之患，宜守不宜进。', '2026-10-20'),
('PB_KanYongKeTi', '先天', 'YearMonthDayHourMethod', 'Cat_JiBing', 'DaXiong', 1, 1, '远', '用克体', '坎为水卦用克体，诸事凶险，病讼当防。', '2026-10-20'),
('PB_YiCuoJin_ShangShang', '先天', 'YicuoJinMethod', 'Cat_JiaoYi', 'DaJi', 1, 0, '近', '一撮金上上', '一撮金得上上之数，交关大利。', '2026-10-20');
INSERT INTO yicuo_jin_yao (name, hexagram_name, hexagram_seq, line_position, yao_label, grade, grade_iri, dictum_text, label) VALUES
('YicuoJin_01_2', '乾为天', 1, 2, '九二二爻', '上上', 'Grade_ShangShang', '得意宜逢贵，前程去有缘。利名终有望，三五月团圆。', '一撮金·乾为天九二二爻'),
('YicuoJin_01_4', '乾为天', 1, 4, '九四四爻', '中中', 'Grade_ZhongZhong', '欲行不止，徘徊不已。藏玉怀珠，片帆千里。', '一撮金·乾为天九四四爻'),
('YicuoJin_01_6', '乾为天', 1, 6, '上九六爻', '下下', 'Grade_XiaXia', '心戚戚，口啾啾。一番思量一番忧，说了休时又不休。', '一撮金·乾为天上九六爻'),
('YicuoJin_02_2', '坤为地', 2, 2, '六二二爻', '上上', 'Grade_ShangShang', '师征千里福绵绵，造化生成信自然。功名得就神明助，蛇鬼相逢自变迁。万顷波涛无点化，一天风月更幽闲。大明在在红轮照，名利何须自作难。', '一撮金·坤为地六二二爻'),
('YicuoJin_02_4', '坤为地', 2, 4, '六四四爻', '下下', 'Grade_XiaXia', '路不通，门闭塞。谨慎提防，月藏云黑。', '一撮金·坤为地六四四爻'),
('YicuoJin_02_6', '坤为地', 2, 6, '上六六爻', '下中', 'Grade_XiaZhong', '月缺花残，镜破钗分。休来休往，事始安宁。', '一撮金·坤为地上六六爻'),
('YicuoJin_03_2', '水雷屯', 3, 2, '六二二爻', '上中', 'Grade_ShangZhong', '事迟志速，而且反复。直待岁寒，花残果熟。', '一撮金·水雷屯六二二爻'),
('YicuoJin_03_4', '水雷屯', 3, 4, '六四四爻', '上上', 'Grade_ShangShang', '乘马班如，求婚媾吉。随时谐义，缺月重明。', '一撮金·水雷屯六四四爻'),
('YicuoJin_03_6', '水雷屯', 3, 6, '上六六爻', '下下', 'Grade_XiaXia', '不足不足，难伸心曲。野塘雨过月如钩，梦断邯郸眉黛蹙。', '一撮金·水雷屯上六六爻'),
('YicuoJin_04_1', '山水蒙', 4, 1, '初六初爻', '下中', 'Grade_XiaZhong', '门外起干戈，亲朋两不和。朱衣临日月，始觉笑呵呵。', '一撮金·山水蒙初六初爻'),
('YicuoJin_04_3', '山水蒙', 4, 3, '六三三爻', '下下', 'Grade_XiaXia', '娶女无攸利，花间又及秋。严霜将荐至，退步不存留。', '一撮金·山水蒙六三三爻'),
('YicuoJin_04_5', '山水蒙', 4, 5, '六五五爻', '下下', 'Grade_XiaXia', '乘病马上，危坡防失，跌见蹉跎。', '一撮金·山水蒙六五五爻'),
('YicuoJin_05_1', '水天需', 5, 1, '初九初爻', '上中', 'Grade_ShangZhong', '过尽山前后，艰阻往来难。若得清风便，扁舟过远山。', '一撮金·水天需初九初爻'),
('YicuoJin_05_3', '水天需', 5, 3, '九三三爻', '上中', 'Grade_ShangZhong', '君子升，小人阻，征战生离苦。前途自有吉人逢，信在马羊人在楚。事可忧，要营求。', '一撮金·水天需九三三爻'),
('YicuoJin_05_5', '水天需', 5, 5, '九五五爻', '中中', 'Grade_ZhongZhong', '久历惊涛，东风便好。太平身退，目下尚早。', '一撮金·水天需九五五爻'),
('YicuoJin_06_1', '天水讼', 6, 1, '初六初爻', '上中', 'Grade_ShangZhong', '嘹呖征鸿独出群，高飞羽翼更斜分。云程正北堪图进，好个名声处处闻。', '一撮金·天水讼初六初爻'),
('YicuoJin_06_3', '天水讼', 6, 3, '六三三爻', '上中', 'Grade_ShangZhong', '贵各相逢便可期，庭前枯木凤来仪。好将短事求长事，休听旁人说是非。', '一撮金·天水讼六三三爻'),
('YicuoJin_06_5', '天水讼', 6, 5, '九五五爻', '上上', 'Grade_ShangShang', '檐前鹊噪正翩翩，忧虑洗消喜自然。一人进了一人退，下梢总有好因缘。', '一撮金·天水讼九五五爻'),
('YicuoJin_07_2', '地水师', 7, 2, '九二二爻', '上上', 'Grade_ShangShang', '秋月云开后，薰风雨过时。若逢楚国旧知己，等闲一荐不须疑。', '一撮金·地水师九二二爻'),
('YicuoJin_07_4', '地水师', 7, 4, '六四四爻', '下中', 'Grade_XiaZhong', '青毡终复旧，枝上果生风。莫谓一时喜，还疑此象凶。', '一撮金·地水师六四四爻'),
('YicuoJin_07_6', '地水师', 7, 6, '上六六爻', '上上', 'Grade_ShangShang', '谋已定，事何忧。金鳞已上钩，功名一网收。', '一撮金·地水师上六六爻'),
('YicuoJin_08_2', '水地比', 8, 2, '六二二爻', '中中', 'Grade_ZhongZhong', '一人去，一人来，清风明月两相猜，获得金鳞下钓台。', '一撮金·水地比六二二爻'),
('YicuoJin_08_4', '水地比', 8, 4, '六四四爻', '下中', 'Grade_XiaZhong', '无端风雨吹春去，落尽枝头桃李花。枕畔有人歌且笑，教君心事乱如麻。', '一撮金·水地比六四四爻'),
('YicuoJin_08_6', '水地比', 8, 6, '上六六爻', '下下', 'Grade_XiaXia', '喜未稳，愁已遭，大雨狂风临古木，人人尽道不坚牢。', '一撮金·水地比上六六爻'),
('YicuoJin_09_2', '风天小畜', 9, 2, '九二二爻', '上中', 'Grade_ShangZhong', '金鳞入手，得还防走。若论周旋，谨慎戒口。', '一撮金·风天小畜九二二爻'),
('YicuoJin_09_4', '风天小畜', 9, 4, '六四四爻', '中中', 'Grade_ZhongZhong', '上下不和同，劳而未有功。出门通大道，从此保初终。', '一撮金·风天小畜六四四爻'),
('YicuoJin_09_6', '风天小畜', 9, 6, '上九六爻', '上中', 'Grade_ShangZhong', '拟欲迁而未可迁，提防喜处惹勾连。前途若得阴人引，变化鱼龙出大渊。', '一撮金·风天小畜上九六爻'),
('YicuoJin_10_1', '天泽履', 10, 1, '初九初爻', '上中', 'Grade_ShangZhong', '不远不近，似易似难。等闲入手，云中笑看。', '一撮金·天泽履初九初爻'),
('YicuoJin_10_3', '天泽履', 10, 3, '六三三爻', '下下', 'Grade_XiaXia', '桃李谢春风，西去又复东。家中无意绪，船在浪涛中。', '一撮金·天泽履六三三爻'),
('YicuoJin_10_5', '天泽履', 10, 5, '九五五爻', '中中', 'Grade_ZhongZhong', '狂风吹起黑云飞，月在天心遮不得。时闲无事暂相关，到底依然无刻剥。', '一撮金·天泽履九五五爻'),
('YicuoJin_11_1', '地天泰', 11, 1, '初九初爻', '上中', 'Grade_ShangZhong', '东边事，西边成，风物月华明，高楼弄笛声。', '一撮金·地天泰初九初爻'),
('YicuoJin_11_3', '地天泰', 11, 3, '九三三爻', '下下', 'Grade_XiaXia', '和不和，同不同，翻云覆雨几成空，进退须防终少功。', '一撮金·地天泰九三三爻'),
('YicuoJin_11_5', '地天泰', 11, 5, '六五五爻', '上上', 'Grade_ShangShang', '添一人，获一宝。事团圆，门外讨。', '一撮金·地天泰六五五爻'),
('YicuoJin_12_1', '天地否', 12, 1, '初六初爻', '上中', 'Grade_ShangZhong', '相引更相牵，殷勤喜自然。施为无不利，愁事变团圆。', '一撮金·天地否初六初爻'),
('YicuoJin_12_3', '天地否', 12, 3, '六三三爻', '下下', 'Grade_XiaXia', '无踪又无迹，远近终难觅。平地起风云，似笑还成泣。', '一撮金·天地否六三三爻'),
('YicuoJin_12_5', '天地否', 12, 5, '九五五爻', '下下', 'Grade_XiaXia', '身不安，心不安，动静两三番，终期事必欢。', '一撮金·天地否九五五爻'),
('YicuoJin_13_2', '天火同人', 13, 2, '六二二爻', '上上', 'Grade_ShangShang', '心和同，事和同，门外好施工，交加事有终。', '一撮金·天火同人六二二爻'),
('YicuoJin_13_4', '天火同人', 13, 4, '九四四爻', '中平', 'Grade_ZhongPing', '意孜孜，心戚戚，要平安，防出入。', '一撮金·天火同人九四四爻'),
('YicuoJin_13_6', '天火同人', 13, 6, '上九六爻', '上中', 'Grade_ShangZhong', '一水绕一水，一山绕一山。水尽山穷处，名利不为难。', '一撮金·天火同人上九六爻'),
('YicuoJin_14_2', '火天大有', 14, 2, '九二二爻', '上中', 'Grade_ShangZhong', '一重水，一重山，风波道坦然，壶中别有天。', '一撮金·火天大有九二二爻'),
('YicuoJin_14_4', '火天大有', 14, 4, '九四四爻', '上上', 'Grade_ShangShang', '遇险不为忧，风波何足惧。若遇草头人，咫尺青云路。', '一撮金·火天大有九四四爻'),
('YicuoJin_14_6', '火天大有', 14, 6, '上九六爻', '上上', 'Grade_ShangShang', '奇奇奇，地利与天时。灯花传信后，动静总相宜。', '一撮金·火天大有上九六爻'),
('YicuoJin_15_1', '地山谦', 15, 1, '初六初爻', '下中', 'Grade_XiaZhong', '恐怕正忧煎，忧非满目前。若逢明鉴照，挠括信空传。', '一撮金·地山谦初六初爻'),
('YicuoJin_15_3', '地山谦', 15, 3, '九三三爻', '上中', 'Grade_ShangZhong', '劳心慢劳心，劳心终有成。清风来借力，欢笑见前程。', '一撮金·地山谦九三三爻'),
('YicuoJin_15_5', '地山谦', 15, 5, '六五五爻', '下中', 'Grade_XiaZhong', '莺语燕呢喃，花开满院间。倚阑春梦觉，无语敛愁颜。', '一撮金·地山谦六五五爻'),
('YicuoJin_16_2', '雷地豫', 16, 2, '六二二爻', '中中', 'Grade_ZhongZhong', '凿石得玉，淘沙得珠。眼前目下，何用踌躇。', '一撮金·雷地豫六二二爻'),
('YicuoJin_16_4', '雷地豫', 16, 4, '九四四爻', '上上', 'Grade_ShangShang', '名成利遂勿忧煎，菊里秋风道坦然。得意便垂三尺钓，长竿获得锦鳞鲜。', '一撮金·雷地豫九四四爻'),
('YicuoJin_16_6', '雷地豫', 16, 6, '上六六爻', '下下', 'Grade_XiaXia', '独钓寒潭涧，中途兴已阑。水寒鱼不饵，小舟明月还。', '一撮金·雷地豫上六六爻'),
('YicuoJin_17_2', '泽雷随', 17, 2, '六二二爻', '中平', 'Grade_ZhongPing', '一事已成空，一事还成喜。若遇口边人，心下堪凭委。', '一撮金·泽雷随六二二爻'),
('YicuoJin_17_4', '泽雷随', 17, 4, '九四四爻', '下中', 'Grade_XiaZhong', '鱼上钩，丝纶弱。收拾难，力再著。', '一撮金·泽雷随九四四爻'),
('YicuoJin_17_6', '泽雷随', 17, 6, '上六六爻', '上上', 'Grade_ShangShang', '可蓄可储，片玉寸珠。停停稳稳，前遇良图。', '一撮金·泽雷随上六六爻'),
('YicuoJin_18_2', '山风蛊', 18, 2, '九二二爻', '上中', 'Grade_ShangZhong', '暗去又明来，忧心事可谐。终须成一笑，目下莫疑猜。', '一撮金·山风蛊九二二爻'),
('YicuoJin_18_4', '山风蛊', 18, 4, '六四四爻', '中中', 'Grade_ZhongZhong', '可以委，可以托。事迟迟，无差错。', '一撮金·山风蛊六四四爻'),
('YicuoJin_18_6', '山风蛊', 18, 6, '上九六爻', '上中', 'Grade_ShangZhong', '深渊鱼可钓，幽林鸟可获。只用久长心，不用生疑惑。', '一撮金·山风蛊上九六爻'),
('YicuoJin_19_2', '地泽临', 19, 2, '九二二爻', '上上', 'Grade_ShangShang', '和合事，笑谈成。喜音在半程，平步踏青云。', '一撮金·地泽临九二二爻'),
('YicuoJin_19_4', '地泽临', 19, 4, '六四四爻', '上上', 'Grade_ShangShang', '事团圆，物周旋。一往一来，平步青天。', '一撮金·地泽临六四四爻'),
('YicuoJin_19_6', '地泽临', 19, 6, '上六六爻', '上中', 'Grade_ShangZhong', '朦胧秋月映朱扃，林处鸡声远处生。自有贵人相接引，何须巧语似流莺。', '一撮金·地泽临上六六爻'),
('YicuoJin_20_1', '风地观', 20, 1, '初六初爻', '上上', 'Grade_ShangShang', '野鬼暗张弧，射中主人惊。红日沉江海，空中事不成。', '一撮金·风地观初六初爻'),
('YicuoJin_20_3', '风地观', 20, 3, '六四三爻', '上上', 'Grade_ShangShang', '双燕衔书舞，指日一齐来。寂寞淹留客，从兹下钓台。', '一撮金·风地观六四三爻'),
('YicuoJin_20_5', '风地观', 20, 5, '九五五爻', '下中', 'Grade_XiaZhong', '云叆叆，月朦胧。一雁入云中，残花谢晓风。', '一撮金·风地观九五五爻'),
('YicuoJin_21_1', '火雷噬嗑', 21, 1, '初九初爻', '上中', 'Grade_ShangZhong', '人倚楼，许多愁。淡然进步，事始无忧。', '一撮金·火雷噬嗑初九初爻'),
('YicuoJin_21_3', '火雷噬嗑', 21, 3, '六三三爻', '上中', 'Grade_ShangZhong', '暗中防霹雳，猜疑浑未实。转眼黑云收，拥出扶桑日。', '一撮金·火雷噬嗑六三三爻'),
('YicuoJin_21_5', '火雷噬嗑', 21, 5, '六五五爻', '下下', 'Grade_XiaXia', '堪叹枕边忧，更嗟门里闹。意绪甚索缠，心神亦颠倒。', '一撮金·火雷噬嗑六五五爻'),
('YicuoJin_22_2', '山火贲', 22, 2, '六二二爻', '上上', 'Grade_ShangShang', '月已圆，花再发。事悠悠，无不合。', '一撮金·山火贲六二二爻'),
('YicuoJin_22_4', '山火贲', 22, 4, '六四四爻', '上中', 'Grade_ShangZhong', '曲中应有直，心事还成戚。云散月重圆，千里风帆急。', '一撮金·山火贲六四四爻'),
('YicuoJin_22_6', '山火贲', 22, 6, '上九六爻', '上上', 'Grade_ShangShang', '明月重圆，颜色欣然。风云相送，和合万年。', '一撮金·山火贲上九六爻'),
('YicuoJin_23_1', '山地剥', 23, 1, '初六初爻', '下下', 'Grade_XiaXia', '上接不稳，下接不和。相缠相扰，平地风波。', '一撮金·山地剥初六初爻'),
('YicuoJin_23_3', '山地剥', 23, 3, '六三三爻', '上上', 'Grade_ShangShang', '玉石犹蒙昧，那堪小悔多。终无咎，笑呵呵。', '一撮金·山地剥六三三爻'),
('YicuoJin_23_5', '山地剥', 23, 5, '六五五爻', '中中', 'Grade_ZhongZhong', '圆又缺，缺又圆，低低密密要周旋，时来始见缘。', '一撮金·山地剥六五五爻'),
('YicuoJin_24_2', '地雷复', 24, 2, '六二二爻', '上中', 'Grade_ShangZhong', '悲后笑嘻嘻，中行道最宜。所求终有望，不必皱双眉。', '一撮金·地雷复六二二爻'),
('YicuoJin_24_4', '地雷复', 24, 4, '六四四爻', '上中', 'Grade_ShangZhong', '临渊放钓，清绝点埃。巨鳌随得，何用疑猜。', '一撮金·地雷复六四四爻'),
('YicuoJin_24_6', '地雷复', 24, 6, '上六六爻', '下下', 'Grade_XiaXia', '进步且徘徊，春风柳絮催。水边行客倦，枕畔有忧怀。', '一撮金·地雷复上六六爻'),
('YicuoJin_25_1', '天雷无妄', 25, 1, '初九初爻', '上上', 'Grade_ShangShang', '事相扶，在半途，翻覆终可免，风波一点无。', '一撮金·天雷无妄初九初爻'),
('YicuoJin_25_3', '天雷无妄', 25, 3, '六三三爻', '下下', 'Grade_XiaXia', '浅水起波澜，平地生荆棘。言语虚参商，犹恐无端的。', '一撮金·天雷无妄六三三爻'),
('YicuoJin_25_5', '天雷无妄', 25, 5, '九五五爻', '上上', 'Grade_ShangShang', '喜喜喜，春风生桃李。不用强忧煎，明月人千里。', '一撮金·天雷无妄九五五爻'),
('YicuoJin_26_2', '山天大畜', 26, 2, '九二二爻', '中中', 'Grade_ZhongZhong', '蜗角蝇头利，而今已变通。草头人笑后，宜始不宜终。', '一撮金·山天大畜九二二爻'),
('YicuoJin_26_4', '山天大畜', 26, 4, '六四四爻', '下中', 'Grade_XiaZhong', '鹊噪高枝上，人行古渡头。半途不了事，日暮转生愁。', '一撮金·山天大畜六四四爻'),
('YicuoJin_26_6', '山天大畜', 26, 6, '上九六爻', '上上', 'Grade_ShangShang', '事有喜，物有光，始终好商量，壶中日月长。', '一撮金·山天大畜上九六爻'),
('YicuoJin_27_1', '山雷颐', 27, 1, '初九初爻', '下下', 'Grade_XiaXia', '红叶无颜色，凋零一夜风。邻鸡醒午梦，心事总成空。', '一撮金·山雷颐初九初爻'),
('YicuoJin_27_3', '山雷颐', 27, 3, '六三三爻', '下下', 'Grade_XiaXia', '事宜休，理多错。日掩云中，空成担阁。', '一撮金·山雷颐六三三爻'),
('YicuoJin_27_5', '山雷颐', 27, 5, '六五五爻', '下中', 'Grade_XiaZhong', '进不安，退不可。上下相从，明珠一颗。', '一撮金·山雷颐六五五爻'),
('YicuoJin_28_1', '泽风大过', 28, 1, '初六初爻', '中中', 'Grade_ZhongZhong', '心有余，力不足。倚仗春风，一歌一曲。', '一撮金·泽风大过初六初爻'),
('YicuoJin_28_3', '泽风大过', 28, 3, '九三三爻', '下下', 'Grade_XiaXia', '荆棘生平地，风波起四方。倚阑惆怅望，无语对斜阳。', '一撮金·泽风大过九三三爻'),
('YicuoJin_28_5', '泽风大过', 28, 5, '九五五爻', '中中', 'Grade_ZhongZhong', '一人两事，一人两心。新花枯树，须待交春。', '一撮金·泽风大过九五五爻'),
('YicuoJin_29_2', '坎为水', 29, 2, '九二二爻', '下中', 'Grade_XiaZhong', '梦里说江水，波深下钓难。利名终有望，目下未开颜。', '一撮金·坎为水九二二爻'),
('YicuoJin_29_4', '坎为水', 29, 4, '六四四爻', '上上', 'Grade_ShangShang', '莫怪事迟留，休言不到头。长竿终入手，一钓上金钩。', '一撮金·坎为水六四四爻'),
('YicuoJin_29_6', '坎为水', 29, 6, '上六六爻', '下下', 'Grade_XiaXia', '疑疑疑，一番笑后一番悲。落红满地无人扫，独对西风抹黛眉。', '一撮金·坎为水上六六爻'),
('YicuoJin_30_2', '离为火', 30, 2, '六二二爻', '上上', 'Grade_ShangShang', '谋已定，事何忧，明月上重楼，云中客点头。', '一撮金·离为火六二二爻'),
('YicuoJin_30_4', '离为火', 30, 4, '九四四爻', '下下', 'Grade_XiaXia', '遇不遇，逢不逢，月沉水底，人在梦中。', '一撮金·离为火九四四爻'),
('YicuoJin_30_6', '离为火', 30, 6, '上九六爻', '中中', 'Grade_ZhongZhong', '诛战中邦利出征，一朝获丑在王庭。凤衔一诏堤场畔，得个佳名四海荣。', '一撮金·离为火上九六爻'),
('YicuoJin_31_1', '泽山咸', 31, 1, '初六初爻', '中中', 'Grade_ZhongZhong', '意在关中信未来，故人千里自徘徊。天边雁足传书至，一点梅花喜色开。', '一撮金·泽山咸初六初爻'),
('YicuoJin_31_3', '泽山咸', 31, 3, '九三三爻', '下下', 'Grade_XiaXia', '休道事无论讹，其中进退多。桂轮圆又缺，光彩更揩磨。', '一撮金·泽山咸九三三爻'),
('YicuoJin_31_5', '泽山咸', 31, 5, '九五五爻', '下中', 'Grade_XiaZhong', '事了物未了，人圆物未圆。要知端的信，月影上阑干。', '一撮金·泽山咸九五五爻'),
('YicuoJin_32_1', '雷风恒', 32, 1, '初六初爻', '下下', 'Grade_XiaXia', '深潭月，明镜影。一场空，妄报信。', '一撮金·雷风恒初六初爻'),
('YicuoJin_32_3', '雷风恒', 32, 3, '九三三爻', '下下', 'Grade_XiaXia', '桥已断，路不通。登舟理楫，又遇狂风。', '一撮金·雷风恒九三三爻'),
('YicuoJin_32_5', '雷风恒', 32, 5, '六五五爻', '下下', 'Grade_XiaXia', '湖水悠悠，孤舟浪头。来人未识，残月山楼。', '一撮金·雷风恒六五五爻'),
('YicuoJin_33_2', '天山遁', 33, 2, '六二二爻', '中中', 'Grade_ZhongZhong', '兀兀尘埃又待时，幽窗静处有谁知。若逢青紫人相引，财利功名自可期。', '一撮金·天山遁六二二爻'),
('YicuoJin_33_4', '天山遁', 33, 4, '九四四爻', '上中', 'Grade_ShangZhong', '一得一虑，宜后欲先。路通大道，心事安然。', '一撮金·天山遁九四四爻'),
('YicuoJin_33_6', '天山遁', 33, 6, '上九六爻', '上上', 'Grade_ShangShang', '一番桃李一番新，谁识阳和气象明。林下水边多活计，见山了了称人情。', '一撮金·天山遁上九六爻'),
('YicuoJin_34_1', '雷天大壮', 34, 1, '初九初爻', '下下', 'Grade_XiaXia', '江阔渡无船，惊涛恐拍天。月斜云淡处，音信有人传。', '一撮金·雷天大壮初九初爻'),
('YicuoJin_34_3', '雷天大壮', 34, 3, '九三三爻', '下中', 'Grade_XiaZhong', '平地起风烟，时下未能安，高处觅因缘。', '一撮金·雷天大壮九三三爻'),
('YicuoJin_34_5', '雷天大壮', 34, 5, '六五五爻', '下中', 'Grade_XiaZhong', '正直宜守，妄动生灾。名通利达，叶落花开。', '一撮金·雷天大壮六五五爻'),
('YicuoJin_35_1', '火地晋', 35, 1, '初六初爻', '上中', 'Grade_ShangZhong', '须著力，莫游遨。长竿钓向蟾蜍窟，直欲云中得巨鳌。', '一撮金·火地晋初六初爻'),
('YicuoJin_35_3', '火地晋', 35, 3, '六三三爻', '上上', 'Grade_ShangShang', '两两意和同，轻帆遇顺风。道逢人得意，歌唱急流中。', '一撮金·火地晋六三三爻'),
('YicuoJin_35_5', '火地晋', 35, 5, '六五五爻', '中中', 'Grade_ZhongZhong', '万里涉江山，风波尽日闲。已吞钩上饵，何必遇波澜。', '一撮金·火地晋六五五爻'),
('YicuoJin_36_1', '地火明夷', 36, 1, '初九初爻', '中中', 'Grade_ZhongZhong', '乘翼遥飞去，皆因避远行。一途经济意，又是满园春。', '一撮金·地火明夷初九初爻'),
('YicuoJin_36_3', '地火明夷', 36, 3, '九三三爻', '上中', 'Grade_ShangZhong', '虚名虚位久沉沉，禄马当头未见真。一片彩云秋后至，去年风物一时新。', '一撮金·地火明夷九三三爻'),
('YicuoJin_36_5', '地火明夷', 36, 5, '六五五爻', '下下', 'Grade_XiaXia', '重关深锁闭，谨慎要提防。小节不知戒，因循成大殃。', '一撮金·地火明夷六五五爻'),
('YicuoJin_37_2', '风火家人', 37, 2, '六二二爻', '下中', 'Grade_XiaZhong', '一镜破，照两人。心中结，合同心。', '一撮金·风火家人六二二爻'),
('YicuoJin_37_4', '风火家人', 37, 4, '六四四爻', '上上', 'Grade_ShangShang', '珠玉走盘中，田园足阜丰。休言谋未遂，此去一时通。', '一撮金·风火家人六四四爻'),
('YicuoJin_37_6', '风火家人', 37, 6, '上九六爻', '上中', 'Grade_ShangZhong', '心下事悠然，周旋尚未全。遇龙终有吉，人月永团圆。', '一撮金·风火家人上九六爻'),
('YicuoJin_38_1', '火泽睽', 38, 1, '初九初爻', '下中', 'Grade_XiaZhong', '上下分，忧愁决。千嶂云，一轮月。', '一撮金·火泽睽初九初爻'),
('YicuoJin_38_3', '火泽睽', 38, 3, '六三三爻', '下下', 'Grade_XiaXia', '鼎沸风波，孤舟渡河。巧中藏拙，人事蹉跎。', '一撮金·火泽睽六三三爻'),
('YicuoJin_38_5', '火泽睽', 38, 5, '六五五爻', '下中', 'Grade_XiaZhong', '船棹中流急，花开春又迟。事宁心不静，惹起许多疑。', '一撮金·火泽睽六五五爻'),
('YicuoJin_39_1', '水山蹇', 39, 1, '初六初爻', '下中', 'Grade_XiaZhong', '岸阔水深舟易落，路遥山险步难行。行行自有通津日，目下香消月未明。', '一撮金·水山蹇初六初爻'),
('YicuoJin_39_3', '水山蹇', 39, 3, '九三三爻', '下下', 'Grade_XiaXia', '事虑淹留，人不彻头。往来闭塞，要见无由。', '一撮金·水山蹇九三三爻'),
('YicuoJin_39_5', '水山蹇', 39, 5, '九五五爻', '中中', 'Grade_ZhongZhong', '道路任招呼，风波一点无。时间心绪乱，全仗贵人扶。', '一撮金·水山蹇九五五爻'),
('YicuoJin_40_2', '雷水解', 40, 2, '九二二爻', '上上', 'Grade_ShangShang', '万里波涛静，一天风雨闲。利名无阻隔，行路出重关。', '一撮金·雷水解九二二爻'),
('YicuoJin_40_4', '雷水解', 40, 4, '九四四爻', '上上', 'Grade_ShangShang', '湖海意悠悠，烟波下钓钩。若逢龙与兔，名利一齐周。', '一撮金·雷水解九四四爻'),
('YicuoJin_40_6', '雷水解', 40, 6, '上六六爻', '上中', 'Grade_ShangZhong', '一箭青云路，营求指日成。许多闲口语，翻作笑歌声。', '一撮金·雷水解上六六爻'),
('YicuoJin_41_1', '山泽损', 41, 1, '初九初爻', '下中', 'Grade_XiaZhong', '喜喜喜，终防否。获得骊龙颔下珠，忽然失却还沉水。', '一撮金·山泽损初九初爻'),
('YicuoJin_41_3', '山泽损', 41, 3, '六三三爻', '中中', 'Grade_ZhongZhong', '事未完，心未安。疑虑久，得安然。', '一撮金·山泽损六三三爻'),
('YicuoJin_41_5', '山泽损', 41, 5, '六五五爻', '中中', 'Grade_ZhongZhong', '莫言枳棘恶，终为鸾凤栖。目前应有待，何用早踌躇。', '一撮金·山泽损六五五爻'),
('YicuoJin_42_1', '风雷益', 42, 1, '初九初爻', '上中', 'Grade_ShangZhong', '大事可成功，有益还无咎。云中执鞭人，报在三秋后。', '一撮金·风雷益初九初爻'),
('YicuoJin_42_3', '风雷益', 42, 3, '六三三爻', '下下', 'Grade_XiaXia', '无踪又无迹，远近终难觅。旱海莫行舟，何劳空费力。', '一撮金·风雷益六三三爻'),
('YicuoJin_42_5', '风雷益', 42, 5, '九五五爻', '上上', 'Grade_ShangShang', '子结花残，花开枯树。屋头春意，喜笑嘻嘻。', '一撮金·风雷益九五五爻'),
('YicuoJin_43_1', '泽天夬', 43, 1, '初九初爻', '下中', 'Grade_XiaZhong', '神黯黯，意悠悠。收却线，莫下钩。', '一撮金·泽天夬初九初爻'),
('YicuoJin_43_3', '泽天夬', 43, 3, '九三三爻', '中平', 'Grade_ZhongPing', '虎伏在前途，行人莫乱呼。路旁须仔细，灾祸自然无。', '一撮金·泽天夬九三三爻'),
('YicuoJin_43_5', '泽天夬', 43, 5, '九五五爻', '下下', 'Grade_XiaXia', '所事纵云难，平地起波澜。笑谈终有忌，事回心觉喜。', '一撮金·泽天夬九五五爻'),
('YicuoJin_44_2', '天风姤', 44, 2, '九二二爻', '下中', 'Grade_XiaZhong', '欲济未济，欲求强求。心无一定，一车两头。', '一撮金·天风姤九二二爻'),
('YicuoJin_44_4', '天风姤', 44, 4, '九四四爻', '下下', 'Grade_XiaXia', '居下当亲上，人心易散离。事机才一失，万事尽皆灰。', '一撮金·天风姤九四四爻'),
('YicuoJin_44_6', '天风姤', 44, 6, '上九六爻', '下下', 'Grade_XiaXia', '见不见，也防人背面。遇不遇，到底无凭据。', '一撮金·天风姤上九六爻'),
('YicuoJin_45_2', '泽地萃', 45, 2, '六二二爻', '上中', 'Grade_ShangZhong', '笑中生不足，内外见愁哭。云散月光辉，转祸当成福。', '一撮金·泽地萃六二二爻'),
('YicuoJin_45_4', '泽地萃', 45, 4, '九四四爻', '中中', 'Grade_ZhongZhong', '言语参商，波涛鼎沸。事久无伤，时间不利。', '一撮金·泽地萃九四四爻'),
('YicuoJin_45_6', '泽地萃', 45, 6, '上六六爻', '中中', 'Grade_ZhongZhong', '无非应有忌，未为先恐踬。路险风波事更非，要得称心须借势。', '一撮金·泽地萃上六六爻'),
('YicuoJin_46_1', '地风升', 46, 1, '初六初爻', '上上', 'Grade_ShangShang', '明月为钩，清风作线。举网烟波，锦鳞易见。', '一撮金·地风升初六初爻'),
('YicuoJin_46_3', '地风升', 46, 3, '九三三爻', '上中', 'Grade_ShangZhong', '舟离古渡月离云，人出重关好问津。且向前行求去住，何须疑虑两三旬。', '一撮金·地风升九三三爻'),
('YicuoJin_46_5', '地风升', 46, 5, '六五五爻', '上上', 'Grade_ShangShang', '佳信至，见笑颜。飞腾一去，披云上天。', '一撮金·地风升六五五爻'),
('YicuoJin_47_2', '泽水困', 47, 2, '九二二爻', '上中', 'Grade_ShangZhong', '足不安，心不安，两两事相得，忧来却又欢。', '一撮金·泽水困九二二爻'),
('YicuoJin_47_4', '泽水困', 47, 4, '九四四爻', '上中', 'Grade_ShangZhong', '目下志难舒，有客来徐徐。金车虽历险，吝必有终欤。', '一撮金·泽水困九四四爻'),
('YicuoJin_47_6', '泽水困', 47, 6, '上六六爻', '下下', 'Grade_XiaXia', '缺月恐难圆，残花不再鲜，苦求名与利，到处遇迍邅。', '一撮金·泽水困上六六爻'),
('YicuoJin_48_1', '水风井', 48, 1, '初六初爻', '中中', 'Grade_ZhongZhong', '月在云间，昏迷道路。云散月明，渐宜进步。', '一撮金·水风井初六初爻'),
('YicuoJin_48_3', '水风井', 48, 3, '九三三爻', '下下', 'Grade_XiaXia', '安静事难疑，云中一鹤飞。桃花逢骤雨，水畔女频啼。', '一撮金·水风井九三三爻'),
('YicuoJin_48_5', '水风井', 48, 5, '九五五爻', '上中', 'Grade_ShangZhong', '美在甘，甘有美。始有终，终有始。', '一撮金·水风井九五五爻'),
('YicuoJin_49_1', '泽火革', 49, 1, '初九初爻', '下中', 'Grade_XiaZhong', '意迷心不迷，事宽心不宽。要知端的事，犹隔两重山。', '一撮金·泽火革初九初爻'),
('YicuoJin_49_3', '泽火革', 49, 3, '九三三爻', '中中', 'Grade_ZhongZhong', '道路迢遥，门庭闭塞。雪拥未分明，云开方见日。', '一撮金·泽火革九三三爻'),
('YicuoJin_49_5', '泽火革', 49, 5, '九五五爻', '上中', 'Grade_ShangZhong', '虎变高山别有期，望人目下尚狐疑。雁来嘹呖黄花发，此际声名达帝畿。', '一撮金·泽火革九五五爻'),
('YicuoJin_50_2', '火风鼎', 50, 2, '九二二爻', '上上', 'Grade_ShangShang', '小子出门庭，青衣久问程。贵人来助力，花谢子还成。', '一撮金·火风鼎九二二爻'),
('YicuoJin_50_4', '火风鼎', 50, 4, '九四四爻', '下中', 'Grade_XiaZhong', '鼎折足，舆脱辙。有贵人，重整续。', '一撮金·火风鼎九四四爻'),
('YicuoJin_50_6', '火风鼎', 50, 6, '上九六爻', '上上', 'Grade_ShangShang', '贵客自相亲，功名唾手成。获金须积德，仰望太阳升。', '一撮金·火风鼎上九六爻'),
('YicuoJin_51_2', '震为雷', 51, 2, '六二二爻', '下下', 'Grade_XiaXia', '无踪又无迹，远近终难觅。旱海莫行舟，何劳空著力。', '一撮金·震为雷六二二爻'),
('YicuoJin_51_4', '震为雷', 51, 4, '九四四爻', '上中', 'Grade_ShangZhong', '白玉隐尘，黄金埋土。久久光辉，也要人举。', '一撮金·震为雷九四四爻'),
('YicuoJin_51_6', '震为雷', 51, 6, '上六六爻', '下中', 'Grade_XiaZhong', '细雨濛濛湿，江边路不通。道途人未达，凭仗借东风。', '一撮金·震为雷上六六爻'),
('YicuoJin_52_2', '艮为山', 52, 2, '六二二爻', '中中', 'Grade_ZhongZhong', '易非易，难非难，忽然平地起波澜，歌笑须教三两番。', '一撮金·艮为山六二二爻'),
('YicuoJin_52_4', '艮为山', 52, 4, '六四四爻', '中中', 'Grade_ZhongZhong', '山山有路，有终有始。似月如花，守成而已。', '一撮金·艮为山六四四爻'),
('YicuoJin_52_6', '艮为山', 52, 6, '上九六爻', '上上', 'Grade_ShangShang', '宝镜无尘染，金貂已剪裁。也逢天意合，终不染尘埃。', '一撮金·艮为山上九六爻'),
('YicuoJin_53_2', '风山渐', 53, 2, '六二二爻', '上上', 'Grade_ShangShang', '阆苑一时春，庭前花柳新。鹊声传好信，草木尽欣欣。', '一撮金·风山渐六二二爻'),
('YicuoJin_53_4', '风山渐', 53, 4, '六四四爻', '上上', 'Grade_ShangShang', '欲捉月中兔，须凭桃李梯。高山来接引，双喜照双眉。', '一撮金·风山渐六四四爻'),
('YicuoJin_53_6', '风山渐', 53, 6, '上九六爻', '中中', 'Grade_ZhongZhong', '意迷心不迷，事宽心不宽。一场双喜会，不久出重关。', '一撮金·风山渐上九六爻'),
('YicuoJin_54_2', '雷泽归妹', 54, 2, '九二二爻', '下中', 'Grade_XiaZhong', '门外事重叠，阴人多遇合。贤女虽助巧，渺渺终难洽。', '一撮金·雷泽归妹九二二爻'),
('YicuoJin_54_4', '雷泽归妹', 54, 4, '九四四爻', '下中', 'Grade_XiaZhong', '缺月重圆，枯枝又鲜。一条坦路，翘首青天。', '一撮金·雷泽归妹九四四爻'),
('YicuoJin_54_6', '雷泽归妹', 54, 6, '上六六爻', '中中', 'Grade_ZhongZhong', '美红颜，休挂怀。人在车中，舟行海底。', '一撮金·雷泽归妹上六六爻'),
('YicuoJin_55_1', '雷火丰', 55, 1, '初九初爻', '上中', 'Grade_ShangZhong', '过尽风波三五重，谁知浪尽又无风。须知明达青云路，用舍行藏不费功。', '一撮金·雷火丰初九初爻'),
('YicuoJin_55_3', '雷火丰', 55, 3, '九三三爻', '下下', 'Grade_XiaXia', '纷纷复纷纷，欷嘘独掩门。敛眉望灯火，伴我坐黄昏。', '一撮金·雷火丰九三三爻'),
('YicuoJin_55_5', '雷火丰', 55, 5, '六五五爻', '下中', 'Grade_XiaZhong', '门内佳音来，生涯应有庆。名利有更迁，雁行终拆阵。', '一撮金·雷火丰六五五爻'),
('YicuoJin_56_2', '火山旅', 56, 2, '六二二爻', '上上', 'Grade_ShangShang', '悲脸笑颜开，秋月挂高台，人从千里来。', '一撮金·火山旅六二二爻'),
('YicuoJin_56_4', '火山旅', 56, 4, '九四四爻', '中中', 'Grade_ZhongZhong', '花落正逢春，行人在半程。事成还不就，索绊两三旬。', '一撮金·火山旅九四四爻'),
('YicuoJin_56_6', '火山旅', 56, 6, '上九六爻', '中中', 'Grade_ZhongZhong', '憔悴无人问，林间听杜鹃。一声山月笛，千里暗销魂。', '一撮金·火山旅上九六爻'),
('YicuoJin_57_2', '巽为风', 57, 2, '九二二爻', '下下', 'Grade_XiaXia', '着着占先机，其中路不迷。目前无舍意，争免是和非。', '一撮金·巽为风九二二爻'),
('YicuoJin_57_4', '巽为风', 57, 4, '六四四爻', '上上', 'Grade_ShangShang', '江海悠悠，烟波下钩。六鳌连获，歌笑中流。', '一撮金·巽为风六四四爻'),
('YicuoJin_57_6', '巽为风', 57, 6, '上九六爻', '下下', 'Grade_XiaXia', '一月圆，一镜缺。少团圆，无可说。', '一撮金·巽为风上九六爻'),
('YicuoJin_58_2', '兑为泽', 58, 2, '九二二爻', '上上', 'Grade_ShangShang', '玉出昆冈石，舟离古渡滩。行藏终有望，用舍不为难。', '一撮金·兑为泽九二二爻'),
('YicuoJin_58_4', '兑为泽', 58, 4, '九四四爻', '下下', 'Grade_XiaXia', '难难难，忽然平地起波澜。易易易，谈笑平常终有忌。', '一撮金·兑为泽九四四爻'),
('YicuoJin_58_6', '兑为泽', 58, 6, '上六六爻', '下下', 'Grade_XiaXia', '乐之极矣悲相望，引兑来兮吉与凶。未能光大终须暗，日落西山返照中。', '一撮金·兑为泽上六六爻'),
('YicuoJin_59_1', '风水涣', 59, 1, '初六初爻', '上上', 'Grade_ShangShang', '云静日当中，光辉到处通。道途逢水顺，千里快如风。', '一撮金·风水涣初六初爻'),
('YicuoJin_59_3', '风水涣', 59, 3, '六三三爻', '中中', 'Grade_ZhongZhong', '望处应重山，高深渐可攀。举头天上看，明月出人间。', '一撮金·风水涣六三三爻'),
('YicuoJin_59_5', '风水涣', 59, 5, '九五五爻', '中中', 'Grade_ZhongZhong', '不归一，劳心力。贵人旁，宜借力。', '一撮金·风水涣九五五爻'),
('YicuoJin_60_2', '水泽节', 60, 2, '九二二爻', '下下', 'Grade_XiaXia', '休眷恋，奔前程。终闹乱，出门庭。', '一撮金·水泽节九二二爻'),
('YicuoJin_60_4', '水泽节', 60, 4, '六四四爻', '上上', 'Grade_ShangShang', '用则行，舍则藏。一骑出重关，佳音咫尺间。', '一撮金·水泽节六四四爻'),
('YicuoJin_60_6', '水泽节', 60, 6, '上六六爻', '下下', 'Grade_XiaXia', '渴穿井，饥画饼。漫劳心，如捕影。遇龙虎，方可省。', '一撮金·水泽节上六六爻'),
('YicuoJin_61_1', '风泽中孚', 61, 1, '初九初爻', '上中', 'Grade_ShangZhong', '一点著阳春，枯枝朵朵荣。志专方遇合，初忌二三心。', '一撮金·风泽中孚初九初爻'),
('YicuoJin_61_3', '风泽中孚', 61, 3, '六三三爻', '中中', 'Grade_ZhongZhong', '欲行还止，徘徊不已。动摇莫强，得止且止。', '一撮金·风泽中孚六三三爻'),
('YicuoJin_61_5', '风泽中孚', 61, 5, '九五五爻', '上上', 'Grade_ShangShang', '倾一杯，转愁眉。天地合，好施为。', '一撮金·风泽中孚九五五爻'),
('YicuoJin_62_1', '雷山小过', 62, 1, '初六初爻', '下下', 'Grade_XiaXia', '物不牢，人断桥。重整理，慢心高。', '一撮金·雷山小过初六初爻'),
('YicuoJin_62_3', '雷山小过', 62, 3, '九三三爻', '下下', 'Grade_XiaXia', '深户要牢扃，须防暗里人。莫言无外事，纵好定邅迍。', '一撮金·雷山小过九三三爻'),
('YicuoJin_62_5', '雷山小过', 62, 5, '六五五爻', '上上', 'Grade_ShangShang', '空空空，空里得成功。蟠桃千年熟，不怕五更风。', '一撮金·雷山小过六五五爻'),
('YicuoJin_63_1', '水火既济', 63, 1, '初九初爻', '上上', 'Grade_ShangShang', '鹿逐云中出，人从月下归。新欣盈笑脸，不用皱双眉。', '一撮金·水火既济初九初爻'),
('YicuoJin_63_3', '水火既济', 63, 3, '九三三爻', '上中', 'Grade_ShangZhong', '入而易，出而难。厌厌到再三，交加意不堪。', '一撮金·水火既济九三三爻'),
('YicuoJin_63_5', '水火既济', 63, 5, '九五五爻', '中中', 'Grade_ZhongZhong', '积德施功有子孙，杀牛祭佛及西邻。功名两字垂成日，回首山前万物新。', '一撮金·水火既济九五五爻'),
('YicuoJin_64_1', '火水未济', 64, 1, '初六初爻', '中中', 'Grade_ZhongZhong', '桑榆催晚景，缺月恐难圆。若遇刀锥客，方知有喜缘。', '一撮金·火水未济初六初爻'),
('YicuoJin_64_3', '火水未济', 64, 3, '六三三爻', '下中', 'Grade_XiaZhong', '万里片帆轻，波平浪不惊。行行无阴滞，远虑更通津。', '一撮金·火水未济六三三爻'),
('YicuoJin_64_5', '火水未济', 64, 5, '六五五爻', '上上', 'Grade_ShangShang', '芰荷香里许恩材，桂魄圆时印绶来。从此威名山岳重，光辉玉节位三台。', '一撮金·火水未济六五五爻');
INSERT INTO `xiangzi_rule` (`name`, `category`, `rule_key`, `rule_text`, `source_ref`, `label`) VALUES
('XiangZi_01_01', '六神笔式', '青龙', '笔式：丿、乀（蚕头燕额）。主事：主喜事。丿、乀——青龙要停匀，百事皆吉。青龙笔动喜还生，谋用营求事事通。人口增添财禄厚，主人日下尽亨通。', '卷之四·六神笔法/六神形式/六神主事', '相字·六神笔式·青龙'),
('XiangZi_01_02', '六神笔式', '朱雀', '笔式：乂（尖短交加）。主事：主官事、文书动，主失财、有口舌、生横事。乂——朱雀临身文书动，主失财，有口舌，生横事。忌惹人，有忧惊之事。朱雀交加口舌多，令人家内不安和。若逢水命方无怪，他命逢时有怨疴。', '卷之四·六神笔法/六神形式/六神主事', '相字·六神笔式·朱雀'),
('XiangZi_01_03', '六神笔式', '勾陈', '笔式：勹（弯弓斜月）。主事：主惊忧、迟滞、留连，忌土田，是非未决。勹——勾陈主惊忧、迟滞。忌土田。是非未决，并惹闲非。勾陈逢者事交加，谋事中间事事差。田宅官司多挠括，是非门内有喧哗。', '卷之四·六神笔法/六神形式/六神主事', '相字·六神笔式·勾陈'),
('XiangZi_01_04', '六神笔式', '腾蛇', '笔式：乙、乞（长曲势如行）。主事：主忧虑、梦不祥、作事多阻、有喧争。乙、乞——腾蛇主忧虑，梦不祥，作事多阻，有喧争，惹旧愁，宜守静。腾蛇遇者主惊虚，家宅逢之尽不宁。出入官谋宜慎取，免教仆马有灾形。', '卷之四·六神笔法/六神形式/六神主事', '相字·六神笔式·腾蛇'),
('XiangZi_01_05', '六神笔式', '白虎', '笔式：兄、凡、圭（尾尖口阔）。主事：主丧灾、孝服、疾病、官鬼、口舌。兄、凡、圭——白虎主有不祥之招。产、病有孝服，及官鬼，惹口舌，在囚狱。白虎逢之灾孝来，出门凡事不和谐。便防失脱家财损，足疾忧人百事乖。', '卷之四·六神笔法/六神形式/六神主事', '相字·六神笔式·白虎'),
('XiangZi_01_06', '六神笔式', '玄武', '笔式：厶、么（体态方尖）。主事：主盗贼、失脱、家宅流离。厶、么——玄武贵人华盖，主盗财，亦难寻。玄武动时主失脱，家宅流离慎方活。更防阴小有灾危，又至小人生拮括。', '卷之四·六神笔法/六神形式/六神主事', '相字·六神笔式·玄武'),
('XiangZi_02_01', '起六神卦诀', '甲', '青龙', '卷之四·起六神卦诀', '相字·起六神卦诀·甲'),
('XiangZi_02_02', '起六神卦诀', '乙', '青龙', '卷之四·起六神卦诀', '相字·起六神卦诀·乙'),
('XiangZi_02_03', '起六神卦诀', '丙', '朱雀', '卷之四·起六神卦诀', '相字·起六神卦诀·丙'),
('XiangZi_02_04', '起六神卦诀', '丁', '朱雀', '卷之四·起六神卦诀', '相字·起六神卦诀·丁'),
('XiangZi_02_05', '起六神卦诀', '戊', '勾陈', '卷之四·起六神卦诀', '相字·起六神卦诀·戊'),
('XiangZi_02_06', '起六神卦诀', '己', '腾蛇', '卷之四·起六神卦诀', '相字·起六神卦诀·己'),
('XiangZi_02_07', '起六神卦诀', '庚', '白虎', '卷之四·起六神卦诀', '相字·起六神卦诀·庚'),
('XiangZi_02_08', '起六神卦诀', '辛', '白虎', '卷之四·起六神卦诀', '相字·起六神卦诀·辛'),
('XiangZi_02_09', '起六神卦诀', '壬', '玄武', '卷之四·起六神卦诀', '相字·起六神卦诀·壬'),
('XiangZi_02_10', '起六神卦诀', '癸', '玄武', '卷之四·起六神卦诀', '相字·起六神卦诀·癸'),
('XiangZi_03_01', '五行笔式', '水', '水笔式：水圆多性巧。浊者定昏迷。水泛为不定。水走必东西。', '卷之四·五行体格式', '相字·五行笔式·水'),
('XiangZi_03_02', '五行笔式', '火', '火笔式：火重性不常。火燥见灾殃。火多攻心腹。火轻足衣粮。', '卷之四·五行体格式', '相字·五行笔式·火'),
('XiangZi_03_03', '五行笔式', '土', '土笔式：土重根基好。土轻离祖居。土滞破田宅。土定无虚图。', '卷之四·五行体格式', '相字·五行笔式·土'),
('XiangZi_03_04', '五行笔式', '金', '金笔式：金方利身主。金重性多刚。金走为神动。慷慨及门墙。', '卷之四·五行体格式', '相字·五行笔式·金'),
('XiangZi_03_05', '五行笔式', '木', '木笔式：木长性聪明。木短定功名。木多才学敏。木斜废支撑。', '卷之四·五行体格式', '相字·五行笔式·木'),
('XiangZi_04_01', '八卦断', '乾', '乾宫笔法如鸡脚，父母初年早见伤。若不早年离侍下，也须抱疾及为凶。', '卷之四·八卦断', '相字·八卦断·乾'),
('XiangZi_04_02', '八卦断', '坤', '坤宫属母看荣华，切忌勾陈杀带斜。一点定分荣禄位，一生富贵最堪夸。', '卷之四·八卦断', '相字·八卦断·坤'),
('XiangZi_04_03', '八卦断', '艮', '艮位排来兄弟宫，勾陈位笔性他凶。纵然不克并州破，也主商参吴楚中。', '卷之四·八卦断', '相字·八卦断·艮'),
('XiangZi_04_04', '八卦断', '巽', '巽宫带口子难逢，见子须知有克刑。饶君五个与三个，未免难为一个成。', '卷之四·八卦断', '相字·八卦断·巽'),
('XiangZi_04_05', '八卦断', '震', '震位东方一位间，要他笔正莫凋残。若逢祐断须沾疾，腰脚交他不得安。', '卷之四·八卦断', '相字·八卦断·震'),
('XiangZi_04_06', '八卦断', '离', '离是南方火位居，看他一点定荣枯。若还圆净荣官禄，燥火炎炎定不愚。', '卷之四·八卦断', '相字·八卦断·离'),
('XiangZi_04_07', '八卦断', '坎', '坎为财帛定卦位，水星笔横占他方。若见笔尖无大小，根基至老主荣昌。', '卷之四·八卦断', '相字·八卦断·坎'),
('XiangZi_04_08', '八卦断', '兑', '兑位西方太白间，只宜正直莫凋残。若然坑陷并尖缺，妻子骄奢保守难。', '卷之四·八卦断', '相字·八卦断·兑'),
('XiangZi_05_01', '六神形式', '青龙', '丿、乀。蚕头燕额是青龙。凡撇捺长而有头角之样，即作青龙，如撇短则不足以成青龙之式。不拘撇捺皆化木。如无须角，虽长亦非青龙。', '卷之五·六神形式', '相字·六神形式·青龙'),
('XiangZi_05_02', '六神形式', '朱雀', '乂、丿。尖短交加朱雀神。撇短而有尖嘴之形，则为朱雀。主文书事，原属火无化。', '卷之五·六神形式', '相字·六神形式·朱雀'),
('XiangZi_05_03', '六神形式', '腾蛇', '乙、乞。腾蛇长曲势如行。其样如蛇，皆化火看，亦主文书及惊怪等。', '卷之五·六神形式', '相字·六神形式·腾蛇'),
('XiangZi_05_04', '六神形式', '勾陈', '勹、乙。弯弓斜月勾陈象。凡带长者是也，属土，无化，主羁滞。', '卷之五·六神形式', '相字·六神形式·勾陈'),
('XiangZi_05_05', '六神形式', '白虎', '兄、凡、圭。尾尖口阔方为虎。口不开者，非虎也。化作金用，主疾病，凶兆也。', '卷之五·六神形式', '相字·六神形式·白虎'),
('XiangZi_05_06', '六神形式', '玄武', '厶、么、云。体态方尖玄武形。化木主盗贼事，又主波浪险阻等事。', '卷之五·六神形式', '相字·六神形式·玄武'),
('XiangZi_06_01', '五行全备', '一点', '丶：如一点端正，无破绽鸦嘴等形，则是五行全。如不合式，仍属水。', '卷之五·五行全备', '相字·五行全备·一点'),
('XiangZi_06_02', '五行全备', '一画', '一：亦五行全。此象乃庖羲氏画卦之初而混元一气之数也。', '卷之五·五行全备', '相字·五行全备·一画'),
('XiangZi_06_03', '五行全备', '太极', '〇：此太极未分时，亦五行全大之象也。', '卷之五·五行全备', '相字·五行全备·太极'),
('XiangZi_06_04', '五行全备', '四匡', '口：歌曰「四匡无风全五行」，是亦五行全也。如「国」字、「园」字之类，四匡紧紧不透风乃是。如笔稀者不是；口小者属金，亦不是。此地之象也。', '卷之五·五行全备', '相字·五行全备·四匡'),
('XiangZi_06_05', '五行全备', '总诀', '一点一画五行全，试看首尾秘为占。点画若无疵笔露，功名发达享高年。', '卷之五·五行全备', '相字·五行全备·总诀'),
('XiangZi_07_01', '神煞', '贵神', '中、上、贝、日、月、大、人', '卷之五·拆字杂编', '相字·神煞·贵神'),
('XiangZi_07_02', '神煞', '喜神', '士、口、言、鸟。士头口体喜神俱，嫁娶婚姻百事宜。只怕重重见火土，许多克伐反非奇。', '卷之五·拆字杂编', '相字·神煞·喜神'),
('XiangZi_07_03', '神煞', '福星', '不、田（凡子孙动者亦作福星看）。', '卷之五·拆字杂编', '相字·神煞·福星'),
('XiangZi_07_04', '神煞', '文星', '二、乂、曰、子', '卷之五·拆字杂编', '相字·神煞·文星'),
('XiangZi_07_05', '神煞', '印星', '口、囗、子', '卷之五·拆字杂编', '相字·神煞·印星'),
('XiangZi_07_06', '神煞', '马星', '灬、辶、走。马星原是弯弓脚，四点原来用亦同。', '卷之五·拆字杂编', '相字·神煞·马星'),
('XiangZi_07_07', '神煞', '禄神', '甲禄在寅，乙禄在卯，丙戊禄在巳，丁己禄在午，庚禄在申，辛禄在酉，壬禄在亥，癸禄在子（俱以占者年庚本命，于求之笔画为准）。', '卷之五·拆字杂编', '相字·神煞·禄神'),
('XiangZi_07_08', '神煞', '会神', '田、曰、云、禺。有田有日会神兴，见客逢人不必寻。', '卷之五·拆字杂编', '相字·神煞·会神'),
('XiangZi_07_09', '神煞', '生神', '一、丶、元、甲、子、初（一者数之始，元者鸿朦之初，甲子乃干支之首，故皆为生神）。', '卷之五·拆字杂编', '相字·神煞·生神'),
('XiangZi_07_10', '神煞', '亡神', '十、千、百、万、贞、亥、癸（十千百万皆数之终，贞乃元之尽，亥癸是干支之末，故为亡神）。', '卷之五·拆字杂编', '相字·神煞·亡神'),
('XiangZi_07_11', '神煞', '家神', '宀、乇、火（灶神以四点同）、土（奥神）、堂（香火神）、水（井神，三点亦同用）。', '卷之五·拆字杂编', '相字·神煞·家神'),
('XiangZi_07_12', '神煞', '官符', '宀、付', '卷之五·拆字杂编', '相字·神煞·官符'),
('XiangZi_07_13', '神煞', '文书', '二、乂、丿、乙（朱雀、腾蛇皆是）。', '卷之五·拆字杂编', '相字·神煞·文书'),
('XiangZi_07_14', '神煞', '灾煞（病符）', '巛、宀、火、广、丙、矢（字中见旧太岁亦为病符星）。', '卷之五·拆字杂编', '相字·神煞·灾煞（病符）'),
('XiangZi_07_15', '神煞', '天狗煞', '字中见太岁，前年干支是也（如子午见戌，申年见壬，皆是）。', '卷之五·拆字杂编', '相字·神煞·天狗煞'),
('XiangZi_07_16', '神煞', '科名星', '禾、斗（以本人年甲所属是科名，如甲乙以一直，丙人以一撇，皆科名也）。年干所属是科名，禾斗皆为首占星。有此求名皆遂意，如无考试定成空。', '卷之五·拆字杂编', '相字·神煞·科名星'),
('XiangZi_07_17', '神煞', '丧门', '白、兄', '卷之五·拆字杂编', '相字·神煞·丧门'),
('XiangZi_07_18', '神煞', '空亡', '即六甲空亡，「甲子旬中空戌亥」之类是也（假如甲子旬中空，占即以腰间一点为亥空，以长画为戌空）。', '卷之五·拆字杂编', '相字·神煞·空亡'),
('XiangZi_07_19', '神煞', '宜神', '子为财之宜神，鬼为父之宜神，兄为子之宜神，财为鬼之宜神，父为兄之宜神是也。', '卷之五·拆字杂编', '相字·神煞·宜神'),
('XiangZi_07_20', '神煞', '忌神', '子为鬼之忌神，鬼为兄之忌神，兄为财之忌神，财为父之忌神，父为子之忌神是也。', '卷之五·拆字杂编', '相字·神煞·忌神'),
('XiangZi_07_21', '神煞', '主神', '眼前小事日千寻，代友占亲看纳音。疾病官非详本命，字中末笔主终身。', '卷之五·拆字杂编', '相字·神煞·主神'),
('XiangZi_07_22', '神煞', '用神', '官鬼父母才兄子，据事参详要仔细。认定一笔作用神，此为相字真消息。', '卷之五·拆字杂编', '相字·神煞·用神'),
('XiangZi_08_01', '笔画歌诀', '笔画稳重', '衣食丰隆', '卷之四·字画指迷', '相字·笔画歌诀·笔画稳重'),
('XiangZi_08_02', '笔画歌诀', '笔画平直', '丰衣足食', '卷之四·字画指迷', '相字·笔画歌诀·笔画平直'),
('XiangZi_08_03', '笔画歌诀', '笔画端正', '衣禄铁定', '卷之四·字画指迷', '相字·笔画歌诀·笔画端正'),
('XiangZi_08_04', '笔画歌诀', '笔画分明', '决定前程', '卷之四·字画指迷', '相字·笔画歌诀·笔画分明'),
('XiangZi_08_05', '笔画歌诀', '笔画圆静', '富贵双并', '卷之四·字画指迷', '相字·笔画歌诀·笔画圆静'),
('XiangZi_08_06', '笔画歌诀', '笔画肥浓', '富贵无穷', '卷之四·字画指迷', '相字·笔画歌诀·笔画肥浓'),
('XiangZi_08_07', '笔画歌诀', '笔画洁净', '功名可决', '卷之四·字画指迷', '相字·笔画歌诀·笔画洁净'),
('XiangZi_08_08', '笔画歌诀', '笔画轻快', '诸事通泰', '卷之四·字画指迷', '相字·笔画歌诀·笔画轻快'),
('XiangZi_08_09', '笔画歌诀', '笔画刚健', '力量识见', '卷之四·字画指迷', '相字·笔画歌诀·笔画刚健'),
('XiangZi_08_10', '笔画歌诀', '笔画精神', '必有声名', '卷之四·字画指迷', '相字·笔画歌诀·笔画精神'),
('XiangZi_08_11', '笔画歌诀', '笔画光发', '荣显通达', '卷之四·字画指迷', '相字·笔画歌诀·笔画光发'),
('XiangZi_08_12', '笔画歌诀', '笔画气势', '慷慨意志', '卷之四·字画指迷', '相字·笔画歌诀·笔画气势'),
('XiangZi_08_13', '笔画歌诀', '笔画宽洪', '逞英逞雄', '卷之四·字画指迷', '相字·笔画歌诀·笔画宽洪'),
('XiangZi_08_14', '笔画歌诀', '笔画尖小', '其人必了', '卷之四·字画指迷', '相字·笔画歌诀·笔画尖小'),
('XiangZi_08_15', '笔画歌诀', '笔画如线', '有识有见', '卷之四·字画指迷', '相字·笔画歌诀·笔画如线'),
('XiangZi_08_16', '笔画歌诀', '笔画似绳', '一世平宁', '卷之四·字画指迷', '相字·笔画歌诀·笔画似绳'),
('XiangZi_08_17', '笔画歌诀', '笔画挑剔', '奸巧衣食', '卷之四·字画指迷', '相字·笔画歌诀·笔画挑剔'),
('XiangZi_08_18', '笔画歌诀', '笔画乌梅', '面相恢恢', '卷之四·字画指迷', '相字·笔画歌诀·笔画乌梅'),
('XiangZi_08_19', '笔画歌诀', '笔画懒淡', '兄弟离散', '卷之四·字画指迷', '相字·笔画歌诀·笔画懒淡'),
('XiangZi_08_20', '笔画歌诀', '笔画分扫', '破家必早', '卷之四·字画指迷', '相字·笔画歌诀·笔画分扫'),
('XiangZi_08_21', '笔画歌诀', '笔画弯曲', '奸巧百出', '卷之四·字画指迷', '相字·笔画歌诀·笔画弯曲'),
('XiangZi_08_22', '笔画歌诀', '笔画迭荡', '一生浮浪', '卷之四·字画指迷', '相字·笔画歌诀·笔画迭荡'),
