INSERT INTO `precept` (`local`, `label`, `admonition`) VALUES
('WuShi', '无事不占', '无具体事项不可起卦。'),
('BuCheng', '不诚不占', '意念不纯，请诚心再问。'),
('BuYi', '不义不占', '此事悖于道义，不可占。'),
('ChongGua', '重卦不占', '一事一卦，反复求卦反失其机。');
INSERT INTO `zuo_duan` (`name`, `text`) VALUES
('乾', '乾宫：土生之或有吉兆→主老人尊长分上见吉庆；火克之或有凶兆→主老人长上有忧'),
('坤', '坤宫：火生之或有吉兆→主母亲阴人有吉利之喜；见克或有凶兆→主老母阴人有灾厄'),
('震', '震宫：水生之及东方震宫有吉兆→喜在长子长孙；见克或见凶→长子长孙不利'),
('坎', '坎宫：宜见五金及吉利之谶→喜在中男；土克或见凶→忧在中男'),
('离', '离宫：喜木生之或有可应→中女有喜；遇克或见凶→中女有厄'),
('艮', '艮宫：宜火生之、见吉→少男之喜；遇克或见凶→灾及少男，问产必不育'),
('兑', '兑宫：土宜生之、见吉→少女有喜或有欢悦；遇克或见凶→少女有灾');
INSERT INTO `shi_da_ying` (`name`, `text`) VALUES
('裹头', '七裹头：官司立见口舌。火，大官司，水土比和，财无，小人分上，口舌呕气。病主阴人小口灾。'),
('跣足', '八跣足：官司破财，外人欺，心下惊慌。火主破财，土不凶。病有孝至。'),
('担', '五担：官司被人自惊，与面说人成口舌。问信见水土得财。金木客至。病有犯，四肢沉重不能起。'),
('券', '六券：官司不成，火有财，水土有灾，心下不安，有贵人，主口舌，不凶。'),
('卧', '四卧：问官司，侧睡者，欲起必作，主阴人事。金有财，火事发破财。土水无财难就。土木有财。'),
('一行', '一行：问官司，属木，旺木有文书；属火，有官司；财金木，财有至。有客至问病，人火潮热，金水米浆。'),
('二立', '二立：官司不发，水土无金，大小口舌，病不凶。财水土，有贵人至，文书发动。'),
('三坐', '三坐：问官司，有讼不成。主财属火，主和劝。金败财，木得财。病脚，右足犯林木神，有祸不凶。'),
('九喜', '九喜：官司自己无主，外人有请，劝官司。有酒肉，别人事。口舌纷纷，求财不许。不凶。'),
('十怒', '十怒：官司主外人欺凌，不见官，主破财，倚人脱卸。火惊病凶。');
INSERT INTO `gua_ying` (`name`, `text`) VALUES
('乾', '天文雪、老阳；天气寒；凶盗军弓手贼强横停尸；官贵朝贵盐司太守座主；身体顶面颊辅；性情刚健正直尊重好高战吉；声音正清商；信音朝信改召命荐举关升义亲；事意上卦为形象之家下卦为强横之辈；疾病手太阳脉弦紧、天威所发、上壅目热、寒热；附药丸子；食物饼子之赤者手饼馒头荷包羹猪头脑骨头珍粉馄钝；谷果粟栗瓜豆龙眼荔；禽兽雀鹇鹗鹏鹰；衣服赤玄色；器用圆物盏注子盘水晶玉环定器球；财恩义交货钱马之类；禄壬申；字方圆形字有头者须旁八卦；策二百一十六；轨七百六十八'),
('坤', '天文雾露云阴；地理郡国宫阙城邑墙壁；人物母妻儒农僧；凶盗奴婢藏在僻处；官贵大臣教官考校文字；生育女肥厚；性情顺缓不信事顽钝无慈爱；声音宫音；事意迟滞顽懦悭吝从容；疾病手、太阴侯、腹痛、脾胃闭、脉沉伏；饮食藜羹烧熬冻物鹅鸭肺太牢饮食饴糖；五味苦辣甘；果品取物件；音信顺遂可许为捷应、辰戌丑未月日；财物束修抄题僧衣布裳；婚姻富家庄家商家丑拙性吝大腹壮迟钝面黄；器用轿车瓦器田具沙器；禽兽牛牝马鸥雀鸦鸽；字圭金四牛旁；禄癸酉；策一百四十四；轨六百七十一'),
('震', '天文雷虹霓电；地理屋市宅门户枋；方所正东；人物商旅将帅工匠；凶盗东去男人盗；官贵监司郡守刑幕巡检法官；生育长男转动虚惊怪异；性情始刚故决断、急于动故躁；婚姻官宦家技巧工、女容心神好、动静易转；声音上下角、上平声、三音七声；信音所许不至；事意旧事重叠有名无实；病疾气积冷伤胃、四体劳倦、温冷伤食；药足太阳脉洪浮；宴会酒会玩赏期集；食物面食包子酒时新之物；谷果芋小豆稼时新之果；禽兽蜂蝶白鹭鹤；器用木器盘竹器筐算盘舟车兵车轿器皿瓶盏瓯乐器鼓；衣物裙腰带缠带；缠带绳匹帛青玄黄之；财阴人取索竹木钱；禄庚；字走竹旁立画偏；色青玄黄；策一百六十八；轨七百四'),
('巽', '天文风；地理林苑园囿；人物命妇药婆工术女；凶盗奴婢商量取去宜急求之；官贵典狱考校干官休究；身体耳目胆发命口肢；生育长女胎月少莹白；性情鄙野悭吝艰苦号咷；婚姻命妇宗室女委望进退；声音角音、角仄声、三声四声上下；信音召命报捷辟差举状；事意荐举呈发申审号令听命；疾病手足厥会和之气候三十日、脉濡弱、饮食伤胃、宿酒、痞膈、为臭、水谷不化；药草药；宴会家筵客不齐；谷果麻粉茶；食物长面粉羹脍鸡鱼肠肚酸物、下卦为鹅鸭；器用竹木草具绳丝弦索乐器；禽兽鸡鹅鸭鱼善鸣之虫禽、上卦飞下卦走；衣物衣绳丝；色青绿碧白紫色；财利市喜羹、租钱、料钱、那免；禄辛；字草木竹旁、丝、鱼、菜、舟、齿足疾、大豆、辣；策百九十二；轨七百三十六'),
('坎', '天文月虹云霜；地理海阔水泉沟渎厕；方所正北、丘墓中、狐兔穴中；人物僧道；凶盗乘便而来、脱头露尾、易败必获；官贵漕运钱粮漕官运属；身体发膏血；生产难产、中男、清秀；性情心机阴险、智随圆、委曲；婚姻富家酒家亲家用性；声音羽中上卦、羽平六声下卦；信音反复犹豫、小人欺诈、佞、狡狯、盗贼、狱讼；疾病足太阴之气、脉滑芤；附药补肾药、或酒水下；食物酒咸物豕鱼海味中硬而核腰子；谷果麦枣梅李桃、外柔内坚、有核；禽兽鹿豕象豚狐燕螺；器用酒器车轮败车；衣物青黑色；财争讼之财和合打偏财；字两头点水、全水、月、小弓之属；禄戌；色黑皂白；策百六十八；轨七百零四'),
('离', '天文日霞电晴；地理殿堂中堂檐厨灶；方所正南；人物为将帅兵戈甲之士；凶盗妇人盗、从南方去；官贵翰苑教官通判、任官南方；身体三焦小肠目心；生育次女、多性燥啼哭；性情聪明、见事明了；信音朝信、文书、报捷、契券；事意忧疑、聒拓、喧哄、性急、虚忧；疾病手足二君太阳明三相火、眼病、气燥、热疾、发狂；禽兽凤有文彩、鳖螺蚌蟹螯蛤蠃、鹑鹤飞鸟、牝羊；食物馄饨蟹鳖蚌、介虫之属、中虚物、炙煎物；谷果谷实粱藕、外坚内柔之物、棘木之花叶枯枝；器用灯火之具、外坚内柔之物、屏幕帘旗帜戈兵甲胄、盘甑瓶缴壁一应中虚之物、窑灶炉冶盒子瓮笼；衣物赤红紫色；财远旧取索、意外之物；字火日旁；禄巳；策百九十二；轨七百六十三'),
('艮', '天文星烟；地理山径墙巷丘园门墙阑阍寺宗庙；方所东北方、艮门墙、寺；人物阍寺仆隶官僚保人；凶盗以下所使警迹人；官贵山郡无迁转；身体手指鼻肋脾胃；生产损胎次男；性情濡滞多疑、优游、内刚中软；声音清上平、一音、十二音、三声；事意反复进退、去就多疑；疾病手太阳、久患脾胃、股疾、脉沉伏；附药湿土石药；宴会常酣期集；谷果豆大小粟；食物妆点之物、所食不一、酒浆、杂蒸之物、冻物、杂羹、有汁物、鸭鹅、甘味；禽兽牝牛子母牛、鹄鹘鸦鹊雀鹜鸥、鼠；器用轿舆犁具兵甲器陶冶瓦器锅釜瓶瓮簋伞钱袋磁器踏镫螺蜔盒子、内柔外刚之物；衣物黄裳僧衣黑皂彩帛袋布；禄丙；财旧钱、置转货买田土、趁钱；字土牛田旁；策百六十八；轨七百零四'),
('兑', '天文雨露、春雾细雨、夏秋重雾、冬大雪、上为雨下为露；地理井泉泗泽；方所西方；人物先生客人巫匠媒人牙人少女妾娼；官贵学官将帅县令考校乐友、赴任西方；凶盗家使僮仆藏于僻地；身体口肺膀胱大肠辅颊舌太阳；生育少女一胎、月不足、多奇异；性情喜悦口舌多美；声音商上、下商之浊四声；婚姻平常之家、少女媚悦；信音喜酉丑时日至；事意唇吻、口舌、谗谤相欺、争打妇人、暗昧；疾病口痛、唇齿、咽喉、危困；附药剉剂；宴会讲书会友请先生吟赏；食物包子、有口舌物、糖饼烧饼肝肺；谷果栗黍枣李胡桃石榴；禽兽羔羊鹿猿虎豹豺鹭鱼；器用席铁铜钱器皿酒盏瓶瓯、有口器或损缺；衣物彩；财束修含水；禄丁；字家金钩口旁；色素白；策一百九十二；轨七百三十六');
INSERT INTO `domain_lore` (`collection`, `k`, `text`) VALUES
('RI_YING', '木', '本日属木（寅卯日）。以体卦为主，看体卦与本日衰旺如何——卦宜生体、宜比和；不宜克体，亦不宜体卦生之。'),
('RI_YING', '火', '本日属火（巳午日）。以体卦为主，看体卦与本日衰旺如何——卦宜生体、宜比和；不宜克体，亦不宜体卦生之。'),
('RI_YING', '金', '本日属金（申酉日）。以体卦为主，看体卦与本日衰旺如何——卦宜生体、宜比和；不宜克体，亦不宜体卦生之。'),
('RI_YING', '水', '本日属水（亥子日）。以体卦为主，看体卦与本日衰旺如何——卦宜生体、宜比和；不宜克体，亦不宜体卦生之。'),
('RI_YING', '土', '本日属土（辰戌丑未日）。以体卦为主，看体卦与本日衰旺如何——卦宜生体、宜比和；不宜克体，亦不宜体卦生之。'),
('NIAO_SHOU_SHI_RI', '庚', '庚日见鸡鸣——此乃凶刃之杀（凶兆）。'),
('NIAO_SHOU_SHI_RI', '丁', '丁日见羊过——此乃凶刃之杀（凶兆）。'),
('NIAO_SHOU_SHI_RI', '己', '己日值马来——此皆食禄之兆（吉兆）。'),
('NIAO_SHOU_SHI_RI', '壬', '壬日有猪过——此皆食禄之兆（吉兆）。'),
('DONG_XUAN_GE', '宅气如春', '「若还宅气如春意，家宅生和气」——主家宅和顺（吉）'),
('DONG_XUAN_GE', '冷落似秋', '「若然冷落似秋时，从此渐衰微」——主家门渐衰（凶）'),
('DONG_XUAN_GE', '馨香如兰', '「自然馨香如兰室，福至无虚日」——主福至不绝（吉）'),
('DONG_XUAN_GE', '秽薰腥', '「鸡豚猫犬秽薰腥，贫病至相侵」——主贫病交侵（凶）'),
('DONG_XUAN_GE', '男妆女饰', '「男妆女饰皆齐整，此去门风盛」——主门风兴盛（吉）'),
('DONG_XUAN_GE', '垢面', '「家人垢面与蓬头，定见有悲忧」——主有悲忧（凶）'),
('DONG_XUAN_GE', '儿啼妇叹', '「儿啼妇叹情怀悄，祸害道阴小」——主阴小有祸（凶）'),
('DONG_XUAN_GE', '老人无故泣', '「老人无故泣双垂，不日见愁悲」——主近日愁悲（凶）'),
('DONG_XUAN_GE', '墙壁缺', '「门前墙壁缺，家道中消歇」——主家道中落（凶）'),
('DONG_XUAN_GE', '向门流', '「溜漕水势向门流，财帛永难收」——主财帛难聚（凶）'),
('DONG_XUAN_GE', '屋上生奇草', '「忽然屋上生奇草，益荫人家好」——主益荫人家（吉）'),
('DONG_XUAN_GE', '绝尘埃', '「门户幽爽绝尘埃，必定出高才」——主出高才（吉）'),
('DONG_XUAN_GE', '破履当门', '「偶悬破履当门户，必有奴欺主」——主奴欺主（凶）'),
('DONG_XUAN_GE', '边门', '「长长破碎在边门，断不利家君」——主不利家长（凶）'),
('DONG_XUAN_GE', '桃花艳', '「遮门临井桃花艳，内有风情染」——主门内风情之染（凶）'),
('DONG_XUAN_GE', '高桐', '「屋前屋后有高桐，离别主人翁」——主离别主人（凶）'),
('DONG_XUAN_GE', '高梨树', '「井边倘种高梨树，长有离乡土」——主离乡（凶）'),
('DONG_XUAN_GE', '焚香', '「祠堂神主忽焚香，火厄恐相招」——主火厄（凶）'),
('DONG_XUAN_GE', '檐前瓦片', '「檐前瓦片当门堕，诸事愁崩破」——主诸事崩破（凶）'),
('DONG_XUAN_GE', '破碗', '「若抛破碗厕坑中，从此见贫穷」——主贫穷（凶）'),
('DONG_XUAN_GE', '灯在地', '「白昼不宜灯在地，死者还相继」——主丧事相继（凶）'),
('DONG_XUAN_GE', '鼠向日中', '「公然鼠向日中来，不日资财耗」——主资财耗散（凶）'),
('DONG_XUAN_GE', '牝鸡', '「牝鸡早晚鸣咿喔，阴盛家消索」——主阴盛家消（凶）'),
('DONG_XUAN_GE', '中堂犬吠', '「中堂犬吠立而啼，人眷有灾厄」——主人眷灾厄（凶）'),
('DONG_XUAN_GE', '鹊噪连声', '「清晨鹊噪连声继，远信行人至」——主远信行人至（吉）'),
('DONG_XUAN_GE', '蟒蛇', '「蟒蛇偶尔入人家，人病见妖邪」——主人病妖邪（凶）'),
('DONG_XUAN_GE', '雀群争逐', '「雀群争逐当门盛，口舌纷纷定」——主口舌纷争（凶）'),
('DONG_XUAN_GE', '鹏鸟', '「偶然鹏鸟（即鸱鸮也）叫当门，人口有迍逢」——主人口迍邅（凶）'),
('DONG_XUAN_GE', '群羊', '「入门若见有群羊，家主病瘟黄」——主家主病（凶）'),
('DONG_XUAN_GE', '舟船', '「舟船若安在平地，虽稳成淹滞」——主事成而淹滞'),
('DONG_XUAN_GE', '树荫过墙', '「他家树荫过墙来，多得横来财」——主得横财（吉）'),
('DONG_XUAN_GE', '石砌多残折', '「阶前石砌多残折，成事多衰灭」——主成事衰灭（凶）'),
('DONG_XUAN_GE', '茶果应声', '「入门茶果应声来，中馈主家财」——主中馈掌财（吉）'),
('DONG_XUAN_GE', '炊烟早', '「三餐时候炊烟早，家道渐基好」——主家道渐兴（吉）'),
('DONG_XUAN_GE', '宿火不成', '「连宵宿火不成时，人散与财离」——主人散财离（凶）'),
('WAN_WU_GE', '喧闹', '「或闻何处喧闹，主有斗争」'),
('WAN_WU_GE', '笑语', '「或听此间笑语，必逢吉庆」'),
('WAN_WU_GE', '儿妇啼叹', '「儿妇啼叹，其家阴小有灾」'),
('WAN_WU_GE', '军来', '「吏至军来，必有官司词讼」'),
('WAN_WU_GE', '枷锁', '「或逢枷锁而枷锁临身」（主官灾缠身）'),
('WAN_WU_GE', '鞭杖', '「倘遇鞭杖而鞭杖必至」（主受刑责）'),
('WAN_WU_GE', '负肉', '「屠而负肉，此为骨肉有灾」'),
('WAN_WU_GE', '血光', '「倘逢血光，而又恐灾于孳畜」'),
('WAN_WU_GE', '药饵', '「师巫药饵，病患临门」'),
('WAN_WU_GE', '见饭', '「见饭则有犯家先」'),
('WAN_WU_GE', '逢酒', '「逢酒则欠神愿」'),
('WAN_WU_GE', '阴人至', '「阴人至则女子有厄」'),
('WAN_WU_GE', '阳人至', '「阳人至则男子当灾」'),
('WAN_WU_GE', '披麻带孝', '「披麻带孝，必然孝服临头」'),
('WAN_WU_GE', '持杖而号', '「持杖而号，定主号泣满室」'),
('WAN_WU_GE', '鼓乐', '「其或鼓乐声喧，又见酒杯器皿，若不迎婚嫁娶，定须会客宴酣」'),
('WAN_WU_GE', '酒杯器皿', '「又见酒杯器皿，若不迎婚嫁娶，定须会客宴酣」'),
('WAN_WU_GE', '柴炭', '「逢柴炭主忧」'),
('WAN_WU_GE', '折麦', '「折麦主悲」'),
('WAN_WU_GE', '禾与鞋', '「禾与鞋，万事和谐」'),
('WAN_WU_GE', '棋与药', '「棋与药，与人期约」'),
('WAN_WU_GE', '斧锯', '「斧锯必有修造」'),
('WAN_WU_GE', '粮储', '「粮储必有远行」'),
('WAN_WU_GE', '禽鸣', '「闻禽鸣，谋事虚说」'),
('WAN_WU_GE', '鼓声', '「听鼓声，交易空虚」'),
('WAN_WU_GE', '润睫', '「拭目润睫，内有哭泣之事」'),
('WAN_WU_GE', '持刃见血', '「持刃见血，外面有虫毒之谋」'),
('WAN_WU_GE', '柜箱', '「柜箱为藏财之用」'),
('WAN_WU_GE', '绳索', '「绳索为穿钱之物」'),
('WAN_WU_GE', '金帛宝货', '「逢金帛宝货之类，理必有成」'),
('WAN_WU_GE', '刀刃剑具', '「遇刀刃剑具之器，损而无益」'),
('WAN_WU_GE', '鸦鸣', '「鸦鸣而祸事将临」'),
('WAN_WU_GE', '鹊噪', '「鹊噪而喜色已动」'),
('WAN_WU_GE', '见水', '「见水为饮食酒汤」'),
('WAN_WU_GE', '遇火', '「遇火为煎炮烙炙」'),
('WAN_WU_GE', '见米', '「见米为一饭之得」'),
('WAN_WU_GE', '提壶', '「提壶为酌杯之礼」'),
('WAN_WU_GE', '刀砧', '「刀砧乃薰腥美味」');
