('SAN_YAO_LING_YING', '根核流落', '〔三要灵应·草木之应〕根核流落主牵连'),
('SAN_YAO_LING_YING', '奇葩', '〔三要灵应·草木之应〕奇葩端的虚花'),
('SAN_YAO_LING_YING', '嘉果', '〔三要灵应·草木之应〕嘉果可以结实'),
('SAN_YAO_LING_YING', '乌鸦', '〔三要灵应·禽兽之应〕乌鸦报灾'),
('SAN_YAO_LING_YING', '蟢虫', '〔三要灵应·禽兽之应〕蟢虫报喜'),
('SAN_YAO_LING_YING', '鸿雁', '〔三要灵应·禽兽之应〕鸿雁主朋友之信'),
('SAN_YAO_LING_YING', '蛇', '〔三要灵应·禽兽之应〕蛇虺防毒害之谋'),
('SAN_YAO_LING_YING', '鼠啮衣', '〔三要灵应·禽兽之应〕鼠啮衣，有小口之灾'),
('SAN_YAO_LING_YING', '雀噪檐', '〔三要灵应·禽兽之应〕雀噪檐，有远行之至'),
('SAN_YAO_LING_YING', '犬斗', '〔三要灵应·禽兽之应〕犬斗恐招盗贼'),
('SAN_YAO_LING_YING', '鸡斗', '〔三要灵应·禽兽之应〕鸡斗主有喧争'),
('SAN_YAO_LING_YING', '牵羊', '〔三要灵应·禽兽之应〕牵羊者，喜庆将临'),
('SAN_YAO_LING_YING', '骑马', '〔三要灵应·禽兽之应〕骑马者，出入皆利'),
('SAN_YAO_LING_YING', '猿猴攀木', '〔三要灵应·禽兽之应〕猿猴攀木，身心不定'),
('SAN_YAO_LING_YING', '鲤鱼出水', '〔三要灵应·禽兽之应〕鲤鱼出水，变化不凡'),
('SAN_YAO_LING_YING', '绳拴马', '〔三要灵应·禽兽之应〕绳拴马，疾病难安'),
('SAN_YAO_LING_YING', '架陷禽', '〔三要灵应·禽兽之应〕架陷禽，因人未脱'),
('SAN_YAO_LING_YING', '酒樽', '〔三要灵应·杂见观物之应〕酒樽忽破，乐极生悲'),
('SAN_YAO_LING_YING', '良医', '〔三要灵应·杂见观物之应〕良医道逢，难中有救'),
('SAN_YAO_LING_YING', '藤萝', '〔三要灵应·杂见观物之应〕藤萝之类堪依倚'),
('SAN_YAO_LING_YING', '虎豹', '〔三要灵应·杂见观物之应〕虎豹之象可施威'),
('SAN_YAO_LING_YING', '耕田锄地', '〔三要灵应·杂见观物之应〕耕田锄地者，事势必翻'),
('SAN_YAO_LING_YING', '破竹剖竿', '〔三要灵应·杂见观物之应〕破竹剖竿者，事势必顺'),
('SAN_YAO_LING_YING', '春花秋月', '〔三要灵应·杂见观物之应〕春花秋月，虽无实而阚景'),
('SAN_YAO_LING_YING', '夏绵冬葛', '〔三要灵应·杂见观物之应〕夏绵冬葛，虽有用而背时'),
('SAN_YAO_LING_YING', '晴伞', '〔三要灵应·杂见观物之应〕晴伞，渐逢闲废'),
('SAN_YAO_LING_YING', '泡影电光', '〔三要灵应·杂见观物之应〕泡影电光，虚幻难信'),
('SAN_YAO_LING_YING', '蛛丝蚕茧', '〔三要灵应·杂见观物之应〕蛛丝蚕茧，巧计方成'),
('SAN_YAO_LING_YING', '凉扇', '〔三要灵应·杂见观物之应〕凉扇，多主气捐'),
('SAN_YAO_LING_YING', '鹿', '〔三要灵应·物叶音〕见鹿可以问禄'),
('SAN_YAO_LING_YING', '蜂', '〔三要灵应·物叶音〕见蜂可以言封'),
('SAN_YAO_LING_YING', '梨', '〔三要灵应·物叶音〕梨主分离'),
('SAN_YAO_LING_YING', '桃', '〔三要灵应·物叶音〕桃主逃走'),
('SAN_YAO_LING_YING', '见李', '〔三要灵应·物叶音〕见李则问讼得理'),
('SAN_YAO_LING_YING', '逢冠', '〔三要灵应·物叶音〕逢冠则问名得官'),
('SAN_YAO_LING_YING', '鞋', '〔三要灵应·物叶音〕鞋为百事和谐'),
('SAN_YAO_LING_YING', '榼', '〔三要灵应·物叶音〕榼为诸事可合'),
('SAN_YAO_LING_YING', '我心忧', '〔三要灵应·自己之应〕我心忧者，彼事亦忧'),
('SAN_YAO_LING_YING', '我心乐', '〔三要灵应·自己之应〕我心乐者，彼事亦乐'),
('SAN_YAO_LING_YING', '我适闲', '〔三要灵应·自己之应〕我适闲，彼当从容'),
('SAN_YAO_LING_YING', '我值忙', '〔三要灵应·自己之应〕我值忙，彼当窘迫'),
('SAN_YAO_LING_YING', '将叛者', '〔三要灵应·动静之应〕将叛者，其辞惭'),
('SAN_YAO_LING_YING', '将疑者', '〔三要灵应·动静之应〕将疑者，其辞支'),
('SAN_YAO_LING_YING', '吉人', '〔三要灵应·动静之应〕吉人之辞寡'),
('SAN_YAO_LING_YING', '躁人', '〔三要灵应·动静之应〕躁人之辞多'),
('SAN_YAO_LING_YING', '诬善', '〔三要灵应·动静之应〕诬善之人，其辞游'),
('SAN_YAO_LING_YING', '失其守者', '〔三要灵应·动静之应〕失其守者，其辞屈');
INSERT INTO `domain_lore` (`collection`, `k`, `text`) VALUES
('MARRIAGE_APPEARANCE', '乾', '端正而长'),
('MARRIAGE_APPEARANCE', '坎', '邪淫、黑色、嫉妒、奢侈'),
('MARRIAGE_APPEARANCE', '艮', '色黄多巧'),
('MARRIAGE_APPEARANCE', '震', '美貌难犯'),
('MARRIAGE_APPEARANCE', '巽', '发少稀疏，丑陋心贪'),
('MARRIAGE_APPEARANCE', '离', '短赤色，性不常'),
('MARRIAGE_APPEARANCE', '坤', '貌丑，大腹而黄'),
('MARRIAGE_APPEARANCE', '兑', '高长，语话喜悦，白色'),
('SPIRIT_NOTE', '乾', '主有西北方之神，或兵刀之鬼，或天行时气，或称正之邪神'),
('SPIRIT_NOTE', '坤', '主西南之神，或旷野之鬼，或连亲之鬼，或水土里社之神，或犯方隅，或无主之祟'),
('SPIRIT_NOTE', '震', '主东方之神，或木下之神，或妖怪百端，或影响时见'),
('SPIRIT_NOTE', '巽', '主东南之鬼，或自缢戕生，或枷锁致命'),
('SPIRIT_NOTE', '坎', '主北方之鬼，或水旁之神，或没溺而亡，或血疾之鬼'),
('SPIRIT_NOTE', '离', '主南方之鬼，或猛勇之神，或犯灶司，或得愆于香火，或焚烧之鬼，或遇热病而亡'),
('SPIRIT_NOTE', '艮', '主东北之神，或山林之祟，或山魈木客，或土怪石精'),
('SPIRIT_NOTE', '兑', '主西方之神，或阵亡之鬼，或废疾之鬼，或刎颈戕生之鬼'),
('DIET_FOOD', '乾', '圆坚而味辛，为牲之首，为马为猪；有坎乃江湖海味，有水而蔬果珍羞；秋得之而食禄盛'),
('DIET_FOOD', '坤', '所用瓦器，米果之味；静则梨枣茄芋，动则鱼虾鲜羊；其色黑黄，其味甘甜'),
('DIET_FOOD', '震', '木属，大树之果、园林之蔬；色青而味酸；同离多主盐茶，见坎或为盐醋'),
('DIET_FOOD', '巽', '色白青、性曲直、味酸；桃李木瓜、斋辣素食，为鱼为鸡，其豆其面'),
('DIET_FOOD', '坎', '水族之味，味香有细鳞或四足，凡水簇必可饮食；色黑味咸；克出饮酒、生回食鱼'),
('DIET_FOOD', '离', '煎煿炙烧，或茶盐；为鸡为雉、为蟹为蛇，色赤味苦、性热气香；逢坎而酒请有争'),
('DIET_FOOD', '艮', '土物同烹；秋为蟹、春为马；内多肉、味辛；于菜为芹，于物带羽'),
('DIET_FOOD', '兑', '属白金，味辛色白；动物刀砧、辛辣、包里腌藏；盛而有腥臭、旺而有羊鹅'),
('LOST_ITEM_PLACE', '乾', '西北，或公廨楼阁之所，或金石之旁，或圆器之中，或高亢之地'),
('LOST_ITEM_PLACE', '坤', '西南，或田野之所，或仓廪之处，或稼穑之处，或土窖穴藏之所，或瓦器方器之中'),
('LOST_ITEM_PLACE', '震', '东方，或山林之所，或丛棘之内、钟鼓之旁，或闹市之间，或大途之所'),
('LOST_ITEM_PLACE', '巽', '东南，或山林之所，或寺观之地，或菜蔬之园，或舟车之间，或木器之内'),
('LOST_ITEM_PLACE', '坎', '北方，多藏于水边或溪井沟渠之处，或酒醋之边，或鱼盐之地'),
('LOST_ITEM_PLACE', '离', '南方，或庖厨之间，或炉冶之旁，或在明窗，或遗虚室，或在文书之侧，或在烟火之地'),
('LOST_ITEM_PLACE', '艮', '东北，或山林之内，或近路边，或岩石旁，或藏土穴'),
('LOST_ITEM_PLACE', '兑', '西方，或居泽畔，或败垣破壁之所、废井缺沼之中'),
('SHENG_BODY_NOTE', '乾', '主公门中有喜益，或功名上有喜，或因官有财，或问讼得理，或有金宝之利，或有老人尊长进财、官贵之喜'),
('SHENG_BODY_NOTE', '坤', '主有田土之喜，或于田土进财，或得乡人之财，或得阴人之利，或有果谷布帛之喜'),
('SHENG_BODY_NOTE', '震', '主山林之益，或因山林得财，或进东方之财，或因动中有喜，或有木货交易之利、草木姓氏人称心'),
('SHENG_BODY_NOTE', '巽', '亦主山林之益，或因山林得财，或于东南得财，或因草木人进利，或以茶果得利，或茶果菜蔬馈送之喜'),
('SHENG_BODY_NOTE', '坎', '有北方之喜，或受北方之财，或水边人进利，或因点水人称心，或因鱼盐酒货文书交易之利'),
('SHENG_BODY_NOTE', '离', '主有南方之财，或有文书之喜，或有炉冶场之利，或因火姓人而得财'),
('SHENG_BODY_NOTE', '艮', '有东北方之财，或山田之喜，或因山林田土获财，或宫音带土人之财；物当安稳，事有终始'),
('SHENG_BODY_NOTE', '兑', '有西方之财，或喜悦事，或有食物玉金货利之源，或商音之人、市口之人欣逢，或主宾之乐、朋友讲习之喜'),
('KE_BODY_NOTE', '乾', '主有公事之扰，或门户之扰，或有财宝之失，或于金谷有损，或有怒于尊长，或得罪于贵人'),
('KE_BODY_NOTE', '坤', '主有田土之扰，或于田土有损，或有小人之害，或有阴人之侵，或失布帛之财，或丧谷粟之利'),
('KE_BODY_NOTE', '震', '主有虚惊，常多恐惧，或身心不能安静，或家宅见妖灾，或草木姓氏之人相侵，或于山林有所失'),
('KE_BODY_NOTE', '巽', '亦有草木姓人相害，或于山林上生忧；谋事乃东南方之人，处家忌阴人小口之厄'),
('KE_BODY_NOTE', '坎', '主险陷之事，或寇盗之忧，或失意于水边人，或生灾于酒后，或点水人相害，或北方人见殃'),
('KE_BODY_NOTE', '离', '主文书之扰，或失火之惊，或有南方之忧，或火人相害'),
('KE_BODY_NOTE', '艮', '诸事多迍，百谋中阻；或有山林田土之失，或带土人相侵，防东北方之祸害，或忧坟墓不当安稳'),
('KE_BODY_NOTE', '兑', '不利西方，主口舌事之纷争；或带口人侵欺，或有毁折之患，或因饮食而生忧'),
('OBJECT_PLAY_NOTE', '乾', '金为圆白之物，其色白、其性刚，为宝货之物；有气为无价物'),
('OBJECT_PLAY_NOTE', '坎', '黑色、性柔，近水之物'),
('OBJECT_PLAY_NOTE', '艮', '土中之物，瓦石之类，有气为成器之物，其色黄；逢兑克、无气，折伤之物'),
('OBJECT_PLAY_NOTE', '巽', '竹木，有气为有用之物、为可食之物，无气为竹木之属；遇兑之属可食、当时之果物、色青；有气柔、无气刚'),
('OBJECT_PLAY_NOTE', '震', '竹木，有气为有用之物、为可食之物；遇坎为污湿物，无气为烂朽之木'),
('OBJECT_PLAY_NOTE', '离', '色赤、性柔，有水有木而火焚之，必炭之类；有气为价值可货之物'),
('OBJECT_PLAY_NOTE', '坤', '土中之物，色黄而性温'),
('OBJECT_PLAY_NOTE', '兑', '毁折之物，带口'),
('NEI_WAI_DONG_JING', '乾', '玄黄、大赤色、金玉、宝珠、镜、狮、圆物、木果、贵物、冠、象、马、天鹅、刚物'),
('NEI_WAI_DONG_JING', '坎', '水带子、带核之物、豕、鱼、弓轮、水具、水中之物、盐、黑色、酒'),
('NEI_WAI_DONG_JING', '艮', '土石、黄色、虎、狗、土中之物、瓜果、百禽、鼠、黔喙之物'),
('NEI_WAI_DONG_JING', '震', '竹木、青绿碧色、龙、蛇、萑苇、竹木乐器、草、蕃鲜之物'),
('NEI_WAI_DONG_JING', '巽', '木、蛇、长物、青碧绿、山木之禽鸟、香、鸡、直物、竹木之器、工巧之器'),
('NEI_WAI_DONG_JING', '离', '火、文书、干戈、雉、龟、蟹、槁木、甲胄、螺、蚌、鳖、物赤色'),
('NEI_WAI_DONG_JING', '坤', '土、万物、五谷、柔物、丝绵、百禽、牛、布帛、舆、釜、瓦器、黄色'),
('NEI_WAI_DONG_JING', '兑', '金刃、金器、乐器、泽中之物、白色、有口缺之物、羊');
INSERT INTO `domain_lore` (`collection`, `k`, `text`) VALUES
('OBJECT_MIAO_JUE', '乾', '刚而圆、贵而坚，为金为玉、为赤为圜、为大为首、为木之果；物见兑为毁折、逢坎而沉溺、见离为炼煅之金、震为有动之物、巽为木果为圆，坤艮土中之石得火而成器；兑为剑锋之锐，秋得而价高、夏得之而衰矣'),
('OBJECT_MIAO_JUE', '坤', '其形直而方，其色黑而黄；为文为布、为舆为金，其物象牛，其性恶动。得乾乃可圆可方、可贵可贱；震巽为长器，离为文章，兑为土中出之金，艮为带刚之土石也'),
('OBJECT_MIAO_JUE', '震', '其色玄黄而多青；为木为声、为竹为萑苇、为蕃鲜及生形。上柔下刚，是性震动而可惊；得乾乃为声价之物，得兑为无用之木，见艮山林间之石，见坎有气之类，巽为有枝叶，见离为带花'),
('OBJECT_MIAO_JUE', '巽', '其色白，其气香；为草木，为刚为柔。见离为文书，见兑乾为不用（乃遇金刀之物）；坤艮为草木之类，坎兑为可食之物。为长为直，并震而春生夏长，草木之果蔬'),
('OBJECT_MIAO_JUE', '坎', '其色黑，亦可圆可方物；为柔为腐，内则刚物。得之卑湿之所，多为水中之物。见乾亦圆，见兑亦毁（又乃污湿）；得震巽而可食，离水火既济、假水而出、假火而成，又为滞于物，兑为带口也，震巽为带枝叶、为带花也'),
('OBJECT_MIAO_JUE', '艮', '其色黄而青，体燥，其性则上刚下柔；为山石之物、土瓦之类、小石于大山，为门途之处。为物见乾而刚，兑而毁折，坤而土块，巽为草之物，而震为木物类也；坎并为河岸之物，离并为瓦器，震巽并见篱壁之物'),
('OBJECT_MIAO_JUE', '兑', '其色白，其性少柔而多刚；为毁折而下，全带口而圆。见乾先圆后缺，见艮则金石废器，见震为剥削之物，见坎为水之类。得乾而多刚，得坤而多柔；长于西泽之内、于水中之类，得柔而成器也');
INSERT INTO `domain_lore` (`collection`, `k`, `text`) VALUES
('CATEGORY_RULE_GOOD', '天时', '坎兑主雨、离主晴，卦宜生体比和则晴雨及时、天时顺遂'),
('CATEGORY_RULE_GOOD', '人事', '体克用诸事亨通，比和为妙，所谋顺遂'),
('CATEGORY_RULE_GOOD', '家宅', '体为主，旺相须知进田土，比和则家世安居'),
('CATEGORY_RULE_GOOD', '屋舍', '体旺相、生体比和，则屋宅稳固兴隆'),
('CATEGORY_RULE_GOOD', '婚姻', '体用比和、体克用则婚可成、家道吉'),
('CATEGORY_RULE_GOOD', '生产', '以体为母，体宜生旺不宜衰；生体比和则母子平安'),
('CATEGORY_RULE_GOOD', '饮食', '用生体必知肴馔丰厚，克用比和则和美；坎兑为酒、震为鱼'),
('CATEGORY_RULE_GOOD', '求谋', '比和则称意，体克用谋为可成（惟稍迟）'),
('CATEGORY_RULE_GOOD', '求名', '克用则名可求，生体比和俱可取'),
('CATEGORY_RULE_GOOD', '求财', '克用曰有财，生体比和俱称意，财可得'),
('CATEGORY_RULE_GOOD', '交易', '生体及比和，有利必成、交易顺遂'),
('CATEGORY_RULE_GOOD', '出行', '克用、用生体，所至其方多得意；坎则乘舟、离则旱途'),
('CATEGORY_RULE_GOOD', '行人', '生体比和则人即至；行人以生体之日为归期'),
('CATEGORY_RULE_GOOD', '谒见', '体克用、比和生体，则谒见遂意、得贵人助'),
('CATEGORY_RULE_GOOD', '失物', '生体比和则物可寻，以变卦方位定寻处：离冶炉南方、坤方器、兑残缺井畔'),
('CATEGORY_RULE_GOOD', '疾病', '最宜体旺相，克用则易安、药有效；比和凶则有救星'),
('CATEGORY_RULE_GOOD', '官讼', '用宜克、体卦旺相终得理；比和助解最为奇'),
('CATEGORY_RULE_GOOD', '坟墓', '比和生体宜葬，克用尤为大吉利；坤则平阳、巽林、乾高、艮山、离人烟'),
('CATEGORY_RULE_BAD', '天时', '克体则风雨失时、天时反常，宜顺天应候'),
('CATEGORY_RULE_BAD', '人事', '比和为妙克为凶，用克体则人事多有阻滞'),
('CATEGORY_RULE_BAD', '家宅', '生用则耗散财、克体为凶，家宅不宁'),
('CATEGORY_RULE_BAD', '屋舍', '克体则屋宅有损、居之不安'),
('CATEGORY_RULE_BAD', '婚姻', '生用必难成，用克体则婚姻不就或多阻'),
('CATEGORY_RULE_BAD', '生产', '体受克、体衰则产有险，宜谨护'),
('CATEGORY_RULE_BAD', '饮食', '生用克体则饮食难、席有缺'),
('CATEGORY_RULE_BAD', '求谋', '生用克体则谋事难成、费而无功'),
('CATEGORY_RULE_BAD', '求名', '用克体、生用则功名难就'),
('CATEGORY_RULE_BAD', '求财', '生用则破财、用克体则损财或无得'),
('CATEGORY_RULE_BAD', '交易', '克体生用则交易难成、防有亏损'),
('CATEGORY_RULE_BAD', '出行', '用克体则行有阻、途多险，宜缓行'),
('CATEGORY_RULE_BAD', '行人', '克用必来迟；咸远恒迟升不回，艮阻坎险'),
('CATEGORY_RULE_BAD', '谒见', '用克体则见而不得志、或为所拒'),
('CATEGORY_RULE_BAD', '失物', '克体则物难觅，随变卦方位远近推之'),
('CATEGORY_RULE_BAD', '疾病', '体卦受克为凶兆，宜谨药石；离宜服热、坎服冷、坤土温补'),
('CATEGORY_RULE_BAD', '官讼', '用克体、体衰则讼不利，宜和解息争'),
('CATEGORY_RULE_BAD', '坟墓', '克体则葬地不吉，宜另择');
INSERT INTO `domain_lore` (`collection`, `k`, `text`) VALUES
('QIAN_KUN_DISEASE_YAO', '1', '初爻动：变为震木，互见巽、艮，俱是生成之义，是谓不灾，逢生之日即愈'),
('QIAN_KUN_DISEASE_YAO', '2', '二爻动：变为坎水，乃泄体败金之义（金入水乡），互见巽、离（风火扇炉），俱为克体之义——即为焚尸之象，断之死无疑（更看占时外应、春夏秋冬四时推之）'),
('QIAN_KUN_DISEASE_YAO', '3', '三爻动：坤变艮土，俱在生体之义，不问互卦，亦断其吉无疑'),
('QIAN_KUN_DISEASE_YAO', '4', '四爻动：乾变巽木，金木俱有克体之义，互吉亦凶；木有扛尸之义、金为砖椁之推——是尸必定之理'),
('QIAN_KUN_DISEASE_YAO', '5', '五爻动：乾变离，反能生体，互、变俱生体，其吉无疑（更有吉兆则愈吉，凶则迟而忍死）'),
('QIAN_KUN_DISEASE_YAO', '6', '六爻动：乾变兑，则能泄体，互见巽、艮，一凶一吉，其病非死必危（宜看兆之吉凶：吉则言吉、凶则言凶）');
INSERT INTO `domain_lore` (`collection`, `k`, `text`) VALUES
('TU_XIANG_NAME', 'TX_ZHOUYI_GUASHU', '周易卦数（卷之一·象数易理；Image00003）'),
('TU_XIANG_NAME', 'TX_BAGUA_XIANGLI', '八卦象例（卷之一·象数易理；Image00004）'),
('TU_XIANG_NAME', 'TX_BAGUA_FANGWEI_1', '八卦方位图（卷之一·象数易理篇之二；Image00007）'),
('TU_XIANG_NAME', 'TX_BAGUA_FANGWEI_3', '八卦方位图（卷之三·断占总诀篇之一；Image00008）'),
('TU_XIANG_NAME', 'TX_BIAN_GUA_SHI', '变卦式八则·卦画（卷之三·断占总诀篇之一；Image00024–31）'),
('TU_XIANG_NAME', 'TX_QI_LIU_SHEN', '起六神卦诀·附例（卷之四·字画指迷；Image00076）'),
('TU_XIANG_NAME', 'TX_WU_XING_SI_SHI', '五行四时旺相休囚表（卷之五·拆字杂编；Image00108）'),
('TU_XIANG_NAME', 'TX_HUN_TIAN_JIA_ZI', '浑天甲子定局·纳甲（卷之五·拆字杂编；Image00109–110）'),
('TU_XIANG_NAME', 'TX_HOU_TIAN_SHI_FANG', '后天时方（卷之五·拆字杂编；Image00111–114）'),
('TU_XIANG_DESC', 'TX_ZHOUYI_GUASHU', '图象·先天八卦次序图'),
('TU_XIANG_DESC', 'TX_BAGUA_XIANGLI', '图象·八卦卦画之象'),
('TU_XIANG_DESC', 'TX_BAGUA_FANGWEI_1', '图象·后天八卦方位图'),
('TU_XIANG_DESC', 'TX_BAGUA_FANGWEI_3', '图象·八卦方位图'),
('TU_XIANG_DESC', 'TX_BIAN_GUA_SHI', '图象·八则各配本卦／互卦／变卦之卦画（六爻阴阳）'),
('TU_XIANG_DESC', 'TX_QI_LIU_SHEN', '图象·六神配六爻附例表'),
('TU_XIANG_DESC', 'TX_WU_XING_SI_SHI', '图象·五行四时旺相休囚例（金木水火土×春夏秋冬四季月）'),
('TU_XIANG_DESC', 'TX_HUN_TIAN_JIA_ZI', '图象·浑天甲子（纳甲）表'),
('TU_XIANG_DESC', 'TX_HOU_TIAN_SHI_FANG', '图象·六十甲子时方吉凶表（凡四页）'),
('TU_XIANG_TEXT', 'TX_ZHOUYI_GUASHU', '乾，一；兑，二；离，三；震，四；巽，五；坎，六；艮，七；坤，八。'),
('TU_XIANG_TEXT', 'TX_BAGUA_XIANGLI', '乾三连，坤六断，震仰盂，艮覆碗，离中虚，坎中满，兑上缺，巽下断。'),
('TU_XIANG_TEXT', 'TX_BAGUA_FANGWEI_1', '离南、坎北、震东、兑西、巽东南、坤西南、艮东北、乾西北，人则介乎其中。'),
('TU_XIANG_TEXT', 'TX_BAGUA_FANGWEI_3', '离南、坎北、震东、兑西、巽东南、坤西南、艮东北、乾西北，人则介乎其中。'),
('TU_XIANG_TEXT', 'TX_BIAN_GUA_SHI', '泽火革变泽山咸、地雷复变地泽临、天泽履变乾卦、泽火革变火雷噬嗑、雷泽归妹变火泽睽、泽天夬变兑卦、泽火革变艮卦、天水讼变兑卦。（断辞已见卷之三照录，此处补其卦画之目。）'),
('TU_XIANG_TEXT', 'TX_QI_LIU_SHEN', '附例（今以甲乙、丙丁日附载为式，余仿此）：六爻、五爻、四爻、三爻、二爻、初爻——甲乙日例：玄武、白虎、螣蛇、勾陈、朱雀、青龙；丙丁日例：青龙、玄武、白虎、螣蛇、勾陈、朱雀。'),
('TU_XIANG_TEXT', 'TX_WU_XING_SI_SHI', '春：金囚、木旺、水休、火相、土死；夏：金死、木休、水囚、火旺、土相；秋：金旺、木死、水相、火囚、土休；冬：金休、木相、水旺、火死、土囚；四季月：金相、木囚、水死、火休、土旺。（当令者旺，我生者相，生我者休，克我者囚，被我克者死。）'),
('TU_XIANG_TEXT', 'TX_HUN_TIAN_JIA_ZI', '乾：壬戌土、壬申金、壬午火（上卦），甲辰土、甲寅木、甲子水（下卦）；坎：戊子水、戊戌土、戊申金（上卦），戊午火、戊辰土、戊寅木（下卦）；艮：丙寅木、丙子水、丙戌土（上卦），丙申金、丙午火、丙辰土（下卦）；震：庚戌土、庚申金、庚午火（上卦），庚辰土、庚寅木、庚子水（下卦）。以上四宫属阳，皆从顺数。巽：辛卯木、辛巳火、辛未土（上卦），辛酉金、辛亥水、辛丑土（下卦）；离：己巳火、己未土、己酉金（上卦），己亥水、己丑土、己卯木（下卦）；坤：癸酉金、癸亥水、癸丑土（上卦），乙卯木、乙巳火、乙未土（下卦）；兑：丁未土、丁酉金、丁亥水（上卦），丁丑土、丁卯木、丁巳火（下卦）。以上四宫属阴，皆从逆数。'),
('TU_XIANG_TEXT', 'TX_HOU_TIAN_SHI_FANG', '子阳，辰丑阳，戊己下皆吉。子日子罡起，灭迹四位中。五败七破位，十祸日习同。（首行甲子：子罡、丑墓、寅吉、卯灭、辰败、巳吉、午破、未绝、申吉、酉祸、戌孤苦、亥空亡。全表六十甲子×十二支，异本互有出入，底本校勘记已注“败”一作“散”、“生”一作“位”；照实存目，详原图。）'),
('TU_XIANG_SRC', 'TX_ZHOUYI_GUASHU', '维基文库《梅花易數》卷一·象数易理篇之一'),
('TU_XIANG_SRC', 'TX_BAGUA_XIANGLI', '维基文库《梅花易數》卷一·象数易理篇之一'),
('TU_XIANG_SRC', 'TX_BAGUA_FANGWEI_1', '维基文库《梅花易數》卷一（图）、道教之音《梅花易数·八卦方位图》'),
('TU_XIANG_SRC', 'TX_BAGUA_FANGWEI_3', '维基文库《梅花易數》卷三；道教之音《梅花易数·八卦方位图》'),
('TU_XIANG_SRC', 'TX_BIAN_GUA_SHI', '维基文库《梅花易數》卷三·变卦式八则'),
('TU_XIANG_SRC', 'TX_QI_LIU_SHEN', '易学网《梅花易數》卷四·占字总诀一；汉同文《梅花观梅拆字数全集》卷之四'),
('TU_XIANG_SRC', 'TX_WU_XING_SI_SHI', '易学网《梅花易數》卷五·占字总诀二；《欽定古今圖書集成·藝術典》卷七四八'),
('TU_XIANG_SRC', 'TX_HUN_TIAN_JIA_ZI', '《欽定古今圖書集成·藝術典》卷七四八；易学网《梅花易數》卷五'),
('TU_XIANG_SRC', 'TX_HOU_TIAN_SHI_FANG', '《欽定古今圖書集成·藝術典》卷七四八；易学网《梅花易數》卷五');
