-- 4. 周易卦辞/爻辞「解释」（《周易》十翼经典原文，逐条对应上方文本，非编造）
--    卦辞解释 = 彖传 + 大象传；爻辞解释 = 小象传。
--    以 UPDATE 补入，保持上方原文不动。
-- ============================================================================
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：大哉乾元，万物资始，乃统天。云行雨施，品物流形。大明终始，六位时成，时乘六龙以御天。乾道变化，各正性命，保合大和，乃利贞。首出庶物，万国咸宁。 象曰：天行健，君子以自强不息。' WHERE name='Dictum_Hex_01';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：至哉坤元，万物资生，乃顺承天。坤厚载物，德合无疆。含弘光大，品物咸亨。牝马地类，行地无疆，柔顺利贞。君子攸行，先迷失道，后顺得常。西南得朋，乃与类行；东北丧朋，乃终有庆。安贞之吉，应地无疆。 象曰：地势坤，君子以厚德载物。' WHERE name='Dictum_Hex_02';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：屯，刚柔始交而难生，动乎险中，大亨贞。雷雨之动满盈，天造草昧，宜建侯而不宁。 象曰：云雷，屯；君子以经纶。' WHERE name='Dictum_Hex_03';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：蒙，山下有险，险而止，蒙。蒙亨，以亨行时中也。匪我求童蒙，童蒙求我，志应也。初筮告，以刚中也。再三渎，渎则不告，渎蒙也。蒙以养正，圣功也。 象曰：山下出泉，蒙；君子以果行育德。' WHERE name='Dictum_Hex_04';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：需，须也，险在前也。刚健而不陷，其义不困穷矣。需有孚，光亨贞吉，位乎天位，以正中也。利涉大川，往有功也。 象曰：云上于天，需；君子以饮食宴乐。' WHERE name='Dictum_Hex_05';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：讼，上刚下险，险而健，讼。讼有孚窒惕，中吉，刚来而得中也。终凶，讼不可成也。利见大人，尚中正也。不利涉大川，入于渊也。 象曰：天与水违行，讼；君子以作事谋始。' WHERE name='Dictum_Hex_06';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：师，众也，贞正也，能以众正，可以王矣。刚中而应，行险而顺，以此毒天下，而民从之，吉又何咎矣。 象曰：地中有水，师；君子以容民畜众。' WHERE name='Dictum_Hex_07';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：比，吉也；比，辅也，下顺从也。原筮元永贞无咎，以刚中也。不宁方来，上下应也。后夫凶，其道穷也。 象曰：地上有水，比；先王以建万国，亲诸侯。' WHERE name='Dictum_Hex_08';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：小畜，柔得位而上下应之，曰小畜。健而巽，刚中而志行，乃亨。密云不雨，尚往也；自我西郊，施未行也。 象曰：风行天上，小畜；君子以懿文德。' WHERE name='Dictum_Hex_09';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：履，柔履刚也。说而应乎乾，是以履虎尾，不咥人，亨。刚中正，履帝位而不疚，光明也。 象曰：上天下泽，履；君子以辨上下，定民志。' WHERE name='Dictum_Hex_10';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：泰，小往大来，吉亨。则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人，君子道长，小人道消也。 象曰：天地交，泰；后以财成天地之道，辅相天地之宜，以左右民。' WHERE name='Dictum_Hex_11';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：否之匪人，不利君子贞，大往小来。则是天地不交而万物不通也，上下不交而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子，小人道长，君子道消也。 象曰：天地不交，否；君子以俭德辟难，不可荣以禄。' WHERE name='Dictum_Hex_12';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：同人，柔得位得中而应乎乾，曰同人。同人曰：同人于野，亨，利涉大川，乾行也。文明以健，中正而应，君子正也。唯君子为能通天下之志。 象曰：天与火，同人；君子以类族辨物。' WHERE name='Dictum_Hex_13';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：大有，柔得尊位大中，而上下应之，曰大有。其德刚健而文明，应乎天而时行，是以元亨。 象曰：火在天上，大有；君子以遏恶扬善，顺天休命。' WHERE name='Dictum_Hex_14';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：谦，亨，天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾，君子之终也。 象曰：地中有山，谦；君子以裒多益寡，称物平施。' WHERE name='Dictum_Hex_15';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：豫，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况建侯行师乎？天地以顺动，故日月不过，而四时不忒；圣人以顺动，则刑罚清而民服。豫之时义大矣哉！ 象曰：雷出地奋，豫；先王以作乐崇德，殷荐之上帝，以配祖考。' WHERE name='Dictum_Hex_16';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：随，刚来而下柔，动而说，随。大亨贞无咎，而天下随时。随时之义大矣哉！ 象曰：泽中有雷，随；君子以向晦入宴息。' WHERE name='Dictum_Hex_17';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：蛊，刚上而柔下，巽而止，蛊。蛊元亨而天下治也。利涉大川，往有事也。先甲三日，后甲三日，终则有始，天行也。 象曰：山下有风，蛊；君子以振民育德。' WHERE name='Dictum_Hex_18';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：临，刚浸而长，说而顺，刚中而应。大亨以正，天之道也。至于八月有凶，消不久也。 象曰：泽上有地，临；君子以教思无穷，容保民无疆。' WHERE name='Dictum_Hex_19';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：大观在上，顺而巽，中正以观天下。观盥而不荐，有孚颙若，下观而化也。观天之神道，而四时不忒；圣人以神道设教，而天下服矣。 象曰：风行地上，观；先王以省方观民设教。' WHERE name='Dictum_Hex_20';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：颐中有物，曰噬嗑。噬嗑而亨，刚柔分，动而明，雷电合而章。柔得中而上行，虽不当位，利用狱也。 象曰：雷电，噬嗑；先王以明罚敕法。' WHERE name='Dictum_Hex_21';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：贲，亨，柔来而文刚，故亨；分刚上而文柔，故小利有攸往。天文也；文明以止，人文也。观乎天文，以察时变；观乎人文，以化成天下。 象曰：山下有火，贲；君子以明庶政，无敢折狱。' WHERE name='Dictum_Hex_22';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：剥，剥也，柔变刚也。不利有攸往，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也。 象曰：山附于地，剥；上以厚下安宅。' WHERE name='Dictum_Hex_23';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：复亨，刚反，动而以顺行，是以出入无疾，朋来无咎。反复其道，七日来复，天行也。利有攸往，刚长也。复其见天地之心乎？ 象曰：雷在地中，复；先王以至日闭关，商旅不行，后不省方。' WHERE name='Dictum_Hex_24';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：无妄，刚自外来而为主于内，动而健，刚中而应。大亨以正，天之命也。其匪正有眚，不利有攸往。无妄之往，何之矣？天命不佑，行矣哉？ 象曰：天下雷行，物与无妄；先王以茂对时育万物。' WHERE name='Dictum_Hex_25';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：大畜，刚健笃实辉光，日新其德，刚上而尚贤。能止健，大正也。不家食吉，养贤也。利涉大川，应乎天也。 象曰：天在山中，大畜；君子以多识前言往行，以畜其德。' WHERE name='Dictum_Hex_26';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：颐贞吉，养正则吉也。观颐，观其所养也；自求口实，观其自养也。天地养万物，圣人养贤以及万民。颐之时大矣哉！ 象曰：山下有雷，颐；君子以慎言语，节饮食。' WHERE name='Dictum_Hex_27';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：大过，大者过也。栋桡，本末弱也。刚过而中，巽而说行，利有攸往，乃亨。大过之时大矣哉！ 象曰：泽灭木，大过；君子以独立不惧，遁世无闷。' WHERE name='Dictum_Hex_28';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：习坎，重险也。水流而不盈，行险而不失其信。维心亨，乃以刚中也。行有尚，往有功也。天险不可升也，地险山川丘陵也，王公设险以守其国。险之时用大矣哉！ 象曰：水洊至，习坎；君子以常德行，习教事。' WHERE name='Dictum_Hex_29';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：离，丽也；日月丽乎天，百谷草木丽乎土，重明以丽乎正，乃化成天下。柔丽乎中正，故亨，是以畜牝牛吉也。 象曰：明两作，离；大人以继明照于四方。' WHERE name='Dictum_Hex_30';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：咸，感也。柔上而刚下，二气感应以相与，止而说，男下女，是以亨利贞，取女吉也。天地感而万物化生，圣人感人心而天下和平。观其所感，而天地万物之情可见矣。 象曰：山上有泽，咸；君子以虚受人。' WHERE name='Dictum_Hex_31';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：恒，久也。刚上而柔下，雷风相与，巽而动，刚柔皆应，恒。恒亨无咎利贞，久于其道也。天地之道，恒久而不已也。利有攸往，终则有始也。日月得天而能久照，四时变化而能久成，圣人久于其道而天下化成。观其所恒，而天地万物之情可见矣。 象曰：雷风，恒；君子以立不易方。' WHERE name='Dictum_Hex_32';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：遁亨，遁而亨也。刚当位而应，与时行也。小利贞，浸而长也。遁之时义大矣哉！ 象曰：天下有山，遁；君子以远小人，不恶而严。' WHERE name='Dictum_Hex_33';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：大壮，大者壮也。刚以动，故壮。大壮利贞，大者正也。正大而天地之情可见矣。 象曰：雷在天上，大壮；君子以非礼弗履。' WHERE name='Dictum_Hex_34';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：晋，进也。明出地上，顺而丽乎大明，柔进而上行，是以康侯用锡马蕃庶，昼日三接也。 象曰：明出地上，晋；君子以自昭明德。' WHERE name='Dictum_Hex_35';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：明入地中，明夷。内文明而外柔顺，以蒙大难，文王以之。利艰贞，晦其明也。内难而能正其志，箕子以之。 象曰：明入地中，明夷；君子以莅众，用晦而明。' WHERE name='Dictum_Hex_36';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：家人，女正位乎内，男正位乎外，男女正，天地之大义也。家人有严君焉，父母之谓也。父父，子子，兄兄，弟弟，夫夫，妇妇，而家道正；正家而天下定矣。 象曰：风自火出，家人；君子以言有物而行有恒。' WHERE name='Dictum_Hex_37';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：睽，火动而上，泽动而下，二女同居，其志不同行。说而丽乎明，柔进而上行，得中而应乎刚，是以小事吉。天地睽而其事同也，男女睽而其志通也，万物睽而其事类也。睽之时用大矣哉！ 象曰：上火下泽，睽；君子以同而异。' WHERE name='Dictum_Hex_38';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：蹇，难也，险在前也。见险而能止，知矣哉！蹇利西南，往得中也；不利东北，其道穷也。利见大人，往有功也。当位贞吉，以正邦也。蹇之时用大矣哉！ 象曰：山上有水，蹇；君子以反身修德。' WHERE name='Dictum_Hex_39';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：解，险以动，动而免乎险，解。解利西南，往得众也。其来复吉，乃得中也。有攸往夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之时大矣哉！ 象曰：雷雨作，解；君子以赦过宥罪。' WHERE name='Dictum_Hex_40';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：损，损下益上，其道上行。损而有孚，元吉，无咎，可贞，利有攸往。曷之用？二簋可用享。二簋应有时，损刚益柔有时。损益盈虚，与时偕行。 象曰：山下有泽，损；君子以惩忿窒欲。' WHERE name='Dictum_Hex_41';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：益，损上益下，民说无疆。自上下下，其道大光。利有攸往，中正有庆；利涉大川，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。 象曰：风雷，益；君子以见善则迁，有过则改。' WHERE name='Dictum_Hex_42';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：夬，决也，刚决柔也。健而说，决而和。扬于王庭，柔乘五刚也。孚号有厉，其危乃光也。告自邑，不利即戎，所尚乃穷也。利有攸往，刚长乃终也。 象曰：泽上于天，夬；君子以施禄及下，居德则忌。' WHERE name='Dictum_Hex_43';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：姤，遇也，柔遇刚也。勿用取女，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义大矣哉！ 象曰：天下有风，姤；后以施命诰四方。' WHERE name='Dictum_Hex_44';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：萃，聚也；顺以说，刚中而应，故聚也。王假有庙，致孝享也。利见大人亨，聚以正也。用大牲吉，利有攸往，顺天命也。观其所聚，而天地万物之情可见矣。 象曰：泽上于地，萃；君子以除戎器，戒不虞。' WHERE name='Dictum_Hex_45';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：柔以时升，巽而顺，刚中而应，是以大亨。用见大人，勿恤，有庆也。南征吉，志行也。 象曰：地中生木，升；君子以顺德，积小以高大。' WHERE name='Dictum_Hex_46';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：困，刚掩也。险以说，困而不失其所亨，其唯君子乎？贞大人吉，以刚中也。有言不信，尚口乃穷也。 象曰：泽无水，困；君子以致命遂志。' WHERE name='Dictum_Hex_47';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：巽乎水而上水，井；井养而不穷也。改邑不改井，乃以刚中也。汔至亦未繘井，未有功也。羸其瓶，是以凶也。 象曰：木上有水，井；君子以劳民劝相。' WHERE name='Dictum_Hex_48';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：革，水火相息，二女同居，其志不相得，曰革。己日乃孚，革而信之。文明以说，大亨以正，革而当，其悔乃亡。天地革而四时成，汤武革命，顺乎天而应乎人。革之时大矣哉！ 象曰：泽中有火，革；君子以治历明时。' WHERE name='Dictum_Hex_49';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：鼎，象也。以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤。巽而耳目聪明，柔进而上行，得中而应乎刚，是以元亨。 象曰：木上有火，鼎；君子以正位凝命。' WHERE name='Dictum_Hex_50';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：震，亨。震来虩虩，恐致福也。笑言哑哑，后有则也。震惊百里，惊远而惧迩也。出可以守宗庙社稷，以为祭主也。 象曰：洊雷，震；君子以恐惧修省。' WHERE name='Dictum_Hex_51';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：艮，止也。时止则止，时行则行，动静不失其时，其道光明。艮其止，止其所也。上下敌应，不相与也。是以不获其身，行其庭不见其人，无咎也。 象曰：兼山，艮；君子以思不出其位。' WHERE name='Dictum_Hex_52';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：渐之进也，女归吉也。进得位，往有功也。进以正，可以正邦也。其位，刚得中也。止而巽，动不穷也。 象曰：山上有木，渐；君子以居贤德善俗。' WHERE name='Dictum_Hex_53';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：归妹，天地之大义也。天地不交，而万物不兴。归妹，人之终始也。说以动，所归妹也。征凶，位不当也。无攸利，柔乘刚也。 象曰：泽上有雷，归妹；君子以永终知敝。' WHERE name='Dictum_Hex_54';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：丰，大也。明以动，故丰。王假之，尚大也。勿忧宜日中，宜照天下也。日中则昃，月盈则食，天地盈虚，与时消息，而况于人乎？况于鬼神乎？ 象曰：雷电皆至，丰；君子以折狱致刑。' WHERE name='Dictum_Hex_55';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：旅，小亨，柔得中乎外而顺乎刚，止而丽乎明，是以小亨旅贞吉也。旅之时义大矣哉！ 象曰：山上有火，旅；君子以明慎用刑而不留狱。' WHERE name='Dictum_Hex_56';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：重巽以申命。刚巽乎中正而志行，柔皆顺乎刚，是以小亨，利有攸往，利见大人。 象曰：随风，巽；君子以申命行事。' WHERE name='Dictum_Hex_57';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：兑，说也。刚中而柔外，说以利贞，是以顺乎天而应乎人。说以先民，民忘其劳；说以犯难，民忘其死。说之大，民劝矣哉！ 象曰：丽泽，兑；君子以朋友讲习。' WHERE name='Dictum_Hex_58';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：涣，亨。刚来而不穷，柔得位乎外而上同。王假有庙，王乃在中也。利涉大川，乘木有功也。 象曰：风行水上，涣；先王以享于帝立庙。' WHERE name='Dictum_Hex_59';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：节，亨，刚柔分而刚得中。苦节不可贞，其道穷也。说以行险，当位以节，中正以通。天地节而四时成。节以制度，不伤财，不害民。 象曰：泽上有水，节；君子以制数度，议德行。' WHERE name='Dictum_Hex_60';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：中孚，柔在内而刚得中，说而巽，孚乃化邦也。豚鱼吉，信及豚鱼也。利涉大川，乘木舟虚也。中孚以利贞，乃应乎天也。 象曰：泽上有风，中孚；君子以议狱缓死。' WHERE name='Dictum_Hex_61';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：小过，小者过而亨也。过以利贞，与时行也。柔得中，是以小事吉也。刚失位而不中，是以不可大事也。有飞鸟之象焉，飞鸟遗之音，不宜上宜下，大吉，上逆而下顺也。 象曰：山上有雷，小过；君子以行过乎恭，丧过乎哀，用过乎俭。' WHERE name='Dictum_Hex_62';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：既济亨，小者亨也。利贞，刚柔正而位当也。初吉，柔得中也。终止则乱，其道穷也。 象曰：水在火上，既济；君子以思患而豫防之。' WHERE name='Dictum_Hex_63';
UPDATE yijing_hexagram_dictum SET interpretation='彖曰：未济亨，柔得中也。小狐汔济，未出中也。濡其尾，无攸利，不续终也。虽不当位，刚柔应也。 象曰：火在水上，未济；君子以慎辨物居方。' WHERE name='Dictum_Hex_64';

-- 爻辞解释（小象传，逐爻；NN=1..22）
UPDATE yijing_line_dictum SET interpretation='潜龙勿用，阳在下也。' WHERE name='LineDictum_01_1';
UPDATE yijing_line_dictum SET interpretation='见龙在田，德施普也。' WHERE name='LineDictum_01_2';
UPDATE yijing_line_dictum SET interpretation='终日乾乾，反复道也。' WHERE name='LineDictum_01_3';
UPDATE yijing_line_dictum SET interpretation='或跃在渊，进无咎也。' WHERE name='LineDictum_01_4';
UPDATE yijing_line_dictum SET interpretation='飞龙在天，大人造也。' WHERE name='LineDictum_01_5';
UPDATE yijing_line_dictum SET interpretation='亢龙有悔，盈不可久也。' WHERE name='LineDictum_01_6';
UPDATE yijing_line_dictum SET interpretation='履霜坚冰，阴始凝也。驯致其道，至坚冰也。' WHERE name='LineDictum_02_1';
UPDATE yijing_line_dictum SET interpretation='六二之动，直以方也。不习无不利，地道光也。' WHERE name='LineDictum_02_2';
UPDATE yijing_line_dictum SET interpretation='含章可贞，以时发也。或从王事，知光大也。' WHERE name='LineDictum_02_3';
UPDATE yijing_line_dictum SET interpretation='括囊无咎，慎不害也。' WHERE name='LineDictum_02_4';
UPDATE yijing_line_dictum SET interpretation='黄裳元吉，文在中也。' WHERE name='LineDictum_02_5';
UPDATE yijing_line_dictum SET interpretation='龙战于野，其道穷也。' WHERE name='LineDictum_02_6';
UPDATE yijing_line_dictum SET interpretation='虽磐桓，志行正也。以贵下贱，大得民也。' WHERE name='LineDictum_03_1';
UPDATE yijing_line_dictum SET interpretation='六二之难，乘刚也。十年乃字，反常也。' WHERE name='LineDictum_03_2';
UPDATE yijing_line_dictum SET interpretation='即鹿无虞，以从禽也。君子舍之，往吝穷也。' WHERE name='LineDictum_03_3';
UPDATE yijing_line_dictum SET interpretation='求而往，明也。' WHERE name='LineDictum_03_4';
UPDATE yijing_line_dictum SET interpretation='屯其膏，施未光也。' WHERE name='LineDictum_03_5';
UPDATE yijing_line_dictum SET interpretation='泣血涟如，何可长也。' WHERE name='LineDictum_03_6';
UPDATE yijing_line_dictum SET interpretation='利用刑人，以正法也。' WHERE name='LineDictum_04_1';
UPDATE yijing_line_dictum SET interpretation='子克家，刚柔接也。' WHERE name='LineDictum_04_2';
UPDATE yijing_line_dictum SET interpretation='勿用取女，行不顺也。' WHERE name='LineDictum_04_3';
UPDATE yijing_line_dictum SET interpretation='困蒙之吝，独远实也。' WHERE name='LineDictum_04_4';
UPDATE yijing_line_dictum SET interpretation='童蒙之吉，顺以巽也。' WHERE name='LineDictum_04_5';
UPDATE yijing_line_dictum SET interpretation='利用御寇，上下顺也。' WHERE name='LineDictum_04_6';
UPDATE yijing_line_dictum SET interpretation='需于郊，不犯难行也。利用恒无咎，未失常也。' WHERE name='LineDictum_05_1';
UPDATE yijing_line_dictum SET interpretation='需于沙，衍在中也。虽小有言，以吉终也。' WHERE name='LineDictum_05_2';
UPDATE yijing_line_dictum SET interpretation='需于泥，灾在外也。自我致寇，敬慎不败也。' WHERE name='LineDictum_05_3';
UPDATE yijing_line_dictum SET interpretation='需于血，顺以听也。' WHERE name='LineDictum_05_4';
UPDATE yijing_line_dictum SET interpretation='酒食贞吉，以中正也。' WHERE name='LineDictum_05_5';
UPDATE yijing_line_dictum SET interpretation='不速之客来，敬之终吉。虽不当位，未大失也。' WHERE name='LineDictum_05_6';
UPDATE yijing_line_dictum SET interpretation='不永所事，讼不可长也。虽小有言，其辩明也。' WHERE name='LineDictum_06_1';
UPDATE yijing_line_dictum SET interpretation='不克讼，归逋窜也。自下讼上，患至掇也。' WHERE name='LineDictum_06_2';
UPDATE yijing_line_dictum SET interpretation='食旧德，从上吉也。' WHERE name='LineDictum_06_3';
UPDATE yijing_line_dictum SET interpretation='复即命渝，安贞不失也。' WHERE name='LineDictum_06_4';
UPDATE yijing_line_dictum SET interpretation='讼元吉，以中正也。' WHERE name='LineDictum_06_5';
UPDATE yijing_line_dictum SET interpretation='以讼受服，亦不足敬也。' WHERE name='LineDictum_06_6';
UPDATE yijing_line_dictum SET interpretation='师出以律，失律凶也。' WHERE name='LineDictum_07_1';
UPDATE yijing_line_dictum SET interpretation='在师中吉，承天宠也。王三锡命，怀万邦也。' WHERE name='LineDictum_07_2';
UPDATE yijing_line_dictum SET interpretation='师或舆尸，大无功也。' WHERE name='LineDictum_07_3';
UPDATE yijing_line_dictum SET interpretation='左次无咎，未失常也。' WHERE name='LineDictum_07_4';
UPDATE yijing_line_dictum SET interpretation='长子帅师，以中行也。弟子舆尸，使不当也。' WHERE name='LineDictum_07_5';
UPDATE yijing_line_dictum SET interpretation='大君有命，以正功也。小人勿用，必乱邦也。' WHERE name='LineDictum_07_6';
UPDATE yijing_line_dictum SET interpretation='比之初六，有它吉也。' WHERE name='LineDictum_08_1';
UPDATE yijing_line_dictum SET interpretation='比之自内，不自失也。' WHERE name='LineDictum_08_2';
UPDATE yijing_line_dictum SET interpretation='比之匪人，不亦伤乎？' WHERE name='LineDictum_08_3';
UPDATE yijing_line_dictum SET interpretation='外比于贤，以从上也。' WHERE name='LineDictum_08_4';
UPDATE yijing_line_dictum SET interpretation='显比之吉，位正中也。舍逆取顺，失前禽也。邑人不诫，上使中也。' WHERE name='LineDictum_08_5';
UPDATE yijing_line_dictum SET interpretation='比之无首，无所终也。' WHERE name='LineDictum_08_6';
UPDATE yijing_line_dictum SET interpretation='复自道，其义吉也。' WHERE name='LineDictum_09_1';
UPDATE yijing_line_dictum SET interpretation='牵复在中，亦不自失也。' WHERE name='LineDictum_09_2';
UPDATE yijing_line_dictum SET interpretation='夫妻反目，不能正室也。' WHERE name='LineDictum_09_3';
UPDATE yijing_line_dictum SET interpretation='有孚惕出，上合志也。' WHERE name='LineDictum_09_4';
UPDATE yijing_line_dictum SET interpretation='有孚挛如，不独富也。' WHERE name='LineDictum_09_5';
UPDATE yijing_line_dictum SET interpretation='既雨既处，德积载也。君子征凶，有所疑也。' WHERE name='LineDictum_09_6';
UPDATE yijing_line_dictum SET interpretation='素履之往，独行愿也。' WHERE name='LineDictum_10_1';
UPDATE yijing_line_dictum SET interpretation='幽人贞吉，中不自乱也。' WHERE name='LineDictum_10_2';
UPDATE yijing_line_dictum SET interpretation='眇能视，不足以有明也。跛能履，不足以与行也。咥人之凶，位不当也。武人为于大君，志刚也。' WHERE name='LineDictum_10_3';
UPDATE yijing_line_dictum SET interpretation='愬愬终吉，志行也。' WHERE name='LineDictum_10_4';
UPDATE yijing_line_dictum SET interpretation='夬履贞厉，位正当也。' WHERE name='LineDictum_10_5';
UPDATE yijing_line_dictum SET interpretation='元吉在上，大有庆也。' WHERE name='LineDictum_10_6';
UPDATE yijing_line_dictum SET interpretation='拔茅征吉，志在外也。' WHERE name='LineDictum_11_1';
UPDATE yijing_line_dictum SET interpretation='包荒得尚于中行，以光大也。' WHERE name='LineDictum_11_2';
UPDATE yijing_line_dictum SET interpretation='无往不复，天地际也。' WHERE name='LineDictum_11_3';
UPDATE yijing_line_dictum SET interpretation='翩翩不富，皆失实也。不戒以孚，中心愿也。' WHERE name='LineDictum_11_4';
UPDATE yijing_line_dictum SET interpretation='以祉元吉，中以行愿也。' WHERE name='LineDictum_11_5';
UPDATE yijing_line_dictum SET interpretation='城复于隍，其命乱也。' WHERE name='LineDictum_11_6';
UPDATE yijing_line_dictum SET interpretation='拔茅贞吉，志在君也。' WHERE name='LineDictum_12_1';
UPDATE yijing_line_dictum SET interpretation='大人否亨，不乱群也。' WHERE name='LineDictum_12_2';
UPDATE yijing_line_dictum SET interpretation='包羞，位不当也。' WHERE name='LineDictum_12_3';
UPDATE yijing_line_dictum SET interpretation='有命无咎，志行也。' WHERE name='LineDictum_12_4';
UPDATE yijing_line_dictum SET interpretation='大人之吉，位正当也。' WHERE name='LineDictum_12_5';
UPDATE yijing_line_dictum SET interpretation='否终则倾，何可长也。' WHERE name='LineDictum_12_6';
UPDATE yijing_line_dictum SET interpretation='出门同人，又谁咎也。' WHERE name='LineDictum_13_1';
UPDATE yijing_line_dictum SET interpretation='同人于宗，吝道也。' WHERE name='LineDictum_13_2';
UPDATE yijing_line_dictum SET interpretation='伏戎于莽，敌刚也。三岁不兴，安行也。' WHERE name='LineDictum_13_3';
UPDATE yijing_line_dictum SET interpretation='乘其墉，义弗克也。其吉，则困而反则也。' WHERE name='LineDictum_13_4';
UPDATE yijing_line_dictum SET interpretation='同人之先，以中直也。大师相遇，言相克也。' WHERE name='LineDictum_13_5';
UPDATE yijing_line_dictum SET interpretation='同人于郊，志未得也。' WHERE name='LineDictum_13_6';
UPDATE yijing_line_dictum SET interpretation='大有初九，无交害也。' WHERE name='LineDictum_14_1';
UPDATE yijing_line_dictum SET interpretation='大车以载，积中不败也。' WHERE name='LineDictum_14_2';
UPDATE yijing_line_dictum SET interpretation='公用亨于天子，小人害也。' WHERE name='LineDictum_14_3';
UPDATE yijing_line_dictum SET interpretation='匪其彭无咎，明辨晳也。' WHERE name='LineDictum_14_4';
UPDATE yijing_line_dictum SET interpretation='厥孚交如，信以发志也。威如之吉，易而无备也。' WHERE name='LineDictum_14_5';
UPDATE yijing_line_dictum SET interpretation='大有上吉，自天祐也。' WHERE name='LineDictum_14_6';
UPDATE yijing_line_dictum SET interpretation='谦谦君子，卑以自牧也。' WHERE name='LineDictum_15_1';
UPDATE yijing_line_dictum SET interpretation='鸣谦贞吉，中心得也。' WHERE name='LineDictum_15_2';
UPDATE yijing_line_dictum SET interpretation='劳谦君子，万民服也。' WHERE name='LineDictum_15_3';
UPDATE yijing_line_dictum SET interpretation='无不利撝谦，不违则也。' WHERE name='LineDictum_15_4';
UPDATE yijing_line_dictum SET interpretation='利用侵伐，征不服也。' WHERE name='LineDictum_15_5';
UPDATE yijing_line_dictum SET interpretation='鸣谦，志未得也。可用行师，征邑国也。' WHERE name='LineDictum_15_6';
UPDATE yijing_line_dictum SET interpretation='初六鸣豫，志穷凶也。' WHERE name='LineDictum_16_1';
UPDATE yijing_line_dictum SET interpretation='不终日贞吉，以中正也。' WHERE name='LineDictum_16_2';
UPDATE yijing_line_dictum SET interpretation='盱豫有悔，位不当也。' WHERE name='LineDictum_16_3';
UPDATE yijing_line_dictum SET interpretation='由豫大有得，志大行也。' WHERE name='LineDictum_16_4';
UPDATE yijing_line_dictum SET interpretation='六五贞疾，乘刚也。恒不死，中未亡也。' WHERE name='LineDictum_16_5';
UPDATE yijing_line_dictum SET interpretation='冥豫在上，何可长也。' WHERE name='LineDictum_16_6';
UPDATE yijing_line_dictum SET interpretation='官有渝，从正吉也。出门交有功，不失也。' WHERE name='LineDictum_17_1';
UPDATE yijing_line_dictum SET interpretation='系小子，弗兼与也。' WHERE name='LineDictum_17_2';
UPDATE yijing_line_dictum SET interpretation='系丈夫，志舍下也。' WHERE name='LineDictum_17_3';
UPDATE yijing_line_dictum SET interpretation='随有获，其义凶也。有孚在道，明功也。' WHERE name='LineDictum_17_4';
UPDATE yijing_line_dictum SET interpretation='孚于嘉吉，位正中也。' WHERE name='LineDictum_17_5';
UPDATE yijing_line_dictum SET interpretation='拘系之，上穷也。' WHERE name='LineDictum_17_6';
UPDATE yijing_line_dictum SET interpretation='干父之蛊，意承考也。' WHERE name='LineDictum_18_1';
UPDATE yijing_line_dictum SET interpretation='干母之蛊，得中道也。' WHERE name='LineDictum_18_2';
UPDATE yijing_line_dictum SET interpretation='干父之蛊，终无咎也。' WHERE name='LineDictum_18_3';
UPDATE yijing_line_dictum SET interpretation='裕父之蛊，往未得也。' WHERE name='LineDictum_18_4';
UPDATE yijing_line_dictum SET interpretation='干父用誉，承以德也。' WHERE name='LineDictum_18_5';
UPDATE yijing_line_dictum SET interpretation='不事王侯，志可则也。' WHERE name='LineDictum_18_6';
UPDATE yijing_line_dictum SET interpretation='咸临贞吉，志行正也。' WHERE name='LineDictum_19_1';
UPDATE yijing_line_dictum SET interpretation='咸临吉无不利，未顺命也。' WHERE name='LineDictum_19_2';
UPDATE yijing_line_dictum SET interpretation='甘临，位不当也。既忧之，咎不长也。' WHERE name='LineDictum_19_3';
UPDATE yijing_line_dictum SET interpretation='至临无咎，位当也。' WHERE name='LineDictum_19_4';
UPDATE yijing_line_dictum SET interpretation='大君之宜，行中之谓也。' WHERE name='LineDictum_19_5';
UPDATE yijing_line_dictum SET interpretation='敦临之吉，志在内也。' WHERE name='LineDictum_19_6';
UPDATE yijing_line_dictum SET interpretation='初六童观，小人道也。' WHERE name='LineDictum_20_1';
UPDATE yijing_line_dictum SET interpretation='窥观女贞，亦可丑也。' WHERE name='LineDictum_20_2';
UPDATE yijing_line_dictum SET interpretation='观我生进退，未失道也。' WHERE name='LineDictum_20_3';
UPDATE yijing_line_dictum SET interpretation='观国之光，尚宾也。' WHERE name='LineDictum_20_4';
UPDATE yijing_line_dictum SET interpretation='观我生，观民也。' WHERE name='LineDictum_20_5';
UPDATE yijing_line_dictum SET interpretation='观其生，志未平也。' WHERE name='LineDictum_20_6';
UPDATE yijing_line_dictum SET interpretation='屦校灭趾，不行也。' WHERE name='LineDictum_21_1';
UPDATE yijing_line_dictum SET interpretation='噬肤灭鼻，乘刚也。' WHERE name='LineDictum_21_2';
UPDATE yijing_line_dictum SET interpretation='遇毒，位不当也。' WHERE name='LineDictum_21_3';
UPDATE yijing_line_dictum SET interpretation='利艰贞吉，未光也。' WHERE name='LineDictum_21_4';
UPDATE yijing_line_dictum SET interpretation='贞厉无咎，得当也。' WHERE name='LineDictum_21_5';
UPDATE yijing_line_dictum SET interpretation='何校灭耳，聪不明也。' WHERE name='LineDictum_21_6';
UPDATE yijing_line_dictum SET interpretation='舍车而徒，义弗乘也。' WHERE name='LineDictum_22_1';
UPDATE yijing_line_dictum SET interpretation='贲其须，与上兴也。' WHERE name='LineDictum_22_2';
UPDATE yijing_line_dictum SET interpretation='永贞之吉，终莫之陵也。' WHERE name='LineDictum_22_3';
UPDATE yijing_line_dictum SET interpretation='六四当位，疑也。匪寇婚媾，终无尤也。' WHERE name='LineDictum_22_4';
UPDATE yijing_line_dictum SET interpretation='六五之吉，有喜也。' WHERE name='LineDictum_22_5';
UPDATE yijing_line_dictum SET interpretation='白贲无咎，上得志也。' WHERE name='LineDictum_22_6';
UPDATE yijing_line_dictum SET interpretation='剥床以足，以灭下也。' WHERE name='LineDictum_23_1';
UPDATE yijing_line_dictum SET interpretation='剥床以辨，未有与也。' WHERE name='LineDictum_23_2';
UPDATE yijing_line_dictum SET interpretation='剥之无咎，失上下也。' WHERE name='LineDictum_23_3';
UPDATE yijing_line_dictum SET interpretation='剥床以肤，切近灾也。' WHERE name='LineDictum_23_4';
UPDATE yijing_line_dictum SET interpretation='以宫人宠，终无尤也。' WHERE name='LineDictum_23_5';
UPDATE yijing_line_dictum SET interpretation='君子得舆，民所载也。小人剥庐，终不可用也。' WHERE name='LineDictum_23_6';
UPDATE yijing_line_dictum SET interpretation='不远之复，以修身也。' WHERE name='LineDictum_24_1';
UPDATE yijing_line_dictum SET interpretation='休复之吉，以下仁也。' WHERE name='LineDictum_24_2';
UPDATE yijing_line_dictum SET interpretation='频复之厉，义无咎也。' WHERE name='LineDictum_24_3';
UPDATE yijing_line_dictum SET interpretation='中行独复，以从道也。' WHERE name='LineDictum_24_4';
UPDATE yijing_line_dictum SET interpretation='敦复无悔，中以自考也。' WHERE name='LineDictum_24_5';
UPDATE yijing_line_dictum SET interpretation='迷复之凶，反君道也。' WHERE name='LineDictum_24_6';
UPDATE yijing_line_dictum SET interpretation='无妄之往，得志也。' WHERE name='LineDictum_25_1';
UPDATE yijing_line_dictum SET interpretation='不耕获，未富也。' WHERE name='LineDictum_25_2';
UPDATE yijing_line_dictum SET interpretation='行人得牛，邑人灾也。' WHERE name='LineDictum_25_3';
UPDATE yijing_line_dictum SET interpretation='可贞无咎，固有之也。' WHERE name='LineDictum_25_4';
UPDATE yijing_line_dictum SET interpretation='无妄之药，不可试也。' WHERE name='LineDictum_25_5';
UPDATE yijing_line_dictum SET interpretation='无妄之行，穷之灾也。' WHERE name='LineDictum_25_6';
UPDATE yijing_line_dictum SET interpretation='有厉利已，不犯灾也。' WHERE name='LineDictum_26_1';
UPDATE yijing_line_dictum SET interpretation='舆说輹，中无尤也。' WHERE name='LineDictum_26_2';
UPDATE yijing_line_dictum SET interpretation='利有攸往，上合志也。' WHERE name='LineDictum_26_3';
UPDATE yijing_line_dictum SET interpretation='童牛之牿，元吉，有喜也。' WHERE name='LineDictum_26_4';
UPDATE yijing_line_dictum SET interpretation='六五之吉，有庆也。' WHERE name='LineDictum_26_5';
UPDATE yijing_line_dictum SET interpretation='何天之衢，道大行也。' WHERE name='LineDictum_26_6';
UPDATE yijing_line_dictum SET interpretation='观我朵颐，亦不足贵也。' WHERE name='LineDictum_27_1';
UPDATE yijing_line_dictum SET interpretation='六二征凶，行失类也。' WHERE name='LineDictum_27_2';
UPDATE yijing_line_dictum SET interpretation='十年勿用，道大悖也。' WHERE name='LineDictum_27_3';
UPDATE yijing_line_dictum SET interpretation='颠颐之吉，上施光也。' WHERE name='LineDictum_27_4';
UPDATE yijing_line_dictum SET interpretation='居贞之吉，顺以从上也。' WHERE name='LineDictum_27_5';
UPDATE yijing_line_dictum SET interpretation='由颐厉吉，大有庆也。' WHERE name='LineDictum_27_6';
UPDATE yijing_line_dictum SET interpretation='藉用白茅，柔在下也。' WHERE name='LineDictum_28_1';
UPDATE yijing_line_dictum SET interpretation='老夫女妻，过以相与也。' WHERE name='LineDictum_28_2';
UPDATE yijing_line_dictum SET interpretation='栋桡之凶，不可以有辅也。' WHERE name='LineDictum_28_3';
UPDATE yijing_line_dictum SET interpretation='栋隆之吉，不桡乎下也。' WHERE name='LineDictum_28_4';
UPDATE yijing_line_dictum SET interpretation='枯杨生华，何可久也。老妇士夫，亦可丑也。' WHERE name='LineDictum_28_5';
UPDATE yijing_line_dictum SET interpretation='过涉之凶，不可咎也。' WHERE name='LineDictum_28_6';
UPDATE yijing_line_dictum SET interpretation='习坎入坎，失道凶也。' WHERE name='LineDictum_29_1';
UPDATE yijing_line_dictum SET interpretation='求小得，未出中也。' WHERE name='LineDictum_29_2';
UPDATE yijing_line_dictum SET interpretation='来之坎坎，终无功也。' WHERE name='LineDictum_29_3';
UPDATE yijing_line_dictum SET interpretation='樽酒簋贰，刚柔际也。' WHERE name='LineDictum_29_4';
UPDATE yijing_line_dictum SET interpretation='坎不盈，中未大也。' WHERE name='LineDictum_29_5';
UPDATE yijing_line_dictum SET interpretation='上六失道，凶三岁也。' WHERE name='LineDictum_29_6';
UPDATE yijing_line_dictum SET interpretation='履错之敬，以辟咎也。' WHERE name='LineDictum_30_1';
UPDATE yijing_line_dictum SET interpretation='黄离元吉，得中道也。' WHERE name='LineDictum_30_2';
UPDATE yijing_line_dictum SET interpretation='日昃之离，何可久也。' WHERE name='LineDictum_30_3';
UPDATE yijing_line_dictum SET interpretation='突如其来如，无所容也。' WHERE name='LineDictum_30_4';
UPDATE yijing_line_dictum SET interpretation='六五之吉，离王公也。' WHERE name='LineDictum_30_5';
UPDATE yijing_line_dictum SET interpretation='王用出征，以正邦也。' WHERE name='LineDictum_30_6';
UPDATE yijing_line_dictum SET interpretation='咸其拇，志在外也。' WHERE name='LineDictum_31_1';
UPDATE yijing_line_dictum SET interpretation='虽凶居吉，顺不害也。' WHERE name='LineDictum_31_2';
UPDATE yijing_line_dictum SET interpretation='咸其股，亦不处也。志在随人，所执下也。' WHERE name='LineDictum_31_3';
UPDATE yijing_line_dictum SET interpretation='贞吉悔亡，未感害也。憧憧往来，未光大也。' WHERE name='LineDictum_31_4';
UPDATE yijing_line_dictum SET interpretation='咸其脢，志末也。' WHERE name='LineDictum_31_5';
UPDATE yijing_line_dictum SET interpretation='咸其辅颊舌，滕口说也。' WHERE name='LineDictum_31_6';
UPDATE yijing_line_dictum SET interpretation='浚恒之凶，始求深也。' WHERE name='LineDictum_32_1';
UPDATE yijing_line_dictum SET interpretation='九二悔亡，能久中也。' WHERE name='LineDictum_32_2';
UPDATE yijing_line_dictum SET interpretation='不恒其德，无所容也。' WHERE name='LineDictum_32_3';
UPDATE yijing_line_dictum SET interpretation='久非其位，安得禽也。' WHERE name='LineDictum_32_4';
UPDATE yijing_line_dictum SET interpretation='妇人贞吉，从一而终也。夫子制义，从妇凶也。' WHERE name='LineDictum_32_5';
UPDATE yijing_line_dictum SET interpretation='振恒在上，大无功也。' WHERE name='LineDictum_32_6';
UPDATE yijing_line_dictum SET interpretation='遁尾之厉，不往何灾也。' WHERE name='LineDictum_33_1';
UPDATE yijing_line_dictum SET interpretation='执用黄牛，固志也。' WHERE name='LineDictum_33_2';
UPDATE yijing_line_dictum SET interpretation='系遁之厉，有疾惫也。畜臣妾吉，不可大事也。' WHERE name='LineDictum_33_3';
UPDATE yijing_line_dictum SET interpretation='君子好遁，小人否也。' WHERE name='LineDictum_33_4';
UPDATE yijing_line_dictum SET interpretation='嘉遁贞吉，以正志也。' WHERE name='LineDictum_33_5';
UPDATE yijing_line_dictum SET interpretation='肥遁无不利，无所疑也。' WHERE name='LineDictum_33_6';
UPDATE yijing_line_dictum SET interpretation='壮于趾，其孚穷也。' WHERE name='LineDictum_34_1';
UPDATE yijing_line_dictum SET interpretation='九二贞吉，以中也。' WHERE name='LineDictum_34_2';
UPDATE yijing_line_dictum SET interpretation='小人用壮，君子罔也。' WHERE name='LineDictum_34_3';
UPDATE yijing_line_dictum SET interpretation='藩决不赢，尚往也。' WHERE name='LineDictum_34_4';
UPDATE yijing_line_dictum SET interpretation='丧羊于易，位不当也。' WHERE name='LineDictum_34_5';
UPDATE yijing_line_dictum SET interpretation='不能退不能遂，不祥也。艰则吉，咎不长也。' WHERE name='LineDictum_34_6';
UPDATE yijing_line_dictum SET interpretation='晋如摧如，独行正也。裕无咎，未受命也。' WHERE name='LineDictum_35_1';
UPDATE yijing_line_dictum SET interpretation='受兹介福，以中正也。' WHERE name='LineDictum_35_2';
UPDATE yijing_line_dictum SET interpretation='众允之志，上行也。' WHERE name='LineDictum_35_3';
UPDATE yijing_line_dictum SET interpretation='鼫鼠贞厉，位不当也。' WHERE name='LineDictum_35_4';
UPDATE yijing_line_dictum SET interpretation='失得勿恤，往有庆也。' WHERE name='LineDictum_35_5';
UPDATE yijing_line_dictum SET interpretation='维用伐邑，道未光也。' WHERE name='LineDictum_35_6';
UPDATE yijing_line_dictum SET interpretation='君子于行，义不食也。' WHERE name='LineDictum_36_1';
UPDATE yijing_line_dictum SET interpretation='六二之吉，顺以则也。' WHERE name='LineDictum_36_2';
UPDATE yijing_line_dictum SET interpretation='南狩之志，乃大得也。' WHERE name='LineDictum_36_3';
UPDATE yijing_line_dictum SET interpretation='入于左腹，获心意也。' WHERE name='LineDictum_36_4';
UPDATE yijing_line_dictum SET interpretation='箕子之贞，明不可息也。' WHERE name='LineDictum_36_5';
UPDATE yijing_line_dictum SET interpretation='初登于天，照四国也。后入于地，失则也。' WHERE name='LineDictum_36_6';
UPDATE yijing_line_dictum SET interpretation='闲有家，志未变也。' WHERE name='LineDictum_37_1';
UPDATE yijing_line_dictum SET interpretation='六二之吉，顺以巽也。' WHERE name='LineDictum_37_2';
UPDATE yijing_line_dictum SET interpretation='家人嗃嗃，未失也。妇子嘻嘻，失家节也。' WHERE name='LineDictum_37_3';
UPDATE yijing_line_dictum SET interpretation='富家大吉，顺在位也。' WHERE name='LineDictum_37_4';
UPDATE yijing_line_dictum SET interpretation='王假有家，交相爱也。' WHERE name='LineDictum_37_5';
UPDATE yijing_line_dictum SET interpretation='威如之吉，反身之谓也。' WHERE name='LineDictum_37_6';
UPDATE yijing_line_dictum SET interpretation='见恶人，以辟咎也。' WHERE name='LineDictum_38_1';
UPDATE yijing_line_dictum SET interpretation='遇主于巷，未失道也。' WHERE name='LineDictum_38_2';
UPDATE yijing_line_dictum SET interpretation='见舆曳，位不当也。无初有终，遇刚也。' WHERE name='LineDictum_38_3';
UPDATE yijing_line_dictum SET interpretation='交孚无咎，志行也。' WHERE name='LineDictum_38_4';
UPDATE yijing_line_dictum SET interpretation='厥宗噬肤，往有庆也。' WHERE name='LineDictum_38_5';
UPDATE yijing_line_dictum SET interpretation='遇雨之吉，群疑亡也。' WHERE name='LineDictum_38_6';
UPDATE yijing_line_dictum SET interpretation='往蹇来誉，宜待也。' WHERE name='LineDictum_39_1';
UPDATE yijing_line_dictum SET interpretation='王臣蹇蹇，终无尤也。' WHERE name='LineDictum_39_2';
UPDATE yijing_line_dictum SET interpretation='往蹇来反，内喜之也。' WHERE name='LineDictum_39_3';
UPDATE yijing_line_dictum SET interpretation='往蹇来连，当位实也。' WHERE name='LineDictum_39_4';
UPDATE yijing_line_dictum SET interpretation='大蹇朋来，以中节也。' WHERE name='LineDictum_39_5';
UPDATE yijing_line_dictum SET interpretation='往蹇来硕，志在内也。利见大人，以从贵也。' WHERE name='LineDictum_39_6';
UPDATE yijing_line_dictum SET interpretation='刚柔之际，义无咎也。' WHERE name='LineDictum_40_1';
UPDATE yijing_line_dictum SET interpretation='九二贞吉，得中道也。' WHERE name='LineDictum_40_2';
UPDATE yijing_line_dictum SET interpretation='负且乘，亦可丑也。自我致戎，又谁咎也。' WHERE name='LineDictum_40_3';
UPDATE yijing_line_dictum SET interpretation='解而拇，未当位也。' WHERE name='LineDictum_40_4';
UPDATE yijing_line_dictum SET interpretation='君子有解，小人退也。' WHERE name='LineDictum_40_5';
UPDATE yijing_line_dictum SET interpretation='公用射隼，以解悖也。' WHERE name='LineDictum_40_6';
UPDATE yijing_line_dictum SET interpretation='已事遄往，尚合志也。' WHERE name='LineDictum_41_1';
UPDATE yijing_line_dictum SET interpretation='九二利贞，中以为志也。' WHERE name='LineDictum_41_2';
UPDATE yijing_line_dictum SET interpretation='一人行，三则疑也。' WHERE name='LineDictum_41_3';
UPDATE yijing_line_dictum SET interpretation='损其疾，亦可喜也。' WHERE name='LineDictum_41_4';
UPDATE yijing_line_dictum SET interpretation='六五元吉，自上祐也。' WHERE name='LineDictum_41_5';
UPDATE yijing_line_dictum SET interpretation='弗损益之，大得志也。' WHERE name='LineDictum_41_6';
UPDATE yijing_line_dictum SET interpretation='元吉无咎，下不厚事也。' WHERE name='LineDictum_42_1';
UPDATE yijing_line_dictum SET interpretation='或益之，自外来也。' WHERE name='LineDictum_42_2';
UPDATE yijing_line_dictum SET interpretation='益用凶事，固有之也。' WHERE name='LineDictum_42_3';
UPDATE yijing_line_dictum SET interpretation='告公从，以益志也。' WHERE name='LineDictum_42_4';
UPDATE yijing_line_dictum SET interpretation='有孚惠心，勿问之矣。惠我德，大得志也。' WHERE name='LineDictum_42_5';
UPDATE yijing_line_dictum SET interpretation='莫益之，偏辞也。或击之，自外来也。' WHERE name='LineDictum_42_6';
UPDATE yijing_line_dictum SET interpretation='不胜而往，咎也。' WHERE name='LineDictum_43_1';
UPDATE yijing_line_dictum SET interpretation='有戎勿恤，得中道也。' WHERE name='LineDictum_43_2';
UPDATE yijing_line_dictum SET interpretation='君子夬夬，终无咎也。' WHERE name='LineDictum_43_3';
UPDATE yijing_line_dictum SET interpretation='其行次且，位不当也。闻言不信，聪不明也。' WHERE name='LineDictum_43_4';
UPDATE yijing_line_dictum SET interpretation='中行无咎，中未光也。' WHERE name='LineDictum_43_5';
UPDATE yijing_line_dictum SET interpretation='无号之凶，终不可长也。' WHERE name='LineDictum_43_6';
UPDATE yijing_line_dictum SET interpretation='系于金柅，柔道牵也。' WHERE name='LineDictum_44_1';
UPDATE yijing_line_dictum SET interpretation='包有鱼，义不及宾也。' WHERE name='LineDictum_44_2';
UPDATE yijing_line_dictum SET interpretation='其行次且，行未牵也。' WHERE name='LineDictum_44_3';
UPDATE yijing_line_dictum SET interpretation='无鱼之凶，远民也。' WHERE name='LineDictum_44_4';
UPDATE yijing_line_dictum SET interpretation='九五含章，中正也。有陨自天，志不舍命也。' WHERE name='LineDictum_44_5';
UPDATE yijing_line_dictum SET interpretation='姤其角，上穷吝也。' WHERE name='LineDictum_44_6';
UPDATE yijing_line_dictum SET interpretation='乃乱乃萃，其志乱也。' WHERE name='LineDictum_45_1';
UPDATE yijing_line_dictum SET interpretation='引吉无咎，中未变也。' WHERE name='LineDictum_45_2';
UPDATE yijing_line_dictum SET interpretation='往无咎，上巽也。' WHERE name='LineDictum_45_3';
UPDATE yijing_line_dictum SET interpretation='大吉无咎，位不当也。' WHERE name='LineDictum_45_4';
UPDATE yijing_line_dictum SET interpretation='萃有位，志未光也。' WHERE name='LineDictum_45_5';
UPDATE yijing_line_dictum SET interpretation='赍咨涕洟，未安上也。' WHERE name='LineDictum_45_6';
UPDATE yijing_line_dictum SET interpretation='允升大吉，上合志也。' WHERE name='LineDictum_46_1';
UPDATE yijing_line_dictum SET interpretation='九二之孚，有喜也。' WHERE name='LineDictum_46_2';
UPDATE yijing_line_dictum SET interpretation='升虚邑，无所疑也。' WHERE name='LineDictum_46_3';
UPDATE yijing_line_dictum SET interpretation='王用亨于岐山，顺事也。' WHERE name='LineDictum_46_4';
UPDATE yijing_line_dictum SET interpretation='贞吉升阶，大得志也。' WHERE name='LineDictum_46_5';
UPDATE yijing_line_dictum SET interpretation='冥升在上，消不富也。' WHERE name='LineDictum_46_6';
UPDATE yijing_line_dictum SET interpretation='入于幽谷，幽不明也。' WHERE name='LineDictum_47_1';
UPDATE yijing_line_dictum SET interpretation='困于酒食，中有庆也。' WHERE name='LineDictum_47_2';
UPDATE yijing_line_dictum SET interpretation='据于蒺藜，乘刚也。入于其宫不见其妻，不祥也。' WHERE name='LineDictum_47_3';
UPDATE yijing_line_dictum SET interpretation='来徐徐，志在下也。虽不当位，有与也。' WHERE name='LineDictum_47_4';
UPDATE yijing_line_dictum SET interpretation='劓刖，志未得也。乃徐有说，以中直也。利用祭祀，受福也。' WHERE name='LineDictum_47_5';
UPDATE yijing_line_dictum SET interpretation='困于葛藟，未当也。动悔有悔，吉行也。' WHERE name='LineDictum_47_6';
UPDATE yijing_line_dictum SET interpretation='井泥不食，下也。旧井无禽，时舍也。' WHERE name='LineDictum_48_1';
UPDATE yijing_line_dictum SET interpretation='井谷射鲋，无与也。' WHERE name='LineDictum_48_2';
UPDATE yijing_line_dictum SET interpretation='井渫不食，行恻也。求王明，受福也。' WHERE name='LineDictum_48_3';
UPDATE yijing_line_dictum SET interpretation='井甃无咎，修井也。' WHERE name='LineDictum_48_4';
UPDATE yijing_line_dictum SET interpretation='寒泉之食，中正也。' WHERE name='LineDictum_48_5';
UPDATE yijing_line_dictum SET interpretation='元吉在上，大成也。' WHERE name='LineDictum_48_6';
UPDATE yijing_line_dictum SET interpretation='巩用黄牛，不可以有为也。' WHERE name='LineDictum_49_1';
UPDATE yijing_line_dictum SET interpretation='己日革之，行有嘉也。' WHERE name='LineDictum_49_2';
UPDATE yijing_line_dictum SET interpretation='革言三就，又何之矣。' WHERE name='LineDictum_49_3';
UPDATE yijing_line_dictum SET interpretation='改命之吉，信志也。' WHERE name='LineDictum_49_4';
UPDATE yijing_line_dictum SET interpretation='大人虎变，其文炳也。' WHERE name='LineDictum_49_5';
UPDATE yijing_line_dictum SET interpretation='君子豹变，其文蔚也。小人革面，顺以从君也。' WHERE name='LineDictum_49_6';
UPDATE yijing_line_dictum SET interpretation='鼎颠趾，未悖也。利出否，以从贵也。' WHERE name='LineDictum_50_1';
UPDATE yijing_line_dictum SET interpretation='鼎有实，慎所之也。我仇有疾，终无尤也。' WHERE name='LineDictum_50_2';
UPDATE yijing_line_dictum SET interpretation='鼎耳革，失其义也。' WHERE name='LineDictum_50_3';
UPDATE yijing_line_dictum SET interpretation='覆公餗，信如何也。' WHERE name='LineDictum_50_4';
UPDATE yijing_line_dictum SET interpretation='鼎黄耳，中以为实也。' WHERE name='LineDictum_50_5';
UPDATE yijing_line_dictum SET interpretation='玉铉在上，刚柔节也。' WHERE name='LineDictum_50_6';
UPDATE yijing_line_dictum SET interpretation='震来虩虩，恐致福也。笑言哑哑，后有则也。' WHERE name='LineDictum_51_1';
UPDATE yijing_line_dictum SET interpretation='震来厉，乘刚也。' WHERE name='LineDictum_51_2';
UPDATE yijing_line_dictum SET interpretation='震苏苏，位不当也。' WHERE name='LineDictum_51_3';
UPDATE yijing_line_dictum SET interpretation='震遂泥，未光也。' WHERE name='LineDictum_51_4';
UPDATE yijing_line_dictum SET interpretation='震往来厉，危行也。其事在中，大无丧也。' WHERE name='LineDictum_51_5';
UPDATE yijing_line_dictum SET interpretation='震索索，中未得也。虽凶无咎，畏邻戒也。' WHERE name='LineDictum_51_6';
UPDATE yijing_line_dictum SET interpretation='艮其趾，未失正也。' WHERE name='LineDictum_52_1';
UPDATE yijing_line_dictum SET interpretation='不拯其随，未退听也。' WHERE name='LineDictum_52_2';
UPDATE yijing_line_dictum SET interpretation='艮其限，危薰心也。' WHERE name='LineDictum_52_3';
UPDATE yijing_line_dictum SET interpretation='艮其身，止诸躬也。' WHERE name='LineDictum_52_4';
UPDATE yijing_line_dictum SET interpretation='艮其辅，以中正也。' WHERE name='LineDictum_52_5';
UPDATE yijing_line_dictum SET interpretation='敦艮之吉，以厚终也。' WHERE name='LineDictum_52_6';
UPDATE yijing_line_dictum SET interpretation='小子之厉，义无咎也。' WHERE name='LineDictum_53_1';
UPDATE yijing_line_dictum SET interpretation='饮食衎衎，不素饱也。' WHERE name='LineDictum_53_2';
UPDATE yijing_line_dictum SET interpretation='夫征不复，离群丑也。妇孕不育，失其道也。利用御寇，顺相保也。' WHERE name='LineDictum_53_3';
UPDATE yijing_line_dictum SET interpretation='或得其桷，顺以巽也。' WHERE name='LineDictum_53_4';
UPDATE yijing_line_dictum SET interpretation='终莫之胜吉，得所愿也。' WHERE name='LineDictum_53_5';
UPDATE yijing_line_dictum SET interpretation='其羽可用为仪吉，不可乱也。' WHERE name='LineDictum_53_6';
UPDATE yijing_line_dictum SET interpretation='归妹以娣，以恒也。跛能履吉，相承也。' WHERE name='LineDictum_54_1';
UPDATE yijing_line_dictum SET interpretation='利幽人之贞，未变常也。' WHERE name='LineDictum_54_2';
UPDATE yijing_line_dictum SET interpretation='归妹以须，未当也。' WHERE name='LineDictum_54_3';
UPDATE yijing_line_dictum SET interpretation='愆期之志，有待而行也。' WHERE name='LineDictum_54_4';
UPDATE yijing_line_dictum SET interpretation='帝乙归妹，不如其娣之袂良也。其位在中，以贵行也。' WHERE name='LineDictum_54_5';
UPDATE yijing_line_dictum SET interpretation='上六无实，承虚筐也。' WHERE name='LineDictum_54_6';
UPDATE yijing_line_dictum SET interpretation='虽旬无咎，过旬灾也。' WHERE name='LineDictum_55_1';
UPDATE yijing_line_dictum SET interpretation='有孚发若，信以发志也。' WHERE name='LineDictum_55_2';
UPDATE yijing_line_dictum SET interpretation='丰其沛，不可大事也。折其右肱，终不可用也。' WHERE name='LineDictum_55_3';
UPDATE yijing_line_dictum SET interpretation='丰其蔀，位不当也。日中见斗，幽不明也。遇其夷主，吉行也。' WHERE name='LineDictum_55_4';
UPDATE yijing_line_dictum SET interpretation='六五之吉，有庆也。' WHERE name='LineDictum_55_5';
UPDATE yijing_line_dictum SET interpretation='丰其屋，天际翔也。窥其户，阒其无人，自藏也。' WHERE name='LineDictum_55_6';
UPDATE yijing_line_dictum SET interpretation='旅琐琐，志穷灾也。' WHERE name='LineDictum_56_1';
UPDATE yijing_line_dictum SET interpretation='得童仆贞，终无尤也。' WHERE name='LineDictum_56_2';
UPDATE yijing_line_dictum SET interpretation='旅焚其次，亦以伤矣。以旅与下，其义丧也。' WHERE name='LineDictum_56_3';
UPDATE yijing_line_dictum SET interpretation='旅于处，未得位也。得其资斧，心未快也。' WHERE name='LineDictum_56_4';
UPDATE yijing_line_dictum SET interpretation='终以誉命，上逮也。' WHERE name='LineDictum_56_5';
UPDATE yijing_line_dictum SET interpretation='以旅在上，其义焚也。丧牛于易，终莫之闻也。' WHERE name='LineDictum_56_6';
UPDATE yijing_line_dictum SET interpretation='进退，志疑也。利武人之贞，志治也。' WHERE name='LineDictum_57_1';
UPDATE yijing_line_dictum SET interpretation='纷若之吉，得中也。' WHERE name='LineDictum_57_2';
UPDATE yijing_line_dictum SET interpretation='频巽之吝，志穷也。' WHERE name='LineDictum_57_3';
UPDATE yijing_line_dictum SET interpretation='田获三品，有功也。' WHERE name='LineDictum_57_4';
UPDATE yijing_line_dictum SET interpretation='九五之吉，位正中也。' WHERE name='LineDictum_57_5';
UPDATE yijing_line_dictum SET interpretation='巽在床下，上穷也。丧其资斧，正乎凶也。' WHERE name='LineDictum_57_6';
UPDATE yijing_line_dictum SET interpretation='和兑之吉，行未疑也。' WHERE name='LineDictum_58_1';
UPDATE yijing_line_dictum SET interpretation='孚兑之吉，信志也。' WHERE name='LineDictum_58_2';
UPDATE yijing_line_dictum SET interpretation='来兑之凶，位不当也。' WHERE name='LineDictum_58_3';
UPDATE yijing_line_dictum SET interpretation='九四之喜，有庆也。' WHERE name='LineDictum_58_4';
UPDATE yijing_line_dictum SET interpretation='孚于剥，位正当也。' WHERE name='LineDictum_58_5';
UPDATE yijing_line_dictum SET interpretation='上六引兑，未光也。' WHERE name='LineDictum_58_6';
UPDATE yijing_line_dictum SET interpretation='初六之吉，顺也。' WHERE name='LineDictum_59_1';
UPDATE yijing_line_dictum SET interpretation='涣奔其机，得愿也。' WHERE name='LineDictum_59_2';
UPDATE yijing_line_dictum SET interpretation='涣其躬，志在外也。' WHERE name='LineDictum_59_3';
UPDATE yijing_line_dictum SET interpretation='涣其群元吉，光大也。' WHERE name='LineDictum_59_4';
UPDATE yijing_line_dictum SET interpretation='王居无咎，正位也。' WHERE name='LineDictum_59_5';
UPDATE yijing_line_dictum SET interpretation='涣其血，远害也。' WHERE name='LineDictum_59_6';
