UPDATE yijing_line_dictum SET interpretation='翰音登于天，何可长也。' WHERE name='LineDictum_61_6';
UPDATE yijing_line_dictum SET interpretation='飞鸟以凶，不可如何也。' WHERE name='LineDictum_62_1';
